'use strict';
function mountAnatomyViewTools(host){
 const svg=host.querySelector(':scope > svg');if(!svg)return;host.tabIndex=0;host.setAttribute('aria-label','电路阅读区域，可滚动查看完整电路');
 const bar=document.createElement('div');bar.className='an-diagram-zoom';bar.setAttribute('aria-label','二维结构图缩放');bar.innerHTML='<span>二维结构图</span><button data-zoom-readable>大字阅读</button><button data-zoom-fit>全图概览</button><button data-zoom-native>原始大小</button><button data-zoom-out aria-label="缩小结构图">−</button><button data-zoom-in aria-label="放大结构图">＋</button><small aria-live="polite">自动布局 · 放大后可滚动查看细节</small>';host.before(bar);
 const status=bar.querySelector('small'),nativeWidth=svg.viewBox.baseVal.width;
 function size(width){width=Math.min(nativeWidth*3,Math.max(300,width));svg.style.width=width+'px';svg.style.minWidth=width+'px';status.textContent=Math.round(width/nativeWidth*100)+'% · 可横向滚动查看';}
 bar.querySelector('[data-zoom-fit]').onclick=()=>{svg.style.width='100%';svg.style.minWidth='0';host.scrollLeft=0;status.textContent='适应宽度 · 图形保持原比例'};
 const textSizes=[...svg.querySelectorAll('text')].filter(n=>getComputedStyle(n).display!=='none').map(n=>parseFloat(getComputedStyle(n).fontSize)).filter(v=>v>0);
 const readableScale=Math.max(1,16/Math.min(...textSizes,11));
 bar.querySelector('[data-zoom-readable]').onclick=()=>{size(nativeWidth*readableScale);const first=svg.querySelector('.sc-components>[data-diagram-part]'),box=first?.getBoundingClientRect(),frame=host.getBoundingClientRect();if(box){host.scrollLeft+=box.left-frame.left-40;host.scrollTop+=box.top-frame.top-60}else host.scrollLeft=0;status.textContent='大字阅读 · 最小设计字号约16px · 可上下左右滚动；全图概览可查看布局';};
 bar.querySelector('[data-zoom-native]').onclick=()=>size(nativeWidth);
 bar.querySelector('[data-zoom-native]').click();
 bar.querySelector('[data-zoom-in]').onclick=()=>size(svg.getBoundingClientRect().width*1.25);
 bar.querySelector('[data-zoom-out]').onclick=()=>size(svg.getBoundingClientRect().width/1.25);
}

function anatomyCacheLens(b,s){
 if(!['cache','tag'].includes(b.lab))return '';
 const address=s.addr&255,index=(address>>>1)&3,tag=address>>>3,entry=s.cache[index],hit=!!entry.valid&&entry.tag===tag;
 return '<section class="an-cache-lens"><h4>地址如何找到缓存行</h4><p>8位地址 '+address+' = 0x'+address.toString(16).toUpperCase().padStart(2,'0')+'</p><div class="an-cache-address">'+Array.from({length:8},(_,i)=>{const bit=7-i,group=bit>=3?'tag':bit>=1?'index':'offset';return '<button data-cache-address-bit="'+bit+'" class="cache-'+group+'" aria-label="地址位'+bit+'，'+group+'，当前'+((address>>>bit)&1)+'"><small>'+bit+'</small>'+((address>>>bit)&1)+'</button>'}).join('')+'</div><div class="an-cache-fields"><span class="cache-tag">TAG '+tag+'</span><span class="cache-index">INDEX '+index+'</span><span class="cache-offset">OFFSET '+(address&1)+'</span></div><p class="an-cache-result" role="status">'+(hit?'命中：有效位为1，而且保存tag与请求tag相同':entry.valid?'冲突缺失：选中了行'+index+'，但旧tag='+entry.tag+'，请求tag='+tag:'冷缺失：选中了行'+index+'，但有效位为0')+'</p><ol class="an-cache-rows">'+s.cache.map((row,i)=>'<li data-cache-line="'+i+'" '+(i===index?'aria-current="true"':'')+'><b>行 '+i+'</b><span>V='+row.valid+'</span><span>TAG='+row.tag+'</span><span>回填样本='+row.data+'</span></li>').join('')+'</ol><p>点击“从下级回填这一行”后：行'+index+'保存tag='+tag+'、V=1、样本='+s.data+'。'+(entry.valid&&entry.tag!==tag?'原tag='+entry.tag+'被替换。':'')+'</p><div class="an-cache-presets">'+[[0,'地址0'],[1,'地址1 · 同块'],[8,'地址8 · 同行冲突'],[2,'地址2 · 另一行']].map(([a,label])=>'<button data-cache-address="'+a+'">'+label+'</button>').join('')+'</div><small>本层只演示4行、每块2字节的标签查找；“回填样本”是单个保存值，不代表完整数据块。OFFSET改变不影响命中判断。没有脏位、写回总线或实际访存时延。</small></section>';
}

function anatomyMemoryHierarchyLens(b,s){
 if(b.id!=='memorySystem')return '';
 const index=(s.addr>>>1)&3,tag=s.addr>>>3,offset=s.addr&1,line=s.memoryCache[index],hit=!!line.valid&&line.tag===tag,last=s.memoryAccess,hex=v=>v.toString(16).toUpperCase().padStart(2,'0');
 const recent=!last?'尚未执行读写；改变地址只改变候选，不会自动访问。':last.kind==='write'?'最近执行：后备内存['+last.address+'] ← '+last.value+'；缓存行'+last.index+'失效。上次读取的返回值未被这次写入覆盖。':'最近读取地址 '+last.address+'：'+(last.hit?'命中，从缓存取字节':'缺失，回填两个字节 ['+last.bytes.join(', ')+']')+' → 返回 '+last.value+'。';
 return '<section class="an-memory-hierarchy"><h4>一次访问：查找 → 取块 → 选字节</h4><div class="an-hierarchy-address-bits" aria-label="四位地址：tag一位、index两位、offset一位">'+[3,2,1,0].map(bit=>{const role=bit===3?'tag':bit===0?'offset':'index';return '<button data-hierarchy-bit="'+bit+'" class="cache-'+role+'" aria-label="翻转地址bit'+bit+'，'+role+'，权重'+(1<<bit)+'，当前'+((s.addr>>>bit)&1)+'"><small>bit'+bit+' · '+role+'</small><b>'+((s.addr>>>bit)&1)+'</b><small>权重 '+(1<<bit)+'</small></button>'}).join('')+'</div><p data-hierarchy-address-explain>地址 '+s.addr+' = TAG '+tag+' × 8 + INDEX '+index+' × 2 + OFFSET '+offset+'。bit0只选块内字节；bit1/2换行；bit3保留行号但换tag，可能发生冲突。翻转只准备请求，不执行访问。</p><div class="an-memory-read-result" data-memory-read-result>'+(s.memoryLastRead?'上次读取：地址 '+s.memoryLastRead.address+' → '+s.memoryLastRead.value+'（0x'+hex(s.memoryLastRead.value)+'，'+(s.memoryLastRead.hit?'命中':'缺失回填')+'）。当前请求地址 '+s.addr+'；改变请求或执行写入不会替换这份读取结果。':'尚未产生读取结果。输出初值0不代表已经读到0；请执行一次访问。')+'</div><div class="an-hierarchy-route"><b>请求地址 '+s.addr+'</b><span>TAG '+tag+' · 行 '+index+' · 偏移 '+offset+'</span><b>'+(hit?'当前候选命中':'当前候选缺失')+'</b><span>'+(hit?'缓存字节['+offset+'] = '+line.bytes[offset]:'下一次读取将回填后备地址 '+(s.addr&~1)+'、'+((s.addr&~1)+1))+'</span></div><p data-hierarchy-recent role="status">'+recent+'</p>'+anatomyMemoryReadReplay(s)+'<h5>四行缓存 · 每行两个字节</h5><ol class="an-hierarchy-lines">'+s.memoryCache.map((r,i)=>'<li data-hierarchy-line="'+i+'" '+(i===index?'aria-current="true"':'')+'><b>行'+i+' · V='+r.valid+' · TAG='+r.tag+'</b><div>'+r.bytes.map((v,j)=>'<span '+(i===index&&j===offset?'class="selected"':'')+'>偏移'+j+'：'+hex(v)+'</span>').join('')+'</div><small>'+(r.valid?'对应后备地址 '+((r.tag<<3)|(i<<1))+'…'+(((r.tag<<3)|(i<<1))+1):'无效，保存的旧字节不能作为命中数据')+'</small></li>').join('')+'</ol><h5>后备内存 · 16字节，点击选地址</h5><div class="an-hierarchy-memory">'+s.mainMem.map((v,a)=>'<button data-hierarchy-address="'+a+'" aria-pressed="'+(a===s.addr)+'" '+((a&~1)===(s.addr&~1)?'class="same-block"':'')+'><small>@'+a+'</small>'+hex(v)+'</button>').join('')+'</div><small>先填写“待写字节”，点“写后备存储并失效缓存”，再点“访问 / 缺失回填”。写操作直接更新后备内存，并保守失效该索引行（即使旧tag不同）；不是写回缓存。访问是一次教学操作，不表示真实访存周期。此存储实验独立于CPU程序。</small></section>';
}

function anatomyDRAMLens(b,s){
 if(!['dram','dramcell'].includes(b.id))return '';
 const value=s.chargeValid?s.chargeBit:'X',age=Math.min(8,s.chargeAge),names={write:'写入',refresh:'刷新',wait:'等待'};
 return '<section class="an-dram-lens"><h4>保存信息，需要定期恢复</h4><svg viewBox="0 0 280 145" role="img" aria-label="字线'+s.enable+'，保存位'+value+'，已等待'+s.chargeAge+'步"><path d="M20 72H95M125 72H205V95M186 95H224M186 104H224M205 104V123" fill="none" stroke="#87c8d7" stroke-width="3"/><path d="M95 62V82M125 62V82M110 35V58" fill="none" stroke="#cfacff" stroke-width="3"/>'+ (s.enable?'<path d="M95 72H125" stroke="#f3d78e" stroke-width="4"/>':'')+'<text x="15" y="57" fill="#c9e6ed" font-size="12">BL</text><text x="72" y="25" fill="#d6b9ff" font-size="12">WL='+s.enable+'</text><text x="182" y="57" fill="#f4d78b" font-size="18">Q='+value+'</text><text x="165" y="140" fill="#adc8d3" font-size="10">参考极板</text></svg><p>保存位：<b>'+value+'</b> · 位线观察：<b>'+(s.enable?value:'Z')+'</b>（'+(s.enable?'字线打开':'字线关闭，单元不驱动位线')+'）</p><div class="an-dram-age" aria-label="已等待'+age+'个教学步骤，共8步期限">'+Array.from({length:8},(_,i)=>'<span class="'+(i<age?'elapsed':'remaining')+'">'+(i+1)+'</span>').join('')+'</div><p data-dram-retention>'+(!s.chargeValid?'保持期限已过：结果未知X；刷新不能推断丢失的原位。':s.chargeAge>=6?'接近期限：还可等待'+(8-s.chargeAge)+'步，刷新能保留当前位并把等待计数归零。':'已等待'+s.chargeAge+'步，还可等待'+(8-s.chargeAge)+'步。')+'</p><p>写入候选：'+(s.enable?'点写入将保存 '+s.a+'，恢复有效并归零计数。':'WL=0，写入不可用；先打开字线。')+'</p><details><summary>最近16次实际操作</summary><ol>'+ (s.dramTrace||[]).map(r=>'<li>'+names[r.action]+(r.applied?'':'（未生效）')+' → Q='+r.value+'，等待='+r.age+'，WL='+r.wl+'</li>').join('')+'</ol></details><small>八格表示人为缩小的等待期限，不是电压、电荷量或真实时间。保存0和1都需要刷新；X是信息未知，不等于0。该模型没有破坏性读取与感测恢复电路。</small></section>';
}

function anatomyFlashLens(b,s){
 if(b.id!=='flash')return '';
 const saved=s.flashBytes[s.addr],after=saved&s.data,blocked=(~saved&s.data)&255,hex=v=>'0x'+v.toString(16).toUpperCase().padStart(2,'0');
 return '<section class="an-flash-lens"><h4>编程候选 = 保存值 AND 编程数据</h4><p>地址 '+s.addr+'：'+hex(saved)+' AND '+hex(s.data)+' → '+hex(after)+'</p><div class="an-flash-bits"><span>位</span>'+Array.from({length:8},(_,i)=>'<b>'+(7-i)+'</b>').join('')+'<span>保存</span>'+Array.from({length:8},(_,i)=>'<span>'+((saved>>>(7-i))&1)+'</span>').join('')+'<span>待写</span>'+Array.from({length:8},(_,i)=>'<button data-flash-data-bit="'+(7-i)+'" aria-label="编程数据位'+(7-i)+'，当前'+((s.data>>>(7-i))&1)+'">'+((s.data>>>(7-i))&1)+'</button>').join('')+'<span>候选</span>'+Array.from({length:8},(_,i)=>'<b class="'+((blocked>>>(7-i))&1?'blocked':'')+'">'+((after>>>(7-i))&1)+'</b>').join('')+'</div><p data-flash-explain role="status">'+(blocked?'标黄位要求0→1，编程无法完成；这些位将保持0。要恢复1，必须擦除整个示例块。':'本次编程可以得到所需字节；候选尚未保存，需点击编程。')+'</p><div class="an-flash-presets"><button data-flash-data="15">待写0F</button><button data-flash-data="240">待写F0</button><button data-flash-data="255">待写FF</button><button data-flash-data="0">待写00</button></div><h5>8字节示例擦除块</h5><div class="an-flash-array">'+s.flashBytes.map((v,a)=>'<button data-flash-address="'+a+'" aria-pressed="'+(a===s.addr)+'"><small>@'+a+'</small>'+hex(v)+'</button>').join('')+'</div><small>改变待写位不改变保存值。编程只影响选中字节；擦除同时把8个字节恢复FF。此页不模拟真实页大小、忙碌等待、磨损、写保护或掉电中断。</small></section>';
}

function anatomyUARTLens(b,s){
 if(b.id==='rx')return anatomyIdealRXLens(s);
 if(b.lab!=='uart')return '';
 const frame=anatomyUARTFrame(s),busy=s.uartIndex>=0,byte=busy?(s.uartByte??s.byte):s.byte,labels=['START',...Array.from({length:8},(_,i)=>'d'+i),'STOP'],x=i=>35+i*34,y=v=>v?40:78;
 let path='M15 40H35';frame.forEach((v,i)=>{path+='V'+y(v)+'H'+x(i+1)});path+='V40H395';
 return '<section class="an-uart-lens"><h4>8N1：低位先发的一帧</h4><p>待发字节 '+s.byte+' · '+(busy?'当前帧已捕获 '+byte:'空闲，下一次推进捕获待发字节')+'</p><div class="an-uart-pending">'+Array.from({length:8},(_,i)=>'<button data-uart-pending-bit="'+(7-i)+'" aria-label="待发字节位'+(7-i)+'"><small>d'+(7-i)+'</small>'+((s.byte>>>(7-i))&1)+'</button>').join('')+'</div><div class="an-uart-examples"><button data-uart-pending-byte="65">字符A · 65</button><button data-uart-pending-byte="85">交替位 · 85</button><button data-uart-pending-byte="0">全0</button><button data-uart-pending-byte="255">全1</button></div><div class="an-uart-frame"><svg viewBox="0 0 410 126" role="img" aria-label="'+(busy?'当前发送':'下一帧候选')+'，字节'+byte+'，低位先发">'+(busy?'<rect x="'+x(s.uartIndex)+'" y="14" width="34" height="102" fill="#f4d681" fill-opacity=".16"/>':'')+'<path d="'+path+'" fill="none" stroke="#e9cb76" stroke-width="2"/>'+frame.map((v,i)=>'<text x="'+(x(i)+17)+'" y="104" text-anchor="middle" fill="#afc9d3" font-size="8">'+labels[i]+'</text><text x="'+(x(i)+17)+'" y="25" text-anchor="middle" fill="#e9dba9" font-size="11">'+v+'</text>').join('')+'</svg></div><p data-uart-frame-status role="status">'+(busy?'正在发送 '+labels[s.uartIndex]+'，TX='+frame[s.uartIndex]+'；下一次推进'+(s.uartIndex===9?'回到空闲，TX保持1':'进入 '+labels[s.uartIndex+1]):'空闲 TX=1；点击“下一发送位”进入START=0')+'</p><small>修改待发字节只影响下一帧，忙时当前帧保持。图中每格为一个理想位周期：'+(1e6/s.baud).toFixed(3)+' μs；按钮推进不等于真实墙钟时间。采用8数据位、无校验、1停止位，未模拟分频误差或异步接收采样。</small></section>';
}

function anatomyUARTLoopStart(s,badStop=false){
 s.uartLoop={byte:s.byte,badStop,tx:{byte:s.byte,uartByte:s.byte,uartIndex:-1,ticks:0},rx:{a:1,rxPhase:-1,rxData:0,rxValid:0,rxError:0,ticks:0},samples:[]};
}
function anatomyUARTLoopStep(s){
 const loop=s.uartLoop;if(!loop||loop.samples.length>=10)return false;
 anatomyAdvance('tx',loop.tx);const position=loop.tx.uartIndex,tx=anatomyUARTFrame(loop.tx)[position],wire=loop.badStop&&position===9?0:tx;
 loop.rx.a=wire;anatomyAdvance('rx',loop.rx);
 loop.samples.push({position,tx,wire,data:loop.rx.rxData,valid:loop.rx.rxValid,error:loop.rx.rxError});return true;
}
function anatomyUARTLoopMarkup(b,s){
 if(b.lab!=='uart'&&b.id!=='rx')return '';
 const loop=s.uartLoop,labels=['START',...Array.from({length:8},(_,i)=>'d'+i),'STOP'],rx=loop?.rx;
 return '<section class="an-uart-loop"><h4>TX → RX · 逐位回环</h4><p>使用当前待发字节 '+s.byte+' 建立一组独立收发实验；准备会重置本组发送器、接收器与记录。</p><button data-uart-loop-start="normal">准备正常帧</button><button data-uart-loop-start="bad">准备错误停止位</button><button data-uart-loop-step '+(!loop||loop.samples.length>=10?'disabled':'')+'>发送并采样下一位</button>'+(loop?'<p data-uart-loop-status role="status">已采样 '+loop.samples.length+' / 10 · 发送字节 '+loop.byte+' · 接收累积 '+rx.rxData+' · valid='+rx.rxValid+' · 帧错误='+rx.rxError+'</p><div class="an-uart-loop-wire"><span>TX '+(loop.samples.at(-1)?.tx??1)+'</span><b>→ '+(loop.badStop?'仅STOP注入0':'理想直连')+' →</b><span>RX '+(loop.samples.at(-1)?.wire??1)+'</span></div><div class="an-uart-loop-bits">'+Array.from({length:8},(_,i)=>{const bit=7-i,seen=loop.samples.some(r=>r.position===bit+1);return '<span><small>d'+bit+'</small>'+(seen?((rx.rxData>>>bit)&1):'·')+'</span>'}).join('')+'</div><ol>'+loop.samples.map(r=>'<li>'+labels[r.position]+': TX='+r.tx+' → RX='+r.wire+'；累积='+r.data+(r.valid?'；接收有效':r.error?'；停止位错误':'')+'</li>').join('')+'</ol>':'<p>尚未准备回环。</p>')+'<small>本组使用现有TX/RX位级模型的独立副本，不推进上方单独发送器。RX每位恰好采样一次；未模拟异步时钟、过采样、噪声或电气连接。接收位组装完成仍需检查停止位，valid才代表完整有效帧。</small></section>';
}

function anatomyFIFOLens(b,s){
 if(b.id!=='fifo')return '';const p=anatomyFIFOPlan(s),order=Array.from({length:s.fifoCount},(_,i)=>s.fifoMem[(s.fifoRead+i)%4]),last=s.fifoLast;
 return '<section class="an-fifo-lens"><h4>物理位置环绕，逻辑顺序不变</h4><div class="an-fifo-ring">'+s.fifoMem.map((v,i)=>{const valid=Array.from({length:s.fifoCount},(_,j)=>(s.fifoRead+j)%4).includes(i);return '<button data-fifo-queue="MEM" data-fifo-slot="'+i+'" class="'+(valid?'occupied':'')+'"><small>位置 '+i+'</small><b>'+v+'</b><span>'+(s.fifoRead===i?'读R ':'')+(s.fifoWrite===i?'写W':'')+'</span><small>'+(valid?'有效排队字节':'空位，旧值无效')+'</small><small>进入此槽存储位 →</small></button>'}).join('')+'</div><p data-fifo-order>队首先读 → '+(order.length?order.join(' → '):'空')+' → 队尾</p><p>占用 '+s.fifoCount+' / 4 · '+(s.fifoCount===0?'EMPTY':s.fifoCount===4?'FULL':'部分占用')+'</p><p data-fifo-next role="status">下一边沿：'+(p.pop?'读出 '+p.value:s.fifoPop?'拒绝读（空）':'无读请求')+'；'+(p.push?'写入 '+s.data:s.fifoPush?'拒绝写（满且无成功读）':'无写请求')+'。</p><p data-fifo-last>'+(last?'上次边沿：'+(last.pop?'读出 '+last.value:'未读出')+'；'+(last.push?'写入 '+last.writeValue:'未写入'):'尚未提交读写边沿。')+'</p><small>R=W时，用占用计数区分空与满。满时同拍读写，先读出旧队首再覆盖对应槽；空时不把新写值旁路为同拍读出。方格里的旧值不等于有效数据。单时钟缩小模型，不代表跨时钟FIFO。</small></section>';
}

function anatomyFIFOTransmitStep(s){
 if(!s.fifoTX)s.fifoTX={tx:{byte:0,uartByte:0,uartIndex:-1,ticks:0},completed:[],trace:[],steps:0};
 const link=s.fifoTX,tx=link.tx;let taken=null;
 if(tx.uartIndex<0){
  if(!s.fifoCount)return false;
  taken=s.fifoMem[s.fifoRead];const push=s.fifoPush,pop=s.fifoPop;s.fifoPush=0;s.fifoPop=1;anatomyAdvance('fifo',s);s.fifoPush=push;s.fifoPop=pop;tx.byte=taken;
 }else if(tx.uartIndex===9){link.completed.push(tx.uartByte);if(link.completed.length>64)link.completed.shift()}
 anatomyAdvance('tx',tx);link.steps++;
 anatomyFIFOReceiveWire(link,tx.uartIndex<0?1:anatomyUARTFrame(tx)[tx.uartIndex]);
 link.trace.push({step:link.steps,index:tx.uartIndex,level:tx.uartIndex<0?1:anatomyUARTFrame(tx)[tx.uartIndex],byte:tx.uartByte,taken});if(link.trace.length>24)link.trace.shift();return true;
}
function anatomyFIFOTransmitMarkup(b,s){
 if(b.id!=='fifo')return '';const link=s.fifoTX,tx=link?.tx,busy=tx&&tx.uartIndex>=0,labels=['START',...Array.from({length:8},(_,i)=>'d'+i),'STOP'];
 return '<section class="an-fifo-tx"><h4>发送FIFO → TX → RX → 接收FIFO</h4><div class="an-fifo-animation"><button data-fifo-play aria-pressed="false">播放完整传输</button><button data-fifo-auto-read aria-pressed="'+!!s.fifoAutoRead+'">应用自动读取：'+(s.fifoAutoRead?'开':'关')+'</button><p data-fifo-play-status role="status">已暂停 · 每250ms演示一个理想位周期，非真实波特率。</p></div><p>排队 '+s.fifoCount+'项 → '+(busy?'发送器忙：字节'+tx.uartByte+'，'+labels[tx.uartIndex]:'发送器空闲')+'</p><button data-fifo-tx-step '+(!s.fifoCount&&!busy?'disabled':'')+'>推进串口一个理想位周期</button><p data-fifo-tx-status role="status">TX='+(busy?anatomyUARTFrame(tx)[tx.uartIndex]:1)+' · 已完成字节：'+(link?.completed.length?link.completed.join(' → '):'无')+'</p><p>'+(busy?'帧内保持当前字节，不继续出队；STOP完整停留后下一步完成。':s.fifoCount?'下一步取出队首并进入START。':'队列为空，等待写入。')+'</p>'+anatomyFIFOReceiverMarkup(link)+'<details><summary>最近24步实际发送记录</summary><ol>'+(link?.trace||[]).map(r=>'<li>步骤'+r.step+'：'+(r.taken!==null?'出队'+r.taken+'；':'')+(r.index<0?'回到空闲，帧完成':labels[r.index]+'，TX='+r.level+'，字节'+r.byte)+'</li>').join('')+'</ol></details><small>这里消费上方同一个FIFO，出队时只提交读请求，不顺带执行上方待写请求。上方手动读写仍可操作同一队列；要入队请提交读写边沿。当前发送字节在独立发送寄存器中保持，FIFO空不等于发送已完成。理想TX位流已接到下方RX；没有自动定时、过采样或硬件流控。</small></section>';
}

function anatomyFIFOReceiveWire(link,level){
 link.rx??={a:1,rxPhase:-1,rxData:0,rxValid:0,rxError:0,ticks:0};
 link.rxFIFO??={fifoMem:Array(4).fill(0),fifoRead:0,fifoWrite:0,fifoCount:0,fifoPush:0,fifoPop:0,fifoLast:null,data:0,ticks:0};
 link.rxOverflow??=0;link.consumed??=[];
 link.rx.a=level;anatomyAdvance('rx',link.rx);
 if(link.rx.rxValid){const q=link.rxFIFO;q.data=link.rx.rxData;q.fifoPush=1;q.fifoPop=0;anatomyAdvance('fifo',q);if(!q.fifoLast.push)link.rxOverflow++;q.fifoPush=0}
}
function anatomyFIFOReceiveRead(s){
 const link=s.fifoTX,q=link?.rxFIFO;if(!q?.fifoCount)return false;
 q.fifoPush=0;q.fifoPop=1;anatomyAdvance('fifo',q);q.fifoPop=0;link.consumed.push(q.fifoLast.value);if(link.consumed.length>64)link.consumed.shift();return true;
}
function anatomyFIFOReceiverMarkup(link){
 const q=link?.rxFIFO,rx=link?.rx,order=q?Array.from({length:q.fifoCount},(_,i)=>q.fifoMem[(q.fifoRead+i)%4]):[];
 return '<section class="an-fifo-rx"><h5>接收端 · 4项缓冲</h5><div class="an-fifo-ring">'+Array.from({length:4},(_,a)=>{const valid=q&&Array.from({length:q.fifoCount},(_,i)=>(q.fifoRead+i)%4).includes(a);return '<button data-fifo-queue="RXQ" data-fifo-slot="'+a+'" class="'+(valid?'occupied':'')+'"><small>位置 '+a+'</small><b>'+(q?.fifoMem[a]??0)+'</b><span>'+((q?.fifoRead??0)===a?'读R ':'')+((q?.fifoWrite??0)===a?'写W':'')+'</span><small>'+(valid?'有效接收字节':'空位，旧值无效')+'</small><small>进入此槽存储位 →</small></button>'}).join('')+'</div><p>接收器累积 '+(rx?.rxData??0)+' · valid='+(rx?.rxValid??0)+'</p><p data-fifo-rx-order>待取字节：'+(order.length?order.join(' → '):'空')+'；占用 '+order.length+' / 4</p><button data-fifo-rx-read '+(!order.length?'disabled':'')+'>应用读取一个接收字节</button><p data-fifo-rx-consumed>应用最近64个已取字节：'+(link?.consumed?.length?link.consumed.join(' → '):'无')+'</p><p data-fifo-rx-text>应用UTF-8解释：'+anatomyFIFOTextResult(link?.consumed||[]).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))+'</p><p data-fifo-rx-overflow>满缓冲丢弃新字节次数：'+(link?.rxOverflow??0)+'</p><small>RX只在停止位正确时请求入队。这里没有流控；接收FIFO满时丢弃新收到的字节，保留原队列。应用读取只消费接收FIFO，不推进串口或发送队列。</small></section>';
}

function anatomyBaudLens(b,s){
 if(b.id!=='baud')return '';
 const divisor=Math.max(1,Math.round(1e8/s.baud)),count=s.ticks%divisor,terminal=count===divisor-1,next=terminal?0:count+1,actual=1e8/divisor,error=(actual/s.baud-1)*100;
 return '<section class="an-baud-lens"><h4>数主时钟，产生位使能</h4><div class="an-baud-route"><b>100 MHz · 每拍10 ns</b><span>↓ 计数0…'+(divisor-1)+'</span><b>每 '+divisor+' 拍产生一次使能</b><span>↓ 实际波特率 '+actual.toFixed(3)+' bit/s</span></div><p>目标 '+s.baud+' → 分频数 round(100000000 / '+s.baud+') = '+divisor+'；误差 '+(error>=0?'+':'')+error.toFixed(4)+'%。</p><div class="an-baud-progress" role="progressbar" aria-label="当前分频计数" aria-valuemin="0" aria-valuemax="'+(divisor-1)+'" aria-valuenow="'+count+'"><span style="width:'+(count/Math.max(1,divisor-1)*100)+'%"></span></div><div class="an-baud-state"><span>保存计数<b>'+count+'</b></span><span>当前终值使能<b>'+(terminal?1:0)+'</b></span><span>下个边沿后<b>'+next+'</b></span></div><p data-baud-decision role="status">'+(terminal?'当前计数已到终值。下一主时钟边沿可消费使能，同时计数回到0。':'还需推进 '+(divisor-1-count)+' 个边沿才到终值；当前使能为0。')+'</p><p>实际位周期 '+(divisor/100).toFixed(5)+' μs；累计 '+s.ticks+' 个主时钟边沿，虚拟经过 '+(s.ticks/100).toFixed(5)+' μs。</p><small>使能是终值比较的组合候选，供下一个主时钟边沿使用；不是把逻辑输出直接当成新时钟。快进按等价边沿数更新最终计数，未记录每个中间状态。切换目标会把本教学计数归零，不代表运行中动态切换的安全协议。准备一帧后，终值使能会实际推进下方发送器。</small></section>';
}

function anatomyBaudTransmitMarkup(b,s){
 if(b.id!=='baud')return '';const link=s.baudTX,tx=link?.tx,labels=['START',...Array.from({length:8},(_,i)=>'d'+i),'STOP'];
 return '<section class="an-baud-tx"><h4>分频使能 → 同步推进UART</h4><p data-baud-tx-status role="status">'+(!link?'先点击“准备一帧”，等待首次终值使能。':link.done?'帧已完成；TX=1，计数器仍可继续运行。':tx.uartIndex<0?'已准备字节'+tx.byte+'，等待首次使能捕获START；TX=1。':'已捕获字节'+tx.uartByte+' · 当前 '+labels[tx.uartIndex]+' · TX='+anatomyUARTFrame(tx)[tx.uartIndex])+'</p><p>只有消费终值使能的主时钟边沿才推进发送位，普通计数边沿保持当前TX。</p><details><summary>实际发生的发送使能记录 · '+(link?.records.length??0)+'次</summary><ol>'+(link?.records||[]).map(r=>'<li>主时钟边沿 '+r.clock+'（'+(r.clock/100).toFixed(3)+' μs）→ '+(r.position<0?'回空闲，帧完成':labels[r.position]+'，TX='+r.level)+'</li>').join('')+'</ol></details><small>准备会归零本页计数并复制待发字节；之后修改待准备字节不改变本帧。首次捕获有一个分频周期的等待，START至STOP结束占10个位周期。快进保留实际发生的使能位置，不画虚构的主时钟电压波形；完成后不自动重发。默认868分频的组合Chisel/Verilog参考已提供下载；其他分频参数与实体时序需另验。</small></section>';
}

function anatomyBaudWaveMarkup(s){
 const link=s.baudTX;if(!link)return '';
 const div=Math.max(1,Math.round(1e8/s.baud)),horizon=div*12,end=Math.min(s.ticks,horizon),left=55,width=612,x=clock=>left+clock/horizon*width,y=v=>v?55:87,labels=['START',...Array.from({length:8},(_,i)=>'d'+i),'STOP'];let path='M'+left+' '+y(1),level=1;
 for(const r of link.records){if(r.clock>end)break;path+='H'+x(r.clock)+'V'+y(r.level);level=r.level}path+='H'+x(end);
 const grid=Array.from({length:13},(_,i)=>'<path d="M'+x(i*div)+' 35V112" stroke="#35515f" stroke-width="1"/>').join('');
 const ticks=[0,3,6,9,12].map(i=>'<text x="'+x(i*div)+'" y="155" text-anchor="middle" fill="#abc5cf" font-size="12">'+(i*div/100).toFixed(2)+'</text>').join('');
 const events=link.records.filter(r=>r.clock<=end).map((r,i)=>'<g data-baud-wave-event="'+i+'" role="button" tabindex="0" aria-pressed="false" aria-label="主时钟边沿'+r.clock+'，'+(r.position<0?'IDLE':labels[r.position])+'，TX='+r.level+'"><title>边沿'+r.clock+'，'+(r.position<0?'IDLE':labels[r.position])+'</title><rect x="'+(x(r.clock)-9)+'" y="34" width="18" height="100" fill="transparent"/><path d="M'+x(r.clock)+' 35V112" stroke="#9dc4bb" stroke-width="1" stroke-dasharray="3 3"/><text x="'+x(r.clock)+'" y="129" text-anchor="middle" fill="#e6d694" font-size="10">'+(r.position<0?'IDLE':labels[r.position])+'</text></g>').join('');
 return '<h3>分频发送波形 · 已执行的TX记录</h3><div class="an-baud-wave-scroll"><svg width="720" height="180" viewBox="0 0 720 180" preserveAspectRatio="xMidYMid meet" role="group" aria-label="虚拟微秒轴的实际TX位流，不是主时钟电压波形"><rect x="'+x(end)+'" y="28" width="'+Math.max(0,x(horizon)-x(end))+'" height="110" fill="#0b1521" opacity=".8"/>'+grid+'<text x="16" y="72" fill="#dece8c" font-size="13">TX</text><path data-baud-wave-path d="'+path+'" stroke="#edce77" stroke-width="3" fill="none"/>'+events+(s.ticks<=horizon?'<circle cx="'+x(end)+'" cy="'+y(level)+'" r="4" fill="#f9e7a6"/>':'')+ticks+'<text x="12" y="155" fill="#abc5cf" font-size="11">μs</text></svg></div><p data-baud-wave-detail role="status">点击发送使能位置查看阶段；未执行区域不绘制TX预测值。</p><small>每格为一个实际分频位周期；固定显示准备后前12个位周期。'+(s.ticks>horizon?'当前时间已超过图中窗口。':'')+'点击只读查看，不推进电路；窄屏可横向滚动。</small>';
}

function anatomyAsyncRXMarkup(b,s){
 if(b.id!=='asyncrx')return '';const r=s.uartAsync;
 return '<section class="an-async-rx"><h4>接收器每位采样8次</h4><p>RX → FF1='+r.first+' → FF2='+r.second+' → 状态机读取旧FF2。当前 '+r.phase+'，计时 '+r.timer+'。</p><div class="an-async-examples">'+[['good','正常帧'],['bad','错误停止位'],['glitch','2采样短脉冲'],['fast','发送每位7采样'],['slow','发送每位9采样']].map(([key,label])=>'<button data-async-example="'+key+'">'+label+'</button>').join('')+'</div><p>装入会清零本实验。当前：'+r.name+' · 已送 '+r.index+' / '+r.stimulus.length+' 个激励采样'+(r.expected===null||r.expected===undefined?'':' · 发送字节 '+r.expected)+'</p><div class="an-async-timer">'+Array.from({length:8},(_,i)=>'<span class="'+(i<r.timer?'elapsed':'')+'">'+(i+1)+'</span>').join('')+'</div><p>起始候选后等4次采样确认低电平；确认后每8次采样收一位。短脉冲拒绝次数 '+r.falseStarts+'。</p><p data-async-received>最近完成帧：'+(r.received.length?r.received.map(v=>'字节'+v.data+'（valid='+v.valid+'，error='+v.error+'，采样'+v.sample+'）').join('；'):'无')+'</p><details><summary>最近采样与位中心记录</summary><ol>'+r.trace.filter(v=>v.sampled).map(v=>'<li>采样'+v.sample+'：读取旧FF2='+v.observed+'；'+v.event+'；组装='+v.shift+'</li>').join('')+'</ol></details><small>采样当前RX不推进激励序列；送下一激励会先设置RX再采样。发送每位7或9采样表示发端速率偏差，接收器仍按8计数；8N1即使停止位正确也可能数据错误。本模型不计算亚稳态或真实采样裕量，不包含多数表决。</small></section>';
}

function anatomyAsyncSourceField(r,index){
 if(index===null||index===undefined)return null;
 if(r.txPeriod){const field=Math.floor((index-(r.txStart??8))/r.txPeriod);return field<0||field>9?'IDLE':field===0?'START':field===9?'STOP':'d'+(field-1)}
 return r.stimulusKind==='glitch'?(index>=8&&index<10?'GLITCH':'IDLE'):'激励';
}
function anatomyAsyncWaveMarkup(s){
 const r=s.uartAsync,rows=r.trace,left=90,step=6,width=Math.max(420,left+rows.length*step+25),height=328,channels=[['原始RX','raw',56],['FF1（新）','first',94],['FF2（新）','second',132],['读旧FF2','observed',170],['valid事件','valid',208],['error事件','error',246]],x=i=>left+i*step;
 const waves=channels.map(([label,key,top])=>{let path='';rows.forEach((row,i)=>{const y=top+(row[key]?0:18);path+=(i?'V':'M'+x(i)+' ')+y+'H'+x(i+1)});return '<text x="10" y="'+(top+14)+'" fill="#bed5dd" font-size="11">'+label+'</text><path d="'+path+'" fill="none" stroke="'+(key==='error'?'#ed9989':key==='valid'?'#a9d88a':key==='observed'?'#e7ce7f':'#79c1d1')+'" stroke-width="1.7"/>'}).join('');
 const segments=[];rows.forEach((row,i)=>{const field=anatomyAsyncSourceField(r,row.sourceIndex)||'手工';const last=segments.at(-1);if(last&&last.field===field)last.end=i+1;else segments.push({start:i,end:i+1,field})});
 const bands=segments.map(seg=>'<rect x="'+x(seg.start)+'" y="12" width="'+((seg.end-seg.start)*step)+'" height="22" rx="2" fill="'+(seg.field==='IDLE'?'#173441':'#354945')+'"/>'+((seg.end-seg.start)*step>=27?'<text x="'+((x(seg.start)+x(seg.end))/2)+'" y="27" text-anchor="middle" fill="#c7dfd8" font-size="10">'+seg.field+'</text>':'')).join('');
 const ticks=rows.map((row,i)=>i%16===0?'<path d="M'+(x(i)+3)+' 40V270" stroke="#294756" stroke-width=".7"/><text x="'+(x(i)+3)+'" y="315" text-anchor="middle" fill="#a7c5d0" font-size="10">'+row.sample+'</text>':'').join('');
 const centers=rows.map((row,i)=>!row.sampled?'':'<g data-async-wave-center="'+i+'" tabindex="0" role="button" aria-pressed="false" aria-label="采样'+row.sample+'，'+row.sampled+'，读取'+row.observed+'"><rect x="'+(x(i)-5)+'" y="160" width="16" height="134" fill="transparent"/><path d="M'+(x(i)+3)+' 166V280" stroke="#a2c79d" stroke-width="1" stroke-dasharray="3 3"/><circle cx="'+(x(i)+3)+'" cy="'+(170+(row.observed?0:18))+'" r="3" fill="#eddb91"/><text x="'+(x(i)+3)+'" y="295" text-anchor="middle" fill="#ebdba0" font-size="9">'+row.sampled+'</text></g>').join('');
 return '<h3>发出的位，与接收器真正读到的位</h3><div class="an-async-wave-scroll"><svg width="'+width+'" height="'+height+'" viewBox="0 0 '+width+' '+height+'" preserveAspectRatio="xMidYMid meet" role="group" aria-label="离散采样序号：RX、两级同步、旧FF2读取及有效错误事件"><text x="10" y="27" fill="#b6d0da" font-size="10">发送激励</text>'+bands+ticks+waves+centers+'</svg></div><p data-async-wave-detail role="status">点击START、d0…d7或STOP采样点，追踪读值来自发端哪一位。</p><small>横轴为实际离散采样序号，每格一个采样；图中是边沿后的FF1/FF2保存值与本边沿读取的旧FF2，不是模拟电压。只画已执行记录，保留最近192次；窄屏可横向滚动。</small>';
}

function anatomyRegister8Scenarios(s){
 const last=s.reg8Last,bits=n=>(n&255).toString(2).padStart(8,'0');
 return `<section class="an-reg8-scenarios"><h4>用同一组输入，比较三种控制条件</h4><p>输入固定为 10100101（165）。这些按钮只准备条件，随后点击“字节保存边沿”验证。</p><div>${[['hold','① CE=0：保持'],['capture','② CE=1：保存'],['clear','③ RESET=1：清零优先']].map(([id,title])=>`<button data-reg8-scenario="${id}">${title}</button>`).join('')}</div>${last?`<div class="an-reg8-edge" role="status"><b>最近一次保存边沿 · 第 ${last.edge} 次</b><p>D=${bits(last.input)} · CE=${last.enable} · RESET=${last.reset}</p><div class="an-reg8-transition">${Array.from({length:8},(_,j)=>{const i=7-j,a=(last.before>>>i)&1,b=(last.after>>>i)&1;return `<span class="${a!==b?'changed':''}" title="bit${i}：${a}变为${b}"><small>bit${i}</small>${a} → ${b}</span>`}).join('')}</div><p>${last.reset?'RESET 优先，全部清零。':last.enable?'CE 开启，八个位并行采样 D。':'CE 关闭，全部保持。'} 金色仅标记实际改变的位；相同值也可能已经完成采样。</p></div>`:'<p>尚未执行保存边沿；修改输入不会产生保存记录。</p>'}</section>`;
}

function anatomyRegisterControlLens(s){
 const index=(s.reset<<3)|(s.enable<<2)|(s.a<<1)|s.b,mid=s.enable?s.a:s.b,out=s.reset?0:mid;
 return `<section class="an-control-lens"><h4>沿选择路径理解输出</h4><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><p>动画顺序用于讲解逻辑依赖，不代表电路的实际传播时间。</p><ol><li><button data-control-stage="EN">① CE=${s.enable}：选择${s.enable?'原始D='+s.a:'Q反馈='+s.b} → ${mid}</button></li><li><button data-control-stage="RESET">② RESET=${s.reset}：选择${s.reset?'常量0':'上一步候选'+mid} → ${out}</button></li><li><button data-control-stage="OUT">③ 待采样D=${out}；尚未保存</button></li></ol><p>点击步骤定位对应电路。RESET=1 时，CE 和 D 都不能改变清零候选。</p><h4>可点击的完整真值表</h4><p>行是控制条件，列是 D / Q。点击格子，将这一组条件送入当前独立电路。</p><div class="an-control-matrix"><table><caption>格内数值为最终待采样D</caption><thead><tr><th scope="col">RESET / CE</th>${[0,1,2,3].map(v=>`<th scope="col">D=${v>>1}<br>Q=${v&1}</th>`).join('')}</tr></thead><tbody>${[0,1,2,3].map(control=>`<tr><th scope="row">${control>>1} / ${control&1}</th>${[0,1,2,3].map(data=>{const k=control*4+data,r=control>>1,en=control&1,d=data>>1,q=data&1,value=r?0:en?d:q;return `<td><button data-control-case="${k}" aria-pressed="${k===index}" aria-label="RESET=${r}，CE=${en}，D=${d}，Q=${q}，候选=${value}">${value}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div><p role="status">当前格：RESET=${s.reset}，CE=${s.enable}，D=${s.a}，Q=${s.b} → 候选 ${out}。本层不会给上级寄存器时钟。</p></section>`;
}

function anatomyFullAdderTokens(a,b,c){
 const total=a+b+c,carry=Math.floor(total/2),sum=total%2;
 const dot=(on,label)=>`<span class="an-add-dot ${on?'one':'zero'}" aria-label="${label}：${on}">${on}</span>`;
 return `<div class="an-add-regroup" aria-label="三个输入中有${total}个1，分成${carry}组两个1与${sum}个剩余1"><div class="an-add-input-tokens">${[[a,'A'],[b,'B'],[c,'Cin']].map(([v,label])=>`<div><small>${label} · 权重1</small>${dot(v,label)}</div>`).join('')}</div><p>共有 <b>${total}</b> 个1 → 每两个1合成一组</p><div class="an-add-output-tokens"><div><small>Cout · 权重2</small><div class="an-add-pair">${dot(carry,'进位包含的第一个1')}${dot(carry,'进位包含的第二个1')}</div><b>${carry} 组 × 2</b></div><div><small>S · 权重1</small>${dot(sum,'剩余1')}<b>${sum} 个 × 1</b></div></div><small>圆点表示数值单位，不表示电荷或电子。空心0不计入总数。</small></div>`;
}

function anatomyFilterOrigin(parent,part,p,s){
 if(parent?.id!=='filter')return '';let rows=[],note='';
 if(/^D[0-3]$/.test(part)){const i=Number(part[1]);rows=[['av','D',i?'延迟'+(i-1):'待采样输入',i?p.samples[i-1]:p.data,s.av],['reg8Q','Q','样本'+i,p.samples[i],s.reg8Q],['enable','CE','有效'+i,p.enable,s.enable]];note='八位保存完整复制；所有级在同一有效边沿读取各自旧输入。';}
 else if(['A01','A23','A','S'].includes(part)){const e=anatomyEvaluate('filter',p),nets=part==='A01'?['样本0','样本1']:part==='A23'?['样本2','样本3']:part==='A'?['低两项和','高两项和']:['W+2位和','固定移位量'];rows=nets.map((net,i)=>[i?'bv':'av',i?'B':'A',net,e.nets[net],i?s.bv:s.av]);note='无符号有效值零扩展到32位原理ALU；上级操作为'+(part==='S'?'SRL，固定移位2':'ADD')+'，本层当前操作为'+s.op+'。';}
 else return '';
 return `<section class="an-input-origin"><h4>滤波${part}的完整位宽来源</h4><p>${note}</p><table><thead><tr><th>本层量</th><th>上级信号</th><th>来源 → 当前</th></tr></thead><tbody>${rows.map(([key,label,net,value,local])=>`<tr data-filter-origin="${key}" data-origin-value="${value}" data-local-value="${local}"><th>${label}</th><td><button data-trace-parent-net="${net}">${net} ↗</button></td><td>${value} → ${local}</td></tr>`).join('')}</tbody></table><p>局部实验不改变父层窗口；重新读取恢复父层现场。</p></section>`;
}
function anatomyFilterEdgeAnimation(r){
 return `<div class="an-filter-edge-animation"><button data-filter-replay>回放共同边沿（不采新样本）</button><svg viewBox="0 0 280 268" role="img" aria-label="四个寄存器同时读取边沿前的值"><text x="52" y="17" text-anchor="middle">边沿前的来源</text><text x="226" y="17" text-anchor="middle">边沿后保存</text>${r.before.map((old,i)=>{const y=38+i*54,value=r.valid?r.inputs[i]:old,label=r.valid?(i?'旧D'+(i-1):'外部输入'):'旧D'+i,path='M100 '+(y+20)+'H180';return `<g data-filter-motion="${i}" data-source="${value}" data-target="${r.after[i]}"><rect x="4" y="${y}" width="94" height="38" rx="7"/><text x="51" y="${y+14}" text-anchor="middle">${label} = ${value}</text><text x="51" y="${y+29}" text-anchor="middle">${value.toString(2).padStart(8,'0')}</text><rect x="182" y="${y}" width="94" height="38" rx="7"/><text x="229" y="${y+15}" text-anchor="middle">D${i} = ${r.after[i]}</text><text x="229" y="${y+30}" text-anchor="middle">${r.valid?'共同边沿采样':'有效为0：保持'}</text><path d="${path}" class="${r.valid?'capture':'hold'}"/><circle r="4" opacity="0"><animateMotion begin="indefinite" dur="1.2s" path="${path}"/><animate attributeName="opacity" begin="indefinite" dur="1.2s" values="1;1;0" keyTimes="0;.95;1"/></circle></g>`}).join('')}</svg><p data-filter-replay-status role="status">四路同时回放，不表示寄存器依次更新。</p></div>`;
}
function mountAnatomyFilterReplay(host){
 const button=host.querySelector('[data-filter-replay]');if(!button)return;
 button.onclick=()=>{const box=button.closest('.an-filter-edge-animation'),status=box.querySelector('[data-filter-replay-status]');if(matchMedia('(prefers-reduced-motion: reduce)').matches){status.textContent='减少动态效果已开启，保留静态前后对照；没有采新样本。';return}status.textContent='四路同时回放已记录的边沿；没有采新样本。';box.querySelector('animateMotion').addEventListener('endEvent',()=>{status.textContent='回放结束；当前窗口与采样次数均保持不变。'},{once:true});box.querySelectorAll('animateMotion,animate').forEach(a=>a.beginElement());};
}
function anatomyFilterEdgeMarkup(s,interactive=false){
 const r=s.filterLast;if(!r)return '<p class="an-filter-edge-empty">尚无本层采样记录；准备输入后，点击上方采样按钮。</p>';
 const binary=v=>v.toString(2).padStart(8,'0');
 return `<section class="an-filter-edge" data-filter-edge="${r.edge}"><h4>最近一次共同边沿 · 第${r.edge}次</h4><p>边沿前输入=${r.data}；有效=${r.valid}。${r.valid?'四级同时读取下表的边沿前输入。':'发生了采样操作，但有效关闭，四级全部保持。'}</p><div class="an-filter-edge-scroll"><table><thead><tr><th>级</th><th>旧Q</th><th>D输入</th><th>新Q</th></tr></thead><tbody>${r.before.map((v,i)=>`<tr><th>D${i}</th><td data-filter-before="${i}">${v}<small>${binary(v)}</small></td><td data-filter-edge-input="${i}">${r.inputs[i]}<small>${i?'旧D'+(i-1)+'的Q':'外部输入'}</small></td><td data-filter-after="${i}" class="${r.after[i]!==v?'changed':''}">${r.after[i]}<small>${binary(r.after[i])}</small></td></tr>`).join('')}</tbody></table></div><p>${r.valid?`例如D1读取旧D0=${r.before[0]}，不会读取本拍刚进入D0的${r.data}。`:'各级D虽有候选输入，但有效为0，本边沿均未改写保存值。'}金色只标实际数值改变；保存相同数值也可能发生了采样。</p><small>这张表保存已经执行的边沿记录；修改待采样输入不会改写它。</small>${interactive?anatomyFilterEdgeAnimation(r):''}</section>`;
}

function anatomyFilterLens(b,s){
 if(b.id!=='filter')return '';const low=s.samples[0]+s.samples[1],high=s.samples[2]+s.samples[3],sum=low+high,mean=Math.floor(sum/4),next=s.enable?[s.data,...s.samples.slice(0,3)]:s.samples,stages=[...s.samples.map((v,i)=>['D'+i,`样本${i}：当前Q=${v}，下一边沿Q=${next[i]}`]),['A01',`低两项和=${low}（9位）`],['A23',`高两项和=${high}（9位）`],['A',`十位总和=${sum}`],['S',`逻辑右移2位：${sum} >> 2 = ${mean}`],['OUT',`输出=${mean}；余数=${sum%4}`]];
 return `<section class="an-control-lens an-filter-lens"><h4>保留高位，再截断除四</h4>${anatomyFilterEdgeMarkup(s,true)}<p data-filter-window>保存窗口：${s.samples.join('、')}（最新在前）。有效=${s.enable}；下一窗口：${next.join('、')}。</p><p data-filter-arithmetic>两两和：${low} + ${high} = <b data-filter-sum>${sum}</b>；均值=<b data-filter-mean>${mean}</b>。</p><p data-filter-bits>十位总和=${sum.toString(2).padStart(10,'0')}；保留高八位=${mean.toString(2).padStart(8,'0')}，舍去低两位=${(sum%4).toString(2).padStart(2,'0')}。</p><p>${sum} = 4 × ${mean} + ${sum%4}；最大总和1020，需要10位，输出最大255。</p><button data-filter-preset="255">准备255：采样四次观察满量程</button><button data-filter-preset="0">准备0：观察旧样本逐级退出</button><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><ol>${stages.map(([part,text])=>`<li><button data-control-stage="${part}">${text}</button></li>`).join('')}</ol><small>准备按钮仅设置待采样输入并开启有效；上方采样按钮才推进全部八位保存级。播放只定位，不产生边沿。</small></section>`;
}

function anatomyADCChainOrigin(parent,part,p,s){
 if(!['adccore','xadc'].includes(parent?.id)||!['REG','F'].includes(part))return '';
 const reg=part==='REG',source=reg?anatomyADCPlan(p).code:p.adcSample,valid=reg?p.adcValid:p.adcSampleValid;
 return `<section class="an-input-origin"><h4>${reg?'采样寄存器':'滤波器'}来源</h4><table><thead><tr><th>输入</th><th>展开时来源</th><th>本层当前</th></tr></thead><tbody><tr data-adc-origin="data" data-origin-value="${source}" data-local-value="${reg?s.av:s.data}"><th>数据</th><td><button data-trace-parent-net="${reg?'数字码':'样本'}">${source} ↗</button></td><td>${reg?s.av:s.data}</td></tr><tr data-adc-origin="valid" data-origin-value="${valid}" data-local-value="${s.enable}"><th>有效/使能</th><td><button data-trace-parent-net="${reg?'转换有效':'样本有效'}">${valid} ↗</button></td><td>${s.enable}</td></tr>${reg?`<tr data-adc-origin="saved" data-origin-value="${p.adcSample}" data-local-value="${s.q}"><th>已保存Q</th><td>${p.adcSample}</td><td>${s.q}</td></tr>`:''}</tbody></table><p>${reg?'上级已保存Q='+p.adcSample+'；本层Q='+s.q+'。':'上级窗口='+p.adcSamples.join('、')+'；本层窗口='+s.samples.join('、')+'。'}局部边沿不推进上级；重新读取恢复上级现场。</p></section>`;
}
function anatomyADCChainLens(b,s){
 if(!['adccore','xadc'].includes(b.id))return '';const p=anatomyADCPlan(s),mean=Math.floor(s.adcSamples.reduce((a,b)=>a+b,0)/4);
 return `<section class="an-control-lens an-adc-chain"><h4>共同边沿，两级分别读取旧输入</h4><p data-adc-current>量化候选=${p.code}；保存样本=${s.adcSample} / 有效=${s.adcSampleValid}；滤波输出=${mean}。</p><p data-adc-window>最近接收窗口：${s.adcSamples.join('、')}；已接收${s.adcFilterCount}个有效样本。启动不足四点用零填充。</p><p data-adc-next>下一边沿：寄存器${s.adcValid?'采入候选'+p.code:'保持旧样本并关闭有效标记'}；滤波${p.accepted?'接收边沿前保存样本'+s.adcSample:'没有有效旧样本，保持窗口'}，下一均值=${p.filtered}。</p><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><ol><li><button data-control-stage="ADC">量化：当前幅值${s.pct}% → 候选${p.code}</button></li><li><button data-control-stage="REG">寄存器：当前保存${s.adcSample}，转换有效=${s.adcValid}</button></li><li><button data-control-stage="F">滤波：读取保存样本及有效标记，不能穿透同拍新值</button></li><li><button data-control-stage="OUT">当前四点均值=${mean}；播放不会产生边沿</button></li></ol><small>这是理想数字采样链，未模拟采样保持电路、转换延迟或模拟抗混叠。滤波结果向下取整。</small></section>`;
}

function anatomyQuantizerOrigin(parent,part,p,s){
 if(!['adccore','xadc'].includes(parent?.id)||part!=='ADC')return '';
 return `<section class="an-input-origin"><h4>量化输入来源</h4><p data-quant-origin data-origin-value="${p.pct}" data-local-value="${s.pct}">展开时归一化幅值=${p.pct}%；本层当前=${s.pct}%。本层修改不影响上级，重新读取恢复上级现场。</p><button data-trace-parent-net="模拟输入">回溯模拟输入 ↗</button><small>百分比不是实体电压限制，模型没有采样率和模拟动态误差。</small></section>`;
}

function anatomyQuantizerDetails(b,s){
 if(b.id!=='quantizer')return '';const code=Math.min(15,Math.floor(s.pct*16/100)),mask=(1<<code)-1,bits=mask.toString(2).padStart(15,'0');
 return `<section class="an-quantizer-details"><p>输入=${s.pct}%；跨过${code}个阈值，数字码=${code}。</p><details class="an-threshold-bank"><summary>展开15个阈值比较器</summary><p>第k个比较器判断输入是否≥k×6.25%；刚好等于阈值时，进入该阈值对应的较高区间。</p><div class="an-threshold-grid">${Array.from({length:15},(_,j)=>{const k=j+1,t=k*6.25,v=+(s.pct>=t);return `<button data-quant-threshold="${k}" aria-pressed="false">C${k}：≥${t}% → <b>${v}</b></button>`}).join('')}</div><p data-quant-threshold-detail role="status">点击一个比较器，核对它的输入、阈值和输出。</p><div>边界实验：${[6.24,6.25,6.26,93.74,93.75,100].map(v=>`<button data-quant-pct="${v}">${v}%</button>`).join('')}</div></details><details class="an-thermometer-encoder"><summary>展开温度码→四位编码</summary><p>比较器从低阈值到高阈值连续满足；下列按C15…C1显示，1连续靠右。它是温度码，不是独热地址选择。</p><p data-quant-thermometer style="font-family:ui-monospace,monospace;letter-spacing:2px">${bits}</p><p>满足的阈值数=${code} → 二进制 <b data-quant-code>${code.toString(2).padStart(4,'0')}</b>。</p><div>${[3,2,1,0].map(i=>`<button data-quant-codebit="${i}">bit${i}=${(code>>>i)&1}</button>`).join('')}</div><p data-quant-code-detail role="status">点击一个输出位，查看它如何表示当前区间编号。</p><small>只演示本模型产生的理想连续温度码；不模拟比较器失调、噪声或气泡纠错。100%输出1111，不会产生第17个码。</small></details></section>`;
}

function anatomyTransmissionOrigin(parent,part,p,s){
 if(parent?.id!=='sram'||part!=='WR')return '';
 return `<section class="an-input-origin"><h4>写驱动bit0来源</h4><p>八位写驱动只取bit0演示通断原理，不将字节当作单个位。</p><table><thead><tr><th>本层量</th><th>上级来源</th><th>来源 → 本层当前</th></tr></thead><tbody>${[['a','D','待写字节',p.data&1,s.a],['enable','EN','写使能',p.we,s.enable]].map(([key,label,net,value,local])=>`<tr data-transmission-origin="${key}" data-origin-value="${value}" data-local-value="${local}"><th>${label}</th><td><button data-trace-parent-net="${net}">${net}${key==='a'?'的bit0':''} ↗</button></td><td>${value} → ${local}</td></tr>`).join('')}</tbody></table><p>本层组合输入可独立改变，不写入上级阵列；重新读取恢复上级现场。</p></section>`;
}
function anatomyTransmissionLens(b,s){
 if(b.id!=='transmission')return '';const y=s.enable?s.a:'Z',stages=[['I',`互补控制：NOT EN = ${1-s.enable}`],['N',`NMOS栅=${s.enable}，${s.enable?'接通':'断开'}`],['P',`PMOS栅=${1-s.enable}，${s.enable?'接通':'断开'}`],['Y',`输出 Y=${y}：${s.enable?'理想通路传递D':'本层没有其他驱动'}`]];
 return `<section class="an-control-lens"><h4>接通传递数据，关闭不主动输出</h4><p data-transmission-result>D=${s.a}，EN=${s.enable}，Y=${y}。Z不是0；本层不保存上一数字值。</p><div>${Array.from({length:4},(_,i)=>`<button data-transmission-case="${i}" aria-pressed="${((s.enable<<1)|s.a)===i}">D=${i&1} / EN=${i>>>1}</button>`).join('')}</div><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><ol>${stages.map(([part,text])=>`<li><button data-control-stage="${part}">${text}</button></li>`).join('')}</ol><small>理想数字开关；不计算真实导通电阻、阈值或电荷保持。两条互补通路不是依次采样。</small></section>`;
}

function anatomySRAMDriverBit(s,bit=0){
 const d=(s.data>>>bit)&1,bl=s.we?d:'Z',blb=s.we?1-d:'Z';
 return `<svg viewBox="0 0 600 260" role="img" aria-label="写驱动bit${bit}：D=${d}，WE=${s.we}，BL驱动=${bl}，互补BL驱动=${blb}" style="width:100%;height:auto"><g fill="none" stroke="#8bb5c2" stroke-width="2"><path d="M100 80H350M160 80V190H220M280 190H350M410 80H520M410 190H520M380 35V60M380 145V170"/></g><g fill="#173c4b" stroke="#8bb5c2" stroke-width="2"><rect x="25" y="55" width="75" height="50" rx="8"/><path d="M220 170V210L265 190Z"/><circle cx="272" cy="190" r="6"/><path d="M350 55V105L410 80ZM350 165V215L410 190Z"/></g><g fill="#e4f0f3" font-size="17" text-anchor="middle"><text x="62" y="85">D${bit}=${d}</text><text x="380" y="25">WE=${s.we}</text><text x="380" y="135">WE=${s.we}</text><text x="540" y="85">${bl}</text><text x="540" y="195">${blb}</text><text x="290" y="175">${1-d}</text><text x="505" y="55">BL${bit} 写驱动</text><text x="505" y="165">互补写驱动</text></g></svg><p data-driver-bit-detail>bit${bit}：原始D=${d}，反相候选=${1-d}。${s.we?'WE有效，两路理想写驱动分别输出'+d+'和'+(1-d)+'；仍需访问边沿才更新保存字节。':'WE关闭，两路写驱动均为Z，待写数据仍保留。'}Z只表示本图写驱动不主动输出，不代表整个物理位线必然悬空。</p>`;
}
function anatomySRAMDriverLens(b,s){
 if(b.id!=='sram')return '';
 return `<details class="an-sram-driver"><summary>展开八位写驱动：数据与互补支路</summary><p>WE控制写驱动，不控制地址译码。本图是理想数字驱动原理，省略读出预充、感测和晶体管电流。</p><button data-driver-we>切换写使能：WE=${s.we}</button><table><thead><tr><th>bit</th><th>待写D</th><th>BL写驱动</th><th>互补写驱动</th><th>内部</th></tr></thead><tbody>${Array.from({length:8},(_,j)=>{const i=7-j,v=(s.data>>>i)&1;return `<tr><th>${i}</th><td><button data-memory-data="A" data-memory-bit="${i}">${v}</button></td><td data-driver-bl="${i}">${s.we?v:'Z'}</td><td data-driver-blb="${i}">${s.we?1-v:'Z'}</td><td><button data-driver-probe="${i}" aria-label="查看bit${i}写驱动内部">查看</button></td></tr>`}).join('')}</tbody></table><div data-driver-bit-view>${anatomySRAMDriverBit(s,0)}</div><button data-driver-enter>继续展开bit0使能通断原理 ↗</button><small>修改待写位或WE不直接写入阵列；访问边沿才按父层条件提交。</small></details>`;
}

function anatomyDecoderAddressOrigin(parent,part,p,s){
 const fromRAM=parent?.id==='sram'&&part==='DEC',fromLow=parent?.id==='decoder3'&&part==='DEC2';if(!fromRAM&&!fromLow)return '';
 const value=fromRAM?p.addr:p.av&3,net=fromRAM?'地址':'低两位地址';
 return `<section class="an-input-origin"><h4>${fromRAM?'三位行地址来源':'两位预译码地址来源'}</h4><p data-decoder-origin data-origin-value="${value}" data-local-value="${s.av}">展开时来源=${value}，本层当前地址=${s.av}。${fromRAM?'三位地址对应八路字线。选行不等于已完成写入。':'只带入A1/A0；上级A2='+((p.av>>>2)&1)+'还要决定0…3或4…7分组。'}</p><button data-trace-parent-net="${net}">回溯${net} ↗</button><p>本层组合修改不写回上级；重新读取恢复上级现场。</p></section>`;
}
function anatomyDecoder3Lens(b,s){
 if(b.id!=='decoder3')return '';const a=s.av&7,low=a&3,high=a>>>2;
 return `<section class="an-control-lens an-decoder-lens"><h4>先选低位，再由高位区分上下组</h4><p>A2=${high}；A1 A0=${low.toString(2).padStart(2,'0')}。低位匹配${low}同时送往字线${low}和${low+4}，A2只允许其中一组。</p><div>${Array.from({length:8},(_,i)=>`<button data-decoder3-address="${i}" aria-pressed="${a===i}">${i.toString(2).padStart(3,'0')}</button>`).join('')}</div><p data-decoder3-summary>三位地址=${a}；WL7…WL0=${(1<<a).toString(2).padStart(8,'0')}。</p><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><ol><li><button data-control-stage="DEC2">低两位译码：选择匹配${low}</button></li><li><button data-control-stage="I2">高位A2=${high}，NOT A2=${1-high}</button></li>${Array.from({length:8},(_,i)=>`<li><button data-control-stage="H${i}">WL${i} = 低位匹配${i&3}(${+((i&3)===low)}) AND 高位条件(${i<4?1-high:high}) = ${+(a===i)}</button></li>`).join('')}</ol><small>分步仅讲解组合依赖。八路字线只有一路有效；写入还要满足父层写使能和写入边沿。</small></section>`;
}

function anatomyDecoderLens(b,s){
 if(b.id!=='decoder')return '';
 const address=s.av&3,a0=address&1,a1=address>>>1,stages=[['I1',`高位反相：NOT ${a1} = ${1-a1}`],['I0',`低位反相：NOT ${a0} = ${1-a0}`],...Array.from({length:4},(_,i)=>['G'+i,`D${i}：${i&2?'A1':'~A1'} · ${i&1?'A0':'~A0'} = ${+(address===i)}`])];
 return `<section class="an-control-lens an-decoder-lens"><h4>两根地址线，选中四路之一</h4><p>A1是高位，A0是低位。地址数值不是输出位串；输出只有被选中的一路为1。</p><div><button data-decoder-bit="1" aria-pressed="${!!a1}">A1=${a1}</button><button data-decoder-bit="0" aria-pressed="${!!a0}">A0=${a0}</button></div><table><thead><tr><th>地址 A1 A0</th><th>选择输出</th><th>当前值</th></tr></thead><tbody>${Array.from({length:4},(_,i)=>`<tr><td><button data-decoder-address="${i}" aria-pressed="${address===i}">${i.toString(2).padStart(2,'0')}</button></td><td><button data-decoder-focus="G${i}">定位 D${i} 与门</button></td><td data-decoder-output="${i}">${+(address===i)}</td></tr>`).join('')}</tbody></table><p data-decoder-summary>地址=${address}；D3 D2 D1 D0 = ${(1<<address).toString(2).padStart(4,'0')}。</p><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><ol>${stages.map(([part,text])=>`<li><button data-control-stage="${part}">${text}</button></li>`).join('')}</ol><small>四个与门并行匹配；这是高有效2→4组合译码，不包含使能、低有效输出或采样存储。</small></section>`;
}

function anatomyCompareLens(b,s){
 if(b.id!=='compare')return '';
 const a=s.av,bv=s.bv,d=a^bv,eq=+(a===bv),bits=[3,2,1,0],stages=[...bits.map(i=>['X'+i,`bit${i}：${(a>>>i)&1} XOR ${(bv>>>i)&1} = ${(d>>>i)&1}`]),['R01',`低两位差异合并 = ${+!!(d&3)}`],['R23',`高两位差异合并 = ${+!!(d&12)}`],['R',`任意位不同 = ${+!!d}`],['I',`EQ = NOT ${+!!d} = ${eq}`]];
 return `<section class="an-control-lens an-compare-lens"><h4>点击每一位，找出哪里不同</h4><p>左边是bit3，右边是bit0。相等比较要求所有位都相同，不是比较1的数量。</p><table><thead><tr><th>量</th>${bits.map(i=>`<th>bit${i}</th>`).join('')}</tr></thead><tbody>${[['av','A',a],['bv','B',bv]].map(([key,label,value])=>`<tr><th>${label}</th>${bits.map(i=>`<td><button data-compare-bit="${key}:${i}" aria-label="翻转${label}的bit${i}，当前${(value>>>i)&1}" aria-pressed="${!!((value>>>i)&1)}">${(value>>>i)&1}</button></td>`).join('')}</tr>`).join('')}<tr><th>差异</th>${bits.map(i=>`<td><button data-compare-focus="X${i}" aria-label="定位bit${i}的异或，差异${(d>>>i)&1}">${(d>>>i)&1}</button></td>`).join('')}</tr></tbody></table><p data-compare-summary>A=${a}，B=${bv}；差异位=${d.toString(2).padStart(4,'0')}；<b>EQ=${eq}</b>。</p><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><ol>${stages.map(([part,text])=>`<li><button data-control-stage="${part}">${text}</button></li>`).join('')}</ol><small>四个异或门并行工作；播放顺序只用于定位说明，不产生时钟。</small></section>`;
}

function anatomyFullAdderWalk(s){
 const a=s.a&1,b=s.b&1,c=s.cin&1,p=a^b,g=a&b,h=p&c,sum=p^c,carry=g|h;
 const stages=[['X1',`P = A ⊕ B = ${a} ⊕ ${b} = ${p}`,'两个输入不同，传播项为1。'],['X2',`S = P ⊕ Cin = ${p} ⊕ ${c} = ${sum}`,'和位：三个输入中有奇数个1时为1。'],['G1',`G = A · B = ${a} · ${b} = ${g}`,'产生进位：A、B同时为1。'],['G2',`H = P · Cin = ${p} · ${c} = ${h}`,'传播进位：A、B恰有一个1，且低位送来进位。'],['O',`Cout = G + H = ${g} ∨ ${h} = ${carry}`,'这里的 + 表示逻辑或，合并两种进位来源。']];
 return `<section class="an-control-lens an-fulladder-walk"><h4>把三个输入，拆成和位与进位</h4><p>输入 A=${a}、B=${b}、Cin=${c}。算术总数 ${a+b+c} = 2 × Cout(${carry}) + S(${sum})。</p>${anatomyFullAdderTokens(a,b,c)}<button data-fulladder-truth>比较全部8组输入 ↓</button><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><p>这是依赖关系的讲解顺序，不是实际传播时间。和位与进位支路并行工作；播放不会产生时钟或改变输入。</p><ol>${stages.map(([part,expression,why])=>`<li><button data-control-stage="${part}">${expression}</button><p>${why}</p></li>`).join('')}</ol><p>输出：S=${sum}，Cout=${carry}。点击步骤，在电路中定位对应的门；继续拆开可查看该门的内部结构。</p></section>`;
}

function mountAnatomyCountUnits(panel){
 if(!panel)return;
 panel.querySelectorAll('[data-count-unit]').forEach(unit=>{const inspect=()=>{panel.querySelectorAll('[data-count-unit]').forEach(node=>{const active=node===unit;node.setAttribute('aria-pressed',String(active));node.setAttribute('stroke',active?'#f1d37f':'#80b4c3');node.setAttribute('stroke-width',active?'4':'1')});panel.querySelector('[data-count-unit-detail]').textContent=panel.querySelector('[data-count-unit-description="'+unit.dataset.countUnit+'"]').textContent};unit.onclick=inspect;unit.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect()}}});
}
function anatomyCountZoom(panel,parent,historical=false){
 const zoom=document.createElement('dialog');zoom.className='an-count-zoom';zoom.setAttribute('aria-labelledby','an-count-zoom-title');
 const title=document.createElement('h3');title.id='an-count-zoom-title';title.textContent='消抖计数 · 内部结构';
 const close=document.createElement('button');close.textContent='关闭放大图 ×';close.dataset.countZoomClose='';close.onclick=()=>zoom.close();
 const note=document.createElement('p');note.textContent=(historical?'历史观察':'打开时现场')+'快照：可点击单元查看输入输出；关闭后回到原实验。';
 const scroll=document.createElement('div');scroll.className='an-count-zoom-scroll';const svg=panel.querySelector('svg').cloneNode(true);svg.querySelector('#debounce-count-arrow').id='debounce-count-zoom-arrow';svg.querySelectorAll('[marker-end]').forEach(n=>n.setAttribute('marker-end','url(#debounce-count-zoom-arrow)'));scroll.append(svg);
 const detail=panel.querySelector('[data-count-unit-detail]').cloneNode(true);detail.setAttribute('aria-live','polite');zoom.append(close,title,note,scroll,detail);panel.querySelectorAll('[data-count-unit-description]').forEach(n=>zoom.append(n.cloneNode(true)));parent.append(zoom);mountAnatomyCountUnits(zoom);
 zoom.addEventListener('close',()=>{zoom.remove();panel.querySelector('[data-count-zoom]')?.focus({preventScroll:true})},{once:true});zoom.showModal();return zoom;
}

function anatomyDebounceCountDetail(b,s){
 if(b.id!=='debounce')return '';
 const n=anatomyDebouncePreview(s),c=s.consecutive,inc=c+1;
 const units={saved:['保存单元',`当前输出=${c}；待保存输入=${n.count}。只有执行采样边沿才保存；候选变化不会立即改写当前次数。`],increment:['加一器',`输入=${c}；输出=${inc}。组合运算没有独立保存状态；即使此支路未被选择，加一候选仍可计算。`],one:['重计数常量',`输出固定为1。样本与旧候选不同，就从这次新样本计为第1次，不是从0开始。`],select:['选择器',`加一输入=${inc}；重计数输入=1；一致条件=${+n.same}；输出候选=${n.count}。它选择下一次数，本身不保存。`],threshold:['阈值比较器',`输入是下一次数${n.count}，阈值=3，输出ready=${+n.ready}。ready只控制稳定输出能否接受候选，不能当作保存次数。`]};
 const unitAttr=key=>`data-count-unit="${key}" tabindex="0" role="button" aria-pressed="false" aria-label="${units[key][0]}" style="cursor:pointer"`;
 return `<details class="an-debounce-count-detail"><summary>展开计数内部：加一、重计数与阈值判断</summary><p>当前保存次数与下一拍候选分开看。这里使用教学整数运算，不把计数截断成四位。</p><button data-count-zoom>放大内部图 ↗</button><svg viewBox="0 0 560 375" role="group" aria-label="保存次数${c}，加一${inc}，相同条件${+n.same}，下一次数${n.count}，阈值条件${+n.ready}" style="width:100%;height:auto"><defs><marker id="debounce-count-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#e8cd82"/></marker></defs><g fill="none" stroke="#7aaab9" stroke-width="2"><path d="M105 75H175M255 75H350V135M255 200H350V165M415 150H475V250H340" marker-end="url(#debounce-count-arrow)"/><path d="M475 150V335H60V105" stroke-dasharray="5 4"/></g><g fill="#143444" stroke="#80b4c3"><rect ${unitAttr('saved')} x="15" y="45" width="90" height="60" rx="8"/><circle ${unitAttr('increment')} cx="215" cy="75" r="40"/><rect ${unitAttr('one')} x="175" y="175" width="80" height="50" rx="8"/><path ${unitAttr('select')} d="M350 110L415 130V175L350 195Z" fill="#254a54"/><rect ${unitAttr('threshold')} x="170" y="250" width="170" height="65" rx="8"/></g><g fill="#e9f2f4" text-anchor="middle" font-size="15" pointer-events="none"><text x="60" y="68">已保存</text><text x="60" y="91">${c}</text><text x="215" y="68">+1</text><text x="215" y="91">${inc}</text><text x="215" y="195">重新计数</text><text x="215" y="216">1</text><text x="378" y="144">选择</text><text x="378" y="168">${n.count}</text><text x="255" y="274">候选次数 ≥ 3</text><text x="255" y="299">${n.count} ≥ 3 → ${+n.ready}</text></g><path d="${n.same?'M255 75H350V135':'M255 200H350V165'}" fill="none" stroke="#f1d37f" stroke-width="5"/><text x="375" y="225" fill="#f1d37f" text-anchor="middle" font-size="14">一致=${+n.same}</text><text x="45" y="365" fill="#b7d0d8" font-size="12">虚线：下一边沿才保存候选；箭头不表示传播时间</text></svg><p data-count-unit-detail role="status">点击图中单元，查看它的实际输入、输出和保存条件。</p>${Object.entries(units).map(([key,[title,body]])=>`<span hidden data-count-unit-description="${key}">${title}：${body}</span>`).join('')}<p>现在保存 ${c}；${n.same?'样本相同，选择加一结果':'样本不同，选择常量1'}，候选 ${n.count}。${n.ready?'满足提交条件':'还未满足提交条件'}，稳定输出现在仍是 ${s.stable}。</p><div><button data-count-condition="same">准备相同样本</button><button data-count-condition="different">准备不同样本</button><button data-count-sample>采样并观察保存 ↑</button></div><small>准备样本只改变本层原始输入；采样按钮执行与上方相同的一次消抖采样。</small></details>`;
}

function anatomyDebounceCompareOrigin(parent,part,p,s){
 if(parent?.id!=='debounce'||part!=='CMP')return '';
 return `<section class="an-input-origin an-debounce-compare-origin"><h4>相等比较的两个来源</h4><p>上级比较原始输入与候选保存位；本层用四位比较器的bit0演示，高三位初始为0。</p><table><thead><tr><th>本层量</th><th>上级来源</th><th>来源 → 本层当前</th></tr></thead><tbody>${[['av','A','输入',p.a,s.av],['bv','B','候选',p.candidate,s.bv]].map(([key,label,net,value,local])=>`<tr data-debounce-compare="${key}" data-origin-value="${value}" data-local-value="${local}"><th>${label}</th><td><button data-trace-parent-net="${net}">${net} ↗</button></td><td>${value} → ${local}</td></tr>`).join('')}</tbody></table><p>展开时一致=${+(p.a===p.candidate)}；本层当前相等=${+(s.av===s.bv)}。本层修改可独立偏离来源，重新读取恢复上级现场。</p></section>`;
}

function anatomyDebounceRegisterOrigin(parent,part,p,s){
 if(parent?.id!=='debounce'||!['ST','OLD'].includes(part))return '';
 const stable=part==='ST',ready=Number(anatomyDebouncePreview(p).ready),saved=stable?p.stable:p.candidate;
 return `<section class="an-input-origin an-debounce-register-origin"><h4>${stable?'稳定输出':'候选值'}保存单元的来源</h4><p>本层用四位寄存器演示一位保存：bit0对应上级，高三位初始为0。局部输入可独立改变。</p><table><thead><tr><th>量</th><th>展开时来源</th><th>本层当前值</th></tr></thead><tbody>${[['D',p.a,s.av],['Q',saved,s.q],['CE',stable?ready:1,s.enable],['RESET',0,s.reset]].map(([key,source,local])=>`<tr data-debounce-register="${key}" data-origin-value="${source}" data-local-value="${local}"><th>${key}</th><td>${source}</td><td>${local}</td></tr>`).join('')}</tbody></table><p>${stable?'CE来自下一采样的阈值条件，当前Q仍是已接受稳定值。':'候选每次采样都更新，CE固定1。'}局部边沿只保存本层；重新读取恢复上级现场。</p><button data-trace-parent-net="${stable?'提交值':'更新候选'}">回溯输入连线 ↗</button>${stable?'<button data-trace-parent-net="到达阈值">回溯使能连线 ↗</button>':''}</section>`;
}

function anatomySamplingWalk(b,s){
 const stages=b.id==='synchronizer'?[
 ['F1',`第一级：D=${s.a}，当前保存=${s.s1}；下一边沿采原始输入`],
 ['F2',`第二级：D=${s.s1}，当前保存=${s.s2}；同一边沿采第一级旧值`]
 ]:b.id==='edge'?[
 ['S',`当前级：D=${s.a}，Q=${s.stable}；下一边沿采输入`],
 ['D',`延迟级：D=${s.stable}，Q=${s.previous}；下一边沿采当前级旧值`],
 ['I',`反相器：NOT 上次保存 = NOT ${s.previous} = ${1-s.previous}`],
 ['G',`事件与门：${s.stable} AND ${1-s.previous} = ${s.stable&(1-s.previous)}`]
 ]:b.id==='debounce'?(()=>{const n=anatomyDebouncePreview(s);return [
 ['OLD',`保存候选=${s.candidate}；这是已保存值，不是原始输入`],
 ['CMP',`输入 ${s.a} 与候选 ${s.candidate} 比较：${s.a===s.candidate?'相同，延续计数':'不同，下一次重计数为1'}`],
 ['COUNT',`已保存次数=${s.consecutive}；下一采样次数=${n.count}，提交条件=${n.ready?1:0}`],
 ['ST',`稳定输出现在=${s.stable}；下一边沿候选=${n.stable}`]
 ]})():null;
 if(!stages)return '';
 return `<section class="an-control-lens an-sampling-walk"><h4>逐个定位：保存值与下一拍</h4><p>按讲解顺序高亮器件；采样级在共同边沿同时更新。播放只查看当前快照，不产生时钟。</p><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><ol>${stages.map(([part,text])=>`<li><button data-control-stage="${part}">${text}</button></li>`).join('')}</ol><small>需要改变状态时，使用上方输入和采样按钮。这里的顺序不代表器件传播延迟。</small></section>`;
}

function mountAnatomyControlWalk(host,focusPart,blocked=()=>false,options={}){
 if(!host)return ()=>{};
 const steps=[...host.querySelectorAll('[data-control-stage]')],play=host.querySelector('[data-control-play]'),next=host.querySelector('[data-control-next]'),rewind=host.querySelector('[data-control-rewind]'),progress=host.querySelector('[data-control-progress]');let timer=null,index=-1;
 const speed=document.createElement('select');speed.dataset.controlSpeed='';speed.setAttribute('aria-label','每步讲解间隔');speed.innerHTML='<option value="4000">每步4秒</option><option value="2000">每步2秒</option><option value="1000" selected>每步1秒</option><option value="500">每步0.5秒</option>';host.querySelector('.an-control-playback').append(speed);speed.value=String(options.interval||1000);
 function tick(){if(document.hidden){pause();return}advance()}
 speed.onchange=()=>{if(blocked())return;options.onInterval?.(Number(speed.value));if(timer!==null){clearInterval(timer);timer=setInterval(tick,Number(speed.value))}};
 function pause(){if(timer!==null)clearInterval(timer);timer=null;play.textContent='播放路径';play.setAttribute('aria-pressed','false')}
 function paint(){steps.forEach((n,i)=>{n.classList.toggle('is-current',i===index);if(i===index)n.setAttribute('aria-current','step');else n.removeAttribute('aria-current')});progress.textContent=index<0?'尚未播放':`第 ${index+1} / ${steps.length} 步${index===steps.length-1?' · 讲解完成':''}`;next.disabled=index===steps.length-1;focusPart(index>=0?steps[index].dataset.controlStage:null,index>=0?{index:index+1,total:steps.length,text:steps[index].textContent}:null)}
 function advance(){if(blocked()||!host.isConnected){pause();return}if(index<steps.length-1)index++;paint();if(index===steps.length-1)pause()}
 play.onclick=()=>{if(blocked())return;if(timer!==null){pause();return}if(index===steps.length-1)index=-1;advance();if(index===steps.length-1)return;play.textContent='暂停路径';play.setAttribute('aria-pressed','true');timer=setInterval(tick,Number(speed.value))};
 next.onclick=()=>{pause();advance()};rewind.onclick=()=>{if(blocked())return;pause();index=-1;paint()};steps.forEach((btn,i)=>btn.onclick=()=>{if(blocked())return;pause();index=i;paint()});
 play.setAttribute('aria-pressed','false');return pause;
}

const AN_FIFO_SCENARIOS=[
 {name:'空队列 · 同拍读写',mem:[0,0,0,0],read:0,write:0,count:0,push:1,pop:1,data:99},
 {name:'满队列 · 只请求写',mem:[10,20,30,40],read:0,write:0,count:4,push:1,pop:0,data:99},
 {name:'满队列 · 同拍读写',mem:[10,20,30,40],read:0,write:0,count:4,push:1,pop:1,data:99},
 {name:'指针环绕 · 同拍读写',mem:[20,0,0,10],read:3,write:1,count:2,push:1,pop:1,data:99}
];
function anatomyFIFOEdgeLens(b,s){
 if(b.id!=='fifo')return '';const last=s.fifoLast,order=r=>Array.from({length:r.count},(_,i)=>r.mem[(r.read+i)%4]),draw=(r,label)=>`<div class="an-fifo-edge-state"><b>${label}</b><p>R=${r.read} · W=${r.write} · 占用=${r.count}</p><div class="an-fifo-edge-bytes">${order(r).length?order(r).map((v,i)=>`<span>${i===0?'队首 ':''}${v}</span>`).join('<em>→</em>'):'空队列'}</div></div>`;
 return `<section class="an-fifo-edge-lens"><h4>边界实验 · 先观察请求，再提交</h4><p>装入例子会重置本页FIFO、串口链路与观察历史，不自动提交读写边沿。</p><div class="an-fifo-examples">${AN_FIFO_SCENARIOS.map((r,i)=>`<button data-fifo-example="${i}">${r.name}</button>`).join('')}</div>${last?.before&&last?.after?`<h4>最近一次队列边沿</h4><p>请求：读=${+last.requestedPop} / 写=${+last.requestedPush}；实际接受：读=${+last.pop} / 写=${+last.push}</p><div data-fifo-edge-comparison>${draw(last.before,'边沿前保存状态')}<div class="an-fifo-edge-result">${last.pop?'实际读出 '+last.value:last.requestedPop?'空队列拒绝读出':'没有读请求'}<br>${last.push?'实际写入 '+last.writeValue:last.requestedPush?'满队列拒绝单独写入':'没有写请求'}</div>${draw(last.after,'边沿后保存状态')}</div><p>占用计算：${last.before.count} + ${+last.push} − ${+last.pop} = ${last.after.count}。${last.before.count===0&&last.requestedPop&&last.push?'空时新写字节只入队，不作为同拍读出。':last.before.count===4&&last.pop&&last.push?'满时读的是旧队首；新字节写到腾出的物理槽。':'指针仅随实际接受的读写移动。'}</p><small>这是最近已发生边沿的快照；之后更改待写输入不改写这份记录。</small>`:'<p>尚无边沿快照。装入例子后，点击“提交读写边沿”对比前后状态。</p>'}</section>`;
}

function anatomyFIFOTextLoad(s,text){
 const bytes=[...new TextEncoder().encode(text)];if(!bytes.length)throw Error('请输入至少一个字符。');if(bytes.length>64)throw Error('本次最多准备64个UTF-8字节；原待发内容保持。');s.fifoText={draft:text,bytes,index:0};return bytes;
}
function anatomyFIFOTextFeed(s){
 const source=s.fifoText;if(!source||source.index>=source.bytes.length||s.fifoCount===4)return false;
 const push=s.fifoPush,pop=s.fifoPop;s.data=source.bytes[source.index];s.fifoPush=1;s.fifoPop=0;anatomyAdvance('fifo',s);s.fifoPush=push;s.fifoPop=pop;if(s.fifoLast.push){source.index++;return true}return false;
}
function anatomyFIFOTextResult(bytes){
 if(!bytes.length)return '尚未读取字节';try{return JSON.stringify(new TextDecoder('utf-8',{fatal:true}).decode(new Uint8Array(bytes)))}catch{return '尚不能解码为完整UTF-8：可能仍缺后续字节，或字节序列无效'}
}
function anatomyFIFOTextMarkup(b,s){
 if(b.id!=='fifo')return '';const source=s.fifoText||{draft:'Hi',bytes:[],index:0},esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),remaining=source.bytes.length-source.index;
 return `<section class="an-fifo-text"><h4>从文字理解字节传输</h4><label>待编码文字<input data-fifo-text-draft value="${esc(source.draft)}" maxlength="128"></label><button data-fifo-text-load>准备UTF-8字节</button><p data-fifo-text-error role="status"></p><p>准备只替换文字输入源，不清空已有FIFO或接收记录；每字节使用独立8N1帧。需要干净现场可先点“重新开始本演示”。</p><div class="an-fifo-text-bytes">${source.bytes.map((v,i)=>`<span class="${i<source.index?'sent':i===source.index?'next':''}" title="第${i+1}字节，十进制${v}，二进制${v.toString(2).padStart(8,'0')}">${v.toString(16).toUpperCase().padStart(2,'0')}<small>${i<source.index?'已入队':i===source.index?'下一个':'待入队'}</small></span>`).join('')}</div><p data-fifo-text-progress>已入发送队列 ${source.index} / ${source.bytes.length} 字节；剩余 ${remaining}。</p><button data-fifo-text-feed ${!remaining||s.fifoCount===4?'disabled':''}>将下一个字节写入发送FIFO</button><p>${s.fifoCount===4&&remaining?'发送FIFO已满：输入源暂停，先推进串口腾出位置。':remaining?'此操作只写一个字节，不同时执行上方读请求。':'准备文字后，逐字节入队；在“完整收发链”中推进串口并读取接收字节。'} 接收端仍需及时读取，接收FIFO满时会丢弃新字节。</p></section>`;
}

function anatomyFIFOTransportStep(s,autoRead=true){
 let progressed=anatomyFIFOTextFeed(s);if(anatomyFIFOTransmitStep(s))progressed=true;
 if(autoRead&&anatomyFIFOReceiveRead(s))progressed=true;
 return progressed;
}
function anatomyFIFOTransportPending(s,autoRead=true){return !!((s.fifoText&&s.fifoText.index<s.fifoText.bytes.length)||s.fifoCount||(s.fifoTX&&s.fifoTX.tx.uartIndex>=0)||(autoRead&&s.fifoTX?.rxFIFO?.fifoCount))}

function anatomyFIFOOverviewMarkup(s,historical=false){
 const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),link=s.fifoTX,tx=link?.tx,rx=link?.rx,busy=tx&&tx.uartIndex>=0,frame=busy?anatomyUARTFrame(tx):[],q=link?.rxFIFO,received=rx?(rx.rxPhase>=0?rx.rxPhase:rx.rxValid?8:0):0,labels=['START',...Array.from({length:8},(_,i)=>'d'+i),'STOP'],count=s.fifoText?s.fifoText.bytes.length-s.fifoText.index:0;
 return `<header><b>文字 → 字节 → 串行位 → 接收 → 应用</b><span>${historical?'历史快照 · 不推进电路':'现场同步状态'}</span></header><div class="an-fifo-overview-grid"><button data-fifo-focus="MEM"><small>① 待发输入 / 发送FIFO</small><b>输入源剩余 ${count} 字节 · 排队 ${s.fifoCount} / 4</b><span>当前队首：${s.fifoCount?s.fifoMem[s.fifoRead]:'无有效字节'}</span></button><button data-fifo-focus="RXQ"><small>④ 接收FIFO</small><b>待应用读取 ${q?.fifoCount||0} / 4</b><span>已丢弃新字节 ${link?.rxOverflow||0} 个</span></button><section class="an-fifo-overview-frame"><button data-fifo-focus="TXLINK"><small>② 发送器 · 先发低位</small><b>${busy?'捕获字节 '+tx.uartByte+' · 当前 '+labels[tx.uartIndex]+'='+frame[tx.uartIndex]:'空闲 · TX=1'}</b></button><div class="an-fifo-overview-bits" aria-label="发送帧编码预览">${labels.map((label,i)=>`<span class="${busy?(i===tx.uartIndex?'current':i<tx.uartIndex?'past':'future'):'idle'}" ${busy&&i===tx.uartIndex?'aria-current="step"':''}><small>${label}</small><b>${busy?frame[i]:'—'}</b></span>`).join('')}</div><p>金色为当前位；已走过的位为绿色，淡色是捕获字节的后续编码预览，尚未发送。空闲不展示虚构帧。</p></section><button data-fifo-focus="RXLINK"><small>③ 接收器 · 已实际采到的位</small><b class="an-fifo-overview-rx">${Array.from({length:8},(_,j)=>{const i=7-j;return i<received?(rx.rxData>>>i)&1:'·'}).join('')}</b><span>${rx?.rxValid?'停止位已确认，本次字节有效':rx?.rxError?'停止位错误，本次字节无效':received?'已采 '+received+' / 8 位，等待本帧完成':'等待起始 / 数据采样'}</span></button><button data-fifo-focus="APP"><small>⑤ 应用已读取 · 最近64字节</small><b>${esc(anatomyFIFOTextResult(link?.consumed||[]))}</b><span>字节取出后才进入文字解释。</span></button></div>`;
}

function anatomyReportSVG(svg){
 if(!svg)return '';const clone=svg.cloneNode(true),source=[svg,...svg.querySelectorAll('*')],nodes=[clone,...clone.querySelectorAll('*')],properties=['fill','stroke','stroke-width','stroke-dasharray','stroke-linecap','stroke-linejoin','opacity','fill-opacity','stroke-opacity','font-family','font-size','font-weight','text-anchor','dominant-baseline','visibility','display'];
 source.forEach((node,i)=>{const style=getComputedStyle(node);nodes[i].setAttribute('style',properties.map(p=>p+':'+style.getPropertyValue(p)).join(';'));for(const attr of [...nodes[i].attributes])if(/^on/i.test(attr.name)||['tabindex','role'].includes(attr.name))nodes[i].removeAttribute(attr.name)});
 clone.querySelectorAll('script,foreignObject').forEach(n=>n.remove());clone.querySelectorAll('.sc-hint').forEach(n=>n.textContent='只读快照 · 交互请回到教学板');clone.querySelectorAll('text').forEach(n=>{if(['选择连线查看信号与连接说明','选择连线查看信号值与连接说明'].includes(n.textContent))n.textContent='命名信号与连接值见报告表格'});clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.removeAttribute('width');clone.removeAttribute('height');clone.style.width='100%';clone.style.height='auto';clone.style.display='block';return clone.outerHTML;
}
function anatomyDebounceCountReport(s){
 const doc=new DOMParser().parseFromString(anatomyDebounceCountDetail(ANATOMY.debounce,s),'text/html'),svg=doc.querySelector('svg');
 const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 svg.setAttribute('role','img');svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.style.background='#102432';svg.style.fontFamily='system-ui,sans-serif';svg.style.borderRadius='8px';
 svg.querySelector('#debounce-count-arrow').id='debounce-count-report-arrow';svg.querySelectorAll('[marker-end]').forEach(n=>n.setAttribute('marker-end','url(#debounce-count-report-arrow)'));
 svg.querySelectorAll('[data-count-unit]').forEach(n=>{for(const a of [...n.attributes])if(a.name.startsWith('data-')||['role','tabindex','aria-pressed','style'].includes(a.name))n.removeAttribute(a.name)});
 const rows=[...doc.querySelectorAll('[data-count-unit-description]')].map(n=>'<tr><td>'+esc(n.textContent)+'</td></tr>').join('');
 return '<section data-report-count><h2>计数内部 · 保存量与下一拍候选</h2><p>本图根据本报告的状态生成；为只读原理图，输入准备与采样请回到教学板。金色表示当前选择支路，不表示逻辑值一定为1。</p>'+svg.outerHTML+'<table><thead><tr><th>各单元输入、输出与职责</th></tr></thead><tbody>'+rows+'</tbody></table><p>教学整数运算，不指定实体计数位宽；阈值3不代表实际消抖时间。</p></section>';
}

function anatomyExperimentReport({blueprint:b,state:s,evaluation:e,path,origins=[],historical=false,diagram='',position='',assessment=null,sourceSnapshot=null,created=new Date().toISOString()}){
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),value=v=>typeof v==='object'?JSON.stringify(v):String(v??'—'),inputs=anatomyLearningInputKeys(b),chain=anatomyContextPath(b.id,path);
 const table=(headers,rows)=>'<table><thead><tr>'+headers.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
 return '<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(b.title)+' · 实验报告</title><style>body{max-width:1080px;margin:32px auto;padding:0 24px;font:16px/1.7 system-ui,sans-serif;color:#203a49;background:#fff}h1{font-size:28px}h2{margin-top:32px;font-size:21px}small,.muted{color:#526d7b}.meta{border-left:4px solid #ae8732;padding:12px;background:#f5f4ec}.diagram{background:#f7fafc;border:1px solid #a7bdc7;border-radius:10px;padding:12px;overflow:auto}table{border-collapse:collapse;width:100%;margin:12px 0}th,td{border:1px solid #b3c7d1;padding:8px;text-align:left;overflow-wrap:anywhere}th{background:#e9f1f4}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef3f5;padding:12px;font-size:12px}a{color:#195b78}.an-filter-edge small{display:block;font-family:monospace}.an-filter-edge .changed{background:#fff0c7}.an-vga-edge svg{display:block;width:480px;max-width:100%;height:auto;background:#f1f6f8;border:1px solid #7e9dab;border-radius:9px}@media print{body{margin:0;max-width:none;font-size:11pt}.diagram{break-inside:avoid}thead{display:table-header-group}tr{break-inside:avoid}details{display:block}details>summary{display:none}}</style><h1>GBU-CS301 · 实验观察报告</h1><h2>'+esc(b.title)+'</h2><p class="meta">'+(historical?'历史快照 · 只读观察':'当前现场 · 只读观察')+'<br>导出时间：'+esc(created)+'<br>教学边沿 / 操作计数：'+esc(s.ticks)+'<br>本报告保存观察结果与状态，不包含可继续运行的仿真环境。</p><h2>整体位置与具体实例</h2><p>'+chain.map(id=>esc(ANATOMY[id].title.split(' · ')[0])).join(' → ')+'</p><p>实际进入路径：'+path.map((id,i)=>esc(id+(origins[i]?'（'+origins[i]+'）':''))).join(' → ')+'</p>'+(position?'<details><summary>展开逐层位置图</summary><div class="diagram">'+position+'</div></details>':'')+anatomyOriginReportMarkup(sourceSnapshot)+'<h2>输入条件</h2>'+table(['输入','值'],inputs.map(key=>[anatomyLearningInputName(b,key),value(s[key])]))+'<h2>输出与观察值</h2><p><b>'+esc(anatomyOutputDescriptor(b).name)+'：'+esc(value(e.result))+'</b></p>'+table(['观察量','值','解释'],e.watch.map(r=>[r.name,r.value,r.why||'']))+'<h2>命名信号</h2>'+table(['信号','发送端 → 接收端','位宽','值'],b.nets.map(n=>[n.name,n.from+' → '+n.to,n.bits,value(e.nets[n.name])]))+'<h2>导出时电路图</h2><div class="diagram">'+(diagram||'<p>本层电路图尚未就绪。</p>')+'</div>'+(b.id==='debounce'?anatomyDebounceCountReport(s):'')+(b.id==='filter'?'<section data-report-filter-edge><h2>最近一次滤波采样的前后对照</h2>'+anatomyFilterEdgeMarkup(s)+'</section>':'')+(b.lab==='vga'&&s.vgaLast?'<section data-report-vga-edge><h2>最近一次VGA读写边沿</h2>'+anatomyVGAEdgeMarkup(s)+'</section>':'')+anatomySavedEdgeReport(b,s,table)+anatomyCompareReport(b,s,table)+anatomyMemoryAccessReport(b,s,table)+anatomyPredictionReportMarkup(assessment)+'<h2>实现边界</h2><p>'+esc(b.boundary||'教学功能模型，不替代实体器件验证。')+'</p><p>路径关系可能为功能关联；此图不代表厂商物理版图。图中高亮与导出时一致。</p><h2>原始状态附件（只读）</h2><details><summary>展开完整状态，供复核输入与保存量</summary><pre>'+esc(JSON.stringify({format:'GBU-CS301-observation',version:assessment||sourceSnapshot?2:1,view:b.id,path,origins,historical,state:s,...(assessment?{exercise:assessment}:{}),...(sourceSnapshot?{sourceSnapshot}:{})},null,2))+'</pre></details></html>';
}

function anatomyMultiply4Markup(b,s){
 if(b.id!=='multiply4')return '';const m=s.multiply4,bin=(v,n)=>v.toString(2).padStart(n,'0');if(!m)return '<section class="an-multiply-lens"><h4>先装载，再执行四轮</h4><p>设置A/B后点击装载。装载会捕获输入，并把部分积P清零；随后每轮判断B0，保存部分积，并同时移位。</p></section>';
 const active=m.k<4,add=active&&(m.b&1)?m.a:0;
 return `<section class="an-multiply-lens"><h4>正在计算：${m.inputA} × ${m.inputB}</h4><div class="an-multiply-playback"><button data-multiply-play aria-pressed="false">播放四轮</button><button data-multiply-next>讲解下一步</button><p data-multiply-play-status role="status">每轮三步：读B0 → 看候选 → 同一个边沿提交。</p></div><p>前两步只观察，第三步才执行保存边沿；动画间隔是教学节奏，不是电路延迟。</p><p>待装载输入现在为 ${s.av} × ${s.bv}；只有重新装载才替换当前运算。</p><div class="an-multiply-registers"><button data-multiply-part="A"><small>左移被乘数A</small><b>${bin(m.a,8)}</b>${m.a}</button><button data-multiply-part="B"><small>右移乘数B</small><b>${bin(m.b,4)}</b>${m.b} · B0=${m.b&1}</button><button data-multiply-part="P"><small>已保存部分积P</small><b>${bin(m.p,8)}</b>${m.p}</button></div><p data-multiply-decision role="status">${active?'下一轮 '+(m.k+1)+'：'+m.p+' + '+add+' = '+(m.p+add)+'（'+((m.b&1)?'B0=1，加入当前A':'B0=0，加0并保持P')+'）；提交后A左移，B右移。':'四轮完成：'+m.inputA+' × '+m.inputB+' = '+m.p+'。再次执行不改写结果。'}</p><button data-multiply-part="ADD">进入本轮实际加法候选 →</button><div class="an-multiply-rounds" aria-label="已完成轮次">${Array.from({length:4},(_,i)=>`<span class="${i<m.k?'done':i===m.k?'current':''}">轮${i+1}<small>${i<m.k?'已提交':i===m.k?'下一轮':'尚未执行'}</small></span>`).join('')}</div><table><caption>实际已执行记录，不预先填入未来结果</caption><thead><tr><th>轮</th><th>A / B0</th><th>旧P</th><th>新P</th></tr></thead><tbody>${m.rows.map(r=>`<tr><td>${r.k+1}</td><td>${r.a} / ${r.b0}</td><td>${r.before}</td><td>${r.after}</td></tr>`).join('')}</tbody></table><small>这是无符号移位相加；负数乘法需要额外处理。本模型不是DSP物理结构，也不会让CPU自动支持乘法指令。</small></section>`;
}

function anatomyDivide4Markup(b,s){
 if(b.id!=='divide4')return '';const m=s.divide4,p=anatomyDivide4Plan(s),bits=(v,w)=>v.toString(2).padStart(w,'0');if(!m)return '<section class="an-divide-lens"><h4>先装载，再逐位求商</h4><p>Q装入四位被除数，R初始为0。四轮每次从Q最高位取一位，移入R后试减除数。</p></section>';
 return `<section class="an-divide-lens"><h4>正在计算 ${m.inputA} ÷ ${m.inputB}</h4><div class="an-divide-playback"><button data-divide-play aria-pressed="false">播放四轮除法</button><button data-divide-next>讲解下一步</button><p data-divide-play-status role="status">每轮：移入 → 试减 → 恢复选择 → 同一边沿提交。</p></div><p>前三阶段只观察候选，第四阶段才更新保存状态；动画节奏不代表器件传播时间。</p><p>待装载输入为 ${s.av} ÷ ${s.bv}，改变它不会替换当前已捕获值。</p><div class="an-divide-registers">${[['Q',m.q,'Q工作位 · 未完成不是商'],['R',m.r,'已保存余数R'],['D',m.d,'捕获除数D']].map(([id,v,label])=>`<button data-divide-part="${id}"><small>${label}</small><b>${bits(v,4)}</b>${v}</button>`).join('')}</div>${anatomyDivideQuotientMarkup(s)}${m.zero?'<p class="an-divide-error" role="status">除数为0：没有有效的商和余数，未执行试减轮次。请修改除数并重新装载。</p>':p.active?`<div data-divide-candidate><h4>下一轮 ${m.k+1} 的候选</h4><button data-divide-part="SHIFT">① 展开移位逐位接线 →</button><p>R左移并移入Q最高位：(${m.r} × 2) + ${m.q>>>3} = ${p.shifted}（${bits(p.shifted,5)}）</p><button data-divide-part="SUB">② 试减：${p.shifted} − ${m.d} = ${p.difference}</button><p>五位差编码 ${bits(p.trial,5)}；${p.ok?'无借位，够减':'有借位，不够减'}。不能只把低五位当作正常余数。</p><button data-divide-part="SEL">③ 展开五位恢复选择 →</button><p>${p.ok?'保留试减差':'恢复为移入后原值'}，R候选=${p.nextR}；商位写${p.qbit}，Q候选=${bits(p.nextQ,4)}。</p><p>现在还没有保存；点击执行一轮，Q、R和轮数同时提交。</p></div>`:`<p data-divide-final role="status">四轮完成：商 ${m.q}，余数 ${m.r}。验证 ${m.inputA} = ${m.d} × ${m.q} + ${m.r}，且 ${m.r} &lt; ${m.d}。</p>`}<p>已提交 ${m.k} / 4 轮。</p><table><caption>实际提交记录</caption><thead><tr><th>轮</th><th>移入值</th><th>试减差</th><th>商位</th><th>新Q / R</th></tr></thead><tbody>${m.rows.map(r=>`<tr><td>${r.k+1}</td><td>${r.shifted}</td><td>${r.difference}</td><td>${r.qbit}</td><td>${r.nextQ} / ${r.nextR}</td></tr>`).join('')}</tbody></table><small>“恢复”选择的是移入后的原值，不是上轮旧R。除零按教学错误处理，不等同于CPU DIVU的规定行为。</small></section>`;
}

function anatomyRestore5Markup(b,s){
 if(b.id!=='restore5')return '';const result=s.cin?s.av:s.bv;
 return `<section class="an-restore-lens"><h4>同一个借位，控制五个位</h4><button data-restore-example="borrow">例：1−3借位，恢复1</button><button data-restore-example="keep">例：7−3够减，保留4</button><p>点击候选位修改输入；点击输出位进入该位选择器。每次选择都是组合变化，不产生保存边沿。</p>${[['A',s.av,'移入后的原值',!!s.cin],['B',s.bv,'试减差低5位',!s.cin]].map(([id,word,label,chosen])=>`<div class="an-restore-word ${chosen?'chosen':''}"><b>${label} · ${word}${chosen?' ← 当前选中':''}</b><div>${Array.from({length:5},(_,j)=>{const bit=4-j;return `<button data-restore-bit="${id}:${bit}" aria-label="翻转${label}bit${bit}，当前${(word>>>bit)&1}"><small>bit${bit}</small>${(word>>>bit)&1}</button>`}).join('')}</div></div>`).join('')}<p data-restore-rule role="status">借位=${s.cin} → ${s.cin?'恢复移入原值':'保留试减差'} → ${result.toString(2).padStart(5,'0')}（${result}）。原值与试减差在此不相加。</p><div class="an-restore-output">${Array.from({length:5},(_,j)=>{const bit=4-j;return `<button data-restore-mux="${bit}" aria-label="进入bit${bit}的二选一选择器"><small>M${bit}</small>${(result>>>bit)&1}<span>进入 →</span></button>`}).join('')}</div><small>独立设置候选和借位可能形成不符合上级算术的组合；这里演示选择功能，完整除法应回到上级执行。</small></section>`;
}

function anatomyDivideShiftMarkup(b,s){
 if(b.id!=='divideShift')return '';const r=s.av,q=s.bv,t=(r<<1)|(q>>>3),shift=(q<<1)&15,sourceBit=key=>key==='ZERO'?0:((key[0]==='R'?r:q)>>>Number(key[1]))&1,wire=(key,out)=>key==='ZERO'?'常量0接到'+out:key+'接到'+out;
 const output=(name,keys)=>`<div class="an-wire-word"><b>${name}</b><div>${keys.map((key,i)=>{const out=(name[0]==='T'?'T':'S')+(keys.length-1-i);return `<button data-wiring-net="${wire(key,out)}" aria-label="查看${key}到${out}接线"><small>${out} ← ${key==='ZERO'?'0':key}</small>${sourceBit(key)}</button>`}).join('')}</div></div>`;
 return `<section class="an-wire-lens"><h4>移位不是逐位搬动，而是固定接线</h4><p>点击图中或下方R/Q输入位翻转；输出位只查看它的来源，不改变输入。</p>${[['R',r],['Q',q]].map(([name,value])=>`<div class="an-wire-word"><b>${name} 输入 · ${value}</b><div>${Array.from({length:4},(_,i)=>{const bit=3-i;return `<button data-wiring-input="${name}${bit}" aria-label="翻转${name}${bit}"><small>${name}${bit}</small>${(value>>>bit)&1}</button>`}).join('')}</div></div>`).join('')}${output('T 五位临时余数',['R3','R2','R1','R0','Q3'])}<p>T = ${r} × 2 + ${q>>>3} = ${t}。R的最低位接到T1，Q3占用T0，两个来源不重叠。</p>${output('S 先补0的Q左移值',['Q2','Q1','Q0','ZERO'])}<p>S=${shift}，最低位先为0。完整除法之后还要根据借位写入新商位，因此S不是最终的Q候选。</p><small>本层仅有组合接线，没有保存、迭代或算术加法器；进入这里不会执行上级除法轮次。</small></section>`;
}

function anatomyDivideQuotientState(s){
 const m=s.divide4;if(!m)return null;return {valid:!m.zero,k:m.k,prefix:m.inputA>>>(4-m.k),partial:m.q&((1<<m.k)-1),remaining:m.q>>>m.k,bits:Array.from({length:4},(_,j)=>{const position=3-j,generated=position<m.k;return {position,value:(m.q>>>position)&1,kind:generated?'quotient':'pending',source:generated?m.k-position:position-m.k}})};
}
function anatomyDivideQuotientExplain(s,bit){
 const m=s.divide4,q=anatomyDivideQuotientState(s);if(!q||!q.valid)return '当前没有有效除法，不能把Q解释为已生成商。';const item=q.bits.find(v=>v.position===bit);return 'Q bit'+bit+'='+item.value+'：'+(item.kind==='pending'?'尚未处理的被除数位，来自原被除数bit'+item.source+'。'+(bit===3?'下一轮将先把它移入临时余数。':'仍需后续左移才到达Q3。'):'来自第'+item.source+'轮实际生成的商位；当前权重为2^'+bit+(m.k===4?'。四轮已完成，此位处于最终商中并保持。':'。后续轮次执行时，它仍会向左移。'));
}
function anatomyDivideQuotientMarkup(s){
 const m=s.divide4,q=anatomyDivideQuotientState(s);if(!q)return '';if(!q.valid)return '<p class="an-divide-q-invalid">除零现场：Q保留装载内容，不表示有效商。</p>';
 const original=m.inputA.toString(2).padStart(4,'0');return `<section class="an-divide-q-lens"><h4>同一个Q，正在保存两种内容</h4><p>青色标“待移入”，金色标“已生成商位”；未完成时商位还会继续左移；四轮后全部成为最终商。</p><div class="an-divide-q-cells">${q.bits.map(bit=>`<button data-divide-qbit="${bit.position}" class="${bit.kind}" aria-pressed="false" aria-label="查看Q bit${bit.position}的来源"><small>Q${bit.position}</small><b>${bit.value}</b><span>${bit.kind==='pending'?'待移入':'已生成商位'}</span></button>`).join('')}</div><p data-divide-q-detail role="status">点击任意Q位，追踪它来自原被除数哪一位，或哪一轮生成的商位。</p><p>被除数原始位：${Array.from(original, (v,i)=>`<span class="an-divide-prefix ${i<q.k?'processed':''}">${v}</span>`).join('')}；已处理前 ${q.k} 位。</p><p data-divide-prefix-invariant>已处理前缀 ${q.prefix} = 除数 ${m.d} × 当前商段 ${q.partial} + 保存余数 ${m.r}。</p><small>这个等式每轮都成立；四轮后所有被除数位均已处理，Q才成为完整商。</small></section>`;
}

function anatomyRouteNextContext(current,next,path){
 const direct=current.parts.filter(p=>p.ref===next);if(direct.length)return {instances:direct,ancestorIndex:null,parentId:current.id};
 for(let i=path.length-2;i>=0;i--){const parent=ANATOMY[path[i]],instances=parent.parts.filter(p=>p.ref===next);if(instances.length)return {instances,ancestorIndex:i,parentId:parent.id}}
 return {instances:[],ancestorIndex:null,parentId:null};
}

function anatomyRouteLink(route,step=1,base=location.href,focus=false){
 if(!route?.key||!Number.isInteger(step)||step<1||step>route.ids.length)throw Error('无效学习路线或步骤');const url=new URL('learn.html',base);url.searchParams.set('route',route.key);url.searchParams.set('step',String(step));if(focus)url.searchParams.set('focus','1');return url.href;
}

function anatomyGateInputPorts(parent,part){
 if(['nand','nor','not','cmos','transmission'].includes(parent?.lab)){const p=parent.parts.find(p=>p.id===part);if(['nmos','pmos'].includes(p?.type))return parent.nets.some(n=>n.to===part+'.g')?['a']:[];if(parent.lab!=='transmission')return []}
 if(!['fulladder','halfadder','xor','and','or','mux','edge','compare','decoder','decoder3','transmission','vga','timingcompare','comparebit','dotselect','cachecheck','tageq5','demorgan','truth2'].includes(parent?.lab))return [];
 const p=parent.parts.find(p=>p.id===part);if(!p||!['and','or','xor','nand','nor','not'].includes(p.ref))return [];
 const keys=p.ref==='not'?['a']:['a','b'];
 return keys.every(key=>parent.nets.some(n=>n.to===part+'.'+key))?keys:[];
}
function anatomyGateInputOrigin(parent,part,parentState,childState,historical=false){
 const keys=anatomyGateInputPorts(parent,part);if(!keys.length)return '';
 const transistor=parent.parts.find(p=>p.id===part),isTransistor=['nmos','pmos'].includes(transistor.type);
 const e=anatomyEvaluate(parent.id,parentState),escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const rows=keys.map(key=>{const net=parent.nets.find(n=>n.to===part+'.'+(isTransistor?'g':key)),source=e.nets[net.name],local=childState[key];return `<tr data-origin-input="${key}" data-origin-value="${source}" data-local-value="${local}"><th scope="row">${isTransistor?'G（栅极）':key.toUpperCase()}</th><td><button data-trace-parent-net="${escape(net.name)}" aria-label="返回上级并查看信号 ${escape(net.name)}">${escape(net.name)} ↗</button><small>${escape(net.from)} → ${escape(net.to)}</small></td><td>${source} → ${local}<small>${source===local?'与上级一致':'本层已改变'}</small></td></tr>`});
 return `<section class="an-input-origin"><h4>${keys.length===1?'这个输入':'这些输入'}从哪里来？</h4><p>来自上级${escape(parent.title.split(' · ')[0])}的 <b>${escape(part)}</b>。右列比较“上级来源值 → ${historical?'本层回看值':'本层实验值'}”。${historical?'这是跨快照对照，不表示两个值发生在同一时刻。':'修改本层不会反写上级。'}</p><table><thead><tr><th>本层</th><th>上级信号与端口</th><th>值对照</th></tr></thead><tbody>${rows.join('')}</tbody></table>${isTransistor?`<p data-origin-conduction><b>${transistor.type.toUpperCase()}：G=${childState.a} → 理想通路${(transistor.type==='nmos'?childState.a:1-childState.a)?'导通':'断开'}</b>。${transistor.type==='nmos'?'NMOS高电平导通':'PMOS低电平导通'}。这是栅极控制条件，不是栅极向输出输送数据，也不计算真实电流。</p>`:''}<p>点击信号名可返回上级并高亮原连线；“重新读取上级”会用上级当前输入覆盖本层输入。</p></section>`;
}

function anatomyCMOSNetworkLens(b,s){
 if(!['nand','nor','not','cmos'].includes(b.lab))return '';
 const e=anatomyEvaluate(b.id,s),two=['nand','nor'].includes(b.lab),p=two?['P0','P1']:['P'],n=two?['N0','N1']:['N'];
 const pullup=b.lab==='nand'?p.map(id=>[id]):[p],pulldown=b.lab==='nor'?n.map(id=>[id]):[n];
 const connected=paths=>paths.some(path=>path.every(id=>e.switches[id]===1)),up=connected(pullup),down=connected(pulldown);
 function network(paths,upper){
  const height=paths.length*66+26,source=upper?'VDD（1）':'Y',target=upper?'Y':'GND（0）',active=connected(paths);
  return `<div class="an-cmos-network" data-cmos-network="${upper?'up':'down'}" data-connected="${+active}"><b>${upper?'上拉到 VDD':'下拉到 GND'} · ${paths.length>1?'并联：任一路全通即可':paths[0].length>1?'串联：每一只都要通':'单只开关'}</b><svg viewBox="0 0 300 ${height}" role="group" aria-label="${upper?'上拉':'下拉'}网络${active?'接通':'断开'}"><text x="4" y="15">${source}</text><text x="252" y="15">${target}</text><path d="M24 23V${height-16}M276 23V${height-16}" class="an-cmos-wire"/>${paths.map((path,i)=>{const y=45+i*66,on=path.every(id=>e.switches[id]===1);return `<g data-cmos-path="${path.join(',')}" data-connected="${+on}"><path d="M24 ${y}H276" class="an-cmos-wire ${on?'on':''}"/>${path.map((id,j)=>{const x=24+(j+1)*252/(path.length+1),closed=e.switches[id]===1,net=b.nets.find(n=>n.to===id+'.g'),input=net.from.split('.')[0].toLowerCase();return `<g data-cmos-switch="${id}" data-cmos-input="${input}" role="button" tabindex="0" aria-label="${id}，栅极${input.toUpperCase()}=${s[input]}，当前${closed?'导通':'断开'}；切换${input.toUpperCase()}输入"><title>切换 ${input.toUpperCase()}，同步改变接到此输入的所有栅极</title><rect x="${x-30}" y="${y-14}" width="60" height="27" fill="#102936"/><path d="M${x-30} ${y}H${x-16}M${x+16} ${y}H${x+30}M${x-16} ${y}L${x+16} ${closed?y:y-13}" class="an-cmos-wire ${closed?'on':''}"/><text x="${x}" y="${y+27}" text-anchor="middle">${id} · ${closed?'通':'断'}</text><rect class="an-cmos-hit" x="${x-34}" y="${y-23}" width="68" height="55" rx="7"/></g>`}).join('')}</g>`}).join('')}</svg></div>`;
 }
 const parts=[...p,...n];
 return `<section class="an-control-lens an-cmos-lens"><h4>从通断网络推导输出</h4><p>PMOS低电平导通，NMOS高电平导通。点击开关切换驱动它的输入；接到同一输入的管一起变化。绿色开关表示该管导通，不代表整条串联路已经接通。</p>${network(pullup,true)}${network(pulldown,false)}<p data-cmos-verdict data-output="${e.result}">上拉${up?'接通':'断开'}，下拉${down?'接通':'断开'} → Y=${e.result}。${up?'输出被连接到 VDD。':'输出被连接到 GND。'}</p><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><ol>${parts.map(id=>{const net=b.nets.find(net=>net.to===id+'.g');return `<li><button data-control-stage="${id}">${id}：G=${e.nets[net.name]} → ${e.switches[id]?'导通':'断开'}</button></li>`}).join('')}<li><button data-control-stage="Y">输出 Y=${e.result} · ${up?'上拉':'下拉'}网络接通</button></li></ol><small>通表示理想源漏开关接通；不表示电流大小。动画只是讲解顺序，不模拟传播时间和切换时的电流。</small></section>`;
}

function anatomyMUXLens(b,s){
 if(b.id!=='mux')return '';const e=anatomyEvaluate(b.id,s),sel=s.cin&1,chosen=sel?'B':'A',other=sel?'A':'B';
 return `<section class="an-control-lens an-mux-lens"><h4>选择的是来源，不是固定的1</h4><p>SEL=${sel} → 选择 ${chosen}。金色标记被选择的路；路上仍可能传递0。</p><div class="an-mux-routes">${['a','b'].map((key,i)=>`<div class="an-mux-route ${sel===i?'chosen':''}" data-mux-route="${key}" data-chosen="${+(sel===i)}"><button data-mux-toggle="${key}" aria-label="切换${key.toUpperCase()}输入，当前${s[key]}">${key.toUpperCase()} = ${s[key]}</button><span aria-hidden="true">→</span><button data-mux-select="${i}" aria-pressed="${sel===i}">${sel===i?'已选择':'选择此路'}</button><small>${sel===i?'送出 '+s[key]:'被屏蔽，支路贡献0'}</small></div>`).join('')}</div><p class="an-mux-result" data-mux-output="${e.result}">Y = ${chosen} = ${e.result}</p><p>试一试：只改变未选中的 ${other}，Y 不变；改变选中的 ${chosen}，Y 随之改变。两个输入相同时，切换SEL也不会改变Y。</p><div class="an-control-playback"><button data-control-play>播放路径</button><button data-control-next>下一步</button><button data-control-rewind>回到起点</button><span data-control-progress role="status">尚未播放</span></div><ol><li><button data-control-stage="I">反相：~SEL = ${e.nets['~SEL']}</button></li><li><button data-control-stage="G0">A路径：${s.a} · ${e.nets['~SEL']} = ${e.nets['路径0']}</button></li><li><button data-control-stage="G1">B路径：${s.b} · ${sel} = ${e.nets['路径1']}</button></li><li><button data-control-stage="O">合并：${e.nets['路径0']} ∨ ${e.nets['路径1']} = ${e.result}</button></li></ol><small>两个与门支路并行计算；分步播放仅用于讲解，不添加物理传播时间。</small></section>`;
}

function anatomyStorageOriginSupported(parent,part){return parent?.lab==='dff'&&['M','SL'].includes(part)||parent?.lab==='latch'&&part==='M'}
function anatomyStorageInputOrigin(parent,part,parentState,childState,historical=false){
 if(!anatomyStorageOriginSupported(parent,part))return '';const e=anatomyEvaluate(parent.id,parentState),latch=parent.lab==='latch';
 const rows=latch?[['a','A（反馈）','保持反馈',childState.a],['b','B（新数据）','D',childState.b],['cin','SEL','EN',childState.cin]]:[['a','D',part==='M'?'D':'主状态',childState.a],['enable','G',part==='M'?'~CLK':'CLK',childState.enable],['q','当前Q',part==='M'?'主状态':'Q',anatomyEvaluate('latch',childState).result]];
 return `<section class="an-input-origin an-storage-origin"><h4>${latch?'反馈选择器的输入来源':'锁存器的数据、使能与状态来源'}</h4><p>从 ${latch?'锁存器':'触发器'}的 ${part} 展开。上级来源值 → ${historical?'本层回看值；这是跨快照对照':'本层当前值；本层修改不写回上级'}。</p><table><thead><tr><th>本层</th><th>上级信号</th><th>值对照</th></tr></thead><tbody>${rows.map(([key,label,net,local])=>`<tr data-storage-origin="${key}" data-origin-value="${e.nets[net]}" data-local-value="${local}"><th>${label}</th><td><button data-trace-parent-net="${net}" aria-label="返回上级并查看信号 ${net}">${net} ↗</button></td><td>${e.nets[net]} → ${local}</td></tr>`).join('')}</tbody></table><p>点击信号名，返回上级定位该线。</p><p>${latch?'A读取的是当前Q反馈：透明时它已经跟随D，不使用过期的关闭前记录。这个独立MUX没有保存状态，改变选择不会反写上级锁存器。':'G直接带入所选级的互补时钟电平。当前Q是输出状态，不是第三个外部输入；透明时Q跟随本层D。'}</p></section>`;
}

function anatomyPartCurrentValue(b,e,id){
 if(e.partValues?.[id]!==undefined)return e.partValues[id];const part=b.parts.find(p=>p.id===id);
 let nets=b.nets.filter(n=>n.from.startsWith(id+'.')&&e.nets[n.name]!==undefined);
 if(!nets.length&&part?.type==='port')nets=b.nets.filter(n=>n.to.startsWith(id+'.')&&e.nets[n.name]!==undefined);
 if(!nets.length)return '本层未单独计算';const values=[...new Set(nets.map(n=>String(e.nets[n.name])))];return values.length===1?e.nets[nets[0].name]:nets.map(n=>n.from.split('.')[1]+'='+e.nets[n.name]).join('，');
}
function anatomySelectionSummary(b,e,selection,historical=false){
 const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 if(selection?.net){const n=b.nets.find(n=>n.name===selection.net);if(!n)return '';return `<div role="status"><small>${historical?'历史快照':'当前选线'} · ${n.bits}位</small><b>${esc(n.name)} = ${esc(e.nets[n.name]??'本层未计算')}</b><span>${esc(n.from)} → ${esc(n.to)}</span></div><div><button data-summary-part="${esc(n.from.split('.')[0])}">定位发送端</button><button data-summary-part="${esc(n.to.split('.')[0])}">定位接收端</button><button data-summary-detail>详细说明 ↓</button><button data-summary-clear>恢复导览</button></div>`}
 if(selection?.part){const p=b.parts.find(p=>p.id===selection.part);if(!p)return '';return `<div role="status"><small>${historical?'历史快照':'当前器件'}</small><b>${esc(p.id)} · ${esc(p.label)}</b><span>当前值：${esc(anatomyPartCurrentValue(b,e,p.id))}</span></div><div>${p.ref?'<button data-summary-enter>继续展开 →</button>':''}<button data-summary-detail>详细说明 ↓</button><button data-summary-clear>恢复导览</button></div>`}return '';
}

function anatomyPredictionReportMarkup(a){
 if(!a)return '';const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),conclusion=a.verification===true?(a.predictionCorrect?'预测正确，模型核验通过':'预测与观察不同，模型核验通过'):a.verification===false?'模型核验不一致，请复核':a.started?'尚未完成核验':'尚未开始';
 return `<section class="exercise-report"><h2>本次预测练习记录</h2><p class="meta">练习记录独立于上方电路快照。导出历史电路时，不把本次练习的后续步骤当成该历史时刻已经发生。${a.conditionsStillCurrent?'练习条件与当前运行现场一致。':'当前运行条件与练习末次记录不同，或练习尚未开始；以下保留已执行快照。'}</p><p><b>题目：</b>${esc(a.question)}</p><p><b>我的预测：</b>${esc(a.prediction)}</p><p><b>进度：</b>${esc(a.completed)} / ${esc(a.planned)} 步；<b>结论：</b>${conclusion}</p><p>${esc(a.status)}</p>${a.rows.length?`<table><caption>已执行观察 · 顺序不是物理时间</caption><thead><tr><th>步</th><th>实际操作</th><th>实际输出</th><th>模型操作计数</th><th>相关观察</th></tr></thead><tbody>${a.rows.map((r,i)=>`<tr><td>${i}</td><td>${esc(r.label)}</td><td>${esc(r.result)}</td><td>${esc(r.ticks)}</td><td>${esc(r.observed)}</td></tr>`).join('')}</tbody></table>`:'<p>尚无已执行步骤。</p>'}</section>`;
}

function anatomyRegisterBitOrigin(parent,part,parentState,childState,historical=false){
 if(parent?.id!=='register8'||!/^([CF])[0-7]$/.test(part))return '';const bit=Number(part.slice(1)),control=part[0]==='C',e=anatomyEvaluate(parent.id,parentState);
 const rows=control?[['a','原始D','D'+bit,childState.a],['b','反馈Q','反馈'+bit,childState.b],['enable','CE','CE'+bit,childState.enable],['reset','RESET','RESET'+bit,childState.reset]]:[['a','待采样D','候选'+bit,childState.a],['q','已保存Q','Q'+bit,childState.q]];
 const byte=(value,label)=>`<div class="an-origin-byte"><b>${label} = ${value}</b><div>${Array.from({length:8},(_,j)=>{const i=7-j;return `<span data-regbit-index="${i}" ${i===bit?'aria-current="true"':''}><small>bit${i}</small><strong>${(value>>>i)&1}</strong></span>`}).join('')}</div></div>`;
 return `<section class="an-input-origin an-register-bit-origin"><h4>${part} 对应整个字节的 bit${bit}</h4><p>金色标出当前位，左边是高位bit7。展开时的上级字节 → ${historical?'本层历史快照（跨快照对照）':'本层独立实验'}。</p>${byte(parentState.av&255,'原始D')}${byte(parentState.reg8Q&255,'已保存Q')}<table><thead><tr><th>本层量</th><th>上级信号</th><th>上级 → 本层</th></tr></thead><tbody>${rows.map(([key,label,net,local])=>`<tr data-regbit-origin="${key}" data-origin-value="${e.nets[net]}" data-local-value="${local}"><th scope="row">${label}</th><td><button data-trace-parent-net="${net}">${net} ↗</button></td><td>${e.nets[net]} → ${local}</td></tr>`).join('')}</tbody></table><p>${control?'本层组合选择不保存数据：RESET优先CE，最终只得到下一边沿候选。':'D已包含上级CE/RESET选择。CLK从0开始，是独立的触发器时钟；点击它的上升沿只保存这一位的局部副本。'}局部修改不反写整个字节，重新读取可恢复上级对应值。</p></section>`;
}

function anatomyControlMUXOrigin(parent,part,parentState,childState,historical=false){
 if(parent?.id!=='registerControl'||!['EN','RESET'].includes(part))return '';const e=anatomyEvaluate(parent.id,parentState),enable=part==='EN',rows=enable?[['a','A · CE=0选保存Q','保存反馈',childState.a],['b','B · CE=1选原始D','原始D',childState.b],['cin','SEL · CE','使能选择',childState.cin]]:[['a','A · RESET=0选前级','CE后候选',childState.a],['b','B · RESET=1选常量0','清零常量',childState.b],['cin','SEL · RESET','复位选择',childState.cin]];
 return `<section class="an-input-origin an-control-mux-origin"><h4>${enable?'第一层：CE选择保持或输入':'第二层：RESET覆盖前级候选'}</h4><p>来自一位保存控制的 ${part}。上级来源值 → ${historical?'本层回看值（跨快照对照）':'本层独立实验值'}。</p><table><thead><tr><th>本层输入</th><th>上级信号</th><th>值对照</th></tr></thead><tbody>${rows.map(([key,label,net,local])=>`<tr data-control-origin="${key}" data-origin-value="${e.nets[net]}" data-local-value="${local}"><th scope="row">${label}</th><td><button data-trace-parent-net="${net}">${net} ↗</button></td><td>${e.nets[net]} → ${local}</td></tr>`).join('')}</tbody></table><p>${enable?'CE=0时保留Q作为候选，CE=1时采用原始D；随后仍须经过RESET选择。':'RESET=1时直接选常量0，前级CE后候选即使为1也不能穿过，所以RESET优先于CE。'}这两层只计算候选，不是保存边沿。独立修改不写回上级，可重新读取恢复。</p></section>`;
}

function anatomyOriginReportMarkup(source){
 if(!source||!ANATOMY[source.parent])return '';const b=ANATOMY[source.parent],part=b.parts.find(p=>p.id===source.part);if(!part)return '';
 const e=anatomyEvaluate(b.id,source.state),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),nets=b.nets.filter(n=>n.to.startsWith(part.id+'.')||n.from.startsWith(part.id+'.'));
 return `<section class="origin-report"><h2>展开入口与来源观察</h2><p class="meta">上级：${esc(b.title)}；实例：${esc(part.id)} · ${esc(part.label)}<br>来源：${source.historical?'历史观察 #'+esc(source.serial):'展开时的现场快照'}<br>这是展开时保存的上级来源，不是上级导出时的现场，也不随本层操作改写。本报告的本层状态可以晚于这份来源快照。</p><p>以下只列该实例在上级的相关信号，不把父子原理模型当作同一可写实例；具体输入复制规则以模块说明为准。</p>${nets.length?`<table><thead><tr><th>上级信号</th><th>端点</th><th>位宽</th><th>展开时值</th></tr></thead><tbody>${nets.map(n=>`<tr><td>${esc(n.name)}</td><td>${esc(n.from)} → ${esc(n.to)}</td><td>${n.bits}</td><td>${esc(e.nets[n.name]??'本层未计算')}</td></tr>`).join('')}</tbody></table>`:'<p>此抽象层没有单独命名连接，未推测输入值。</p>'}</section>`;
}

function anatomySyncFrame(s,part=null,interactive=false){
 const cards=[['IN','原始输入',s.a,s.a],['F1','SYNC1保存',s.s1,s.a],['F2','SYNC2保存',s.s2,s.s1]];
 return `<div class="an-sync-states">${cards.map(([id,label,value,next])=>`<div data-sync-stage="${id}" ${id===part?'aria-current="true"':''}><small>${label}</small><b>${value}</b>${id==='IN'?'<span>当前原始电平</span>':`<span>下一边沿候选：${next}</span>`}${interactive&&id!=='IN'?`<button data-sync-focus="${id}">定位 ${id}</button>`:''}</div>`).join('')}</div><p data-sync-next>同一个下一边沿：SYNC1 ← ${s.a}（原始输入），SYNC2 ← ${s.s1}（边沿前SYNC1），不是先写SYNC1再让新值穿到SYNC2。</p>`;
}
function anatomySynchronizerLens(b,s){
 if(b.id!=='synchronizer')return '';return `<section class="an-sync-lens"><h4>两个触发器，同一边沿读取旧状态</h4>${anatomySyncFrame(s,null,true)}<p>改输入不会立即改变保存值。一次采样后，再对比当前保存与下一边沿候选。</p><small>这里只演示数字采样次序，不模拟亚稳态电压或MTBF；两级同步也不等于按键消抖。</small></section>`;
}
function anatomySynchronizerOrigin(parent,part,parentState,childState,historical=false){
 if(parent?.id!=='synchronizer'||!['F1','F2'].includes(part))return '';const first=part==='F1',data=first?parentState.a:parentState.s1,saved=first?parentState.s1:parentState.s2,net=first?'异步数据':'前级输出';
 return `<section class="an-input-origin an-sync-origin"><h4>${part} 在两级同步链中的位置</h4>${anatomySyncFrame(parentState,part)}<table><thead><tr><th>本层量</th><th>上级来源</th><th>来源 → 本层</th></tr></thead><tbody><tr data-sync-origin="a" data-origin-value="${data}" data-local-value="${childState.a}"><th>D</th><td><button data-trace-parent-net="${net}">${net} ↗</button></td><td>${data} → ${childState.a}</td></tr><tr data-sync-origin="q" data-origin-value="${saved}" data-local-value="${childState.q}"><th>保存Q</th><td>${part}保存状态</td><td>${saved} → ${childState.q}</td></tr></tbody></table><p>${first?'第一级采样原始输入。':'第二级D来自第一级的已保存值，不直接取原始输入；两个触发器同时采样时，第二级使用第一级边沿前的值。'}${historical?'本层正在回看历史，与来源是跨快照对照。':''}本层时钟从低电平开始，独立操作不推进上级同步链；重新读取可恢复上级现场。</p></section>`;
}

function anatomyDebounceLens(b,s){
 if(b.id!=='debounce')return '';const n=anatomyDebouncePreview(s);
 return `<section class="an-debounce-lens"><h4>连续3次相同采样，才接受新电平</h4><div class="an-debounce-state"><span>输入<b>${s.a}</b></span><span>保存候选<b>${s.candidate}</b></span><span>连续次数<b data-debounce-count>${s.consecutive}</b></span><span>稳定输出<b data-debounce-stable>${s.stable}</b></span></div><div class="an-debounce-count-dots" aria-label="当前连续次数${s.consecutive}，教学阈值3">${[1,2,3].map(i=>`<span class="${s.consecutive>=i?'filled':''}">${i}</span>`).join('')}</div><p>${n.same?'输入与保存候选相同，下一采样继续累计。':'输入与保存候选不同，下一采样更换候选，连续次数从1重新开始。'}</p><p data-debounce-next>下一边沿：候选=${n.candidate}，次数=${n.count}，稳定输出=${n.stable}。${n.ready?'已满足3次条件，本边沿可提交该电平。':'还不满足3次条件，稳定输出保持。'}</p><div><button data-debounce-focus="CMP">比较输入</button><button data-debounce-focus="COUNT">查看计数</button><button data-debounce-focus="ST">查看保存输出</button></div><small>圆点是已保存采样次数；图中ready“到达阈值”是下一次采样的提交条件，不是提前保存。阈值3仅用于教学，不代表实际消抖时间。</small></section>`;
}

function anatomyEdgeLens(b,s){
 if(b.id!=='edge')return '';const event=s.stable&(1-s.previous),next=s.a&(1-s.stable);
 return `<section class="an-edge-lens"><h4>比较保存值，长按只产生一次事件</h4><div class="an-edge-values">${[['原始输入',s.a],['本次采样',s.stable],['上次采样',s.previous],['当前按下事件',event]].map(([name,value])=>`<span><small>${name}</small><b>${value}</b></span>`).join('')}</div><p data-edge-equation>press = stable · ~previous = ${s.stable} · ${1-s.previous} = <b data-edge-event>${event}</b></p><p>下一采样边沿：stable ← ${s.a}，previous ← ${s.stable}，事件候选 ${next}。改原始输入本身不改写保存值。</p><div><button data-edge-focus="S">当前采样级</button><button data-edge-focus="D">延迟采样级</button><button data-edge-focus="G">事件与门</button></div><small>事件按采样间隔保持；下一次采样若仍按住，两个保存值都为1，事件回到0。它不是鼠标按住期间不断产生的多个事件。</small></section>`;
}

function anatomyEdgeOrigin(parent,part,parentState,childState,historical=false){
 if(parent?.id!=='edge'||!['S','D'].includes(part))return '';const current=part==='S',e=anatomyEvaluate(parent.id,parentState),rows=[['a','D（下一采样来源）',current?'待采样输入':'延迟采样',childState.a],['q','Q（已保存）',current?'当前':'上一拍',childState.q]];
 return `<section class="an-input-origin an-edge-origin"><h4>${current?'S：当前采样级':'D：上一采样级'}的来源</h4><p>展开时：原始输入 ${parentState.a}；当前保存 stable=${parentState.stable}；上一保存 previous=${parentState.previous}。${historical?'本层回看值与来源是跨快照对照。':''}</p><table><thead><tr><th>本层量</th><th>上级信号</th><th>来源 → 本层</th></tr></thead><tbody>${rows.map(([key,label,net,local])=>`<tr data-edge-origin="${key}" data-origin-value="${e.nets[net]}" data-local-value="${local}"><th scope="row">${label}</th><td><button data-trace-parent-net="${net}">${net} ↗</button></td><td>${e.nets[net]} → ${local}</td></tr>`).join('')}</tbody></table><p>${current?'当前采样级D取原始输入。':'延迟采样级D取当前级的边沿前保存值，不直接取原始输入。'}独立CLK从0开始，上升沿只更新本层Q，不推进上级事件状态。重新读取恢复上级现场。</p></section>`;
}

function anatomyScanLens(b,s){
 if(!['scan','sevenseg'].includes(b.id))return '';
 const e=anatomyEvaluate(b.id,s),nibble=(s.word>>>(s.digit*4))&15,seg=(~AN_SEG[nibble])&127,an=s.scanPhase===2?15^(1<<s.digit):15;
 const polygons=['12,4 46,4 41,10 17,10','47,6 51,10 47,33 41,36 43,13','41,40 47,37 44,63 38,68 36,62','10,69 38,69 43,63 15,63','5,39 11,42 14,61 9,67 4,62','8,7 14,12 11,33 5,36 3,30','12,34 40,34 45,38 39,42 11,42 6,38'];
 return `<section class="an-scan-lens"><h4>一次真正选通哪一位？</h4><p><a href="labs/sevenseg-scan-dots.zip" download>下载含小数点的完整扫描RTL与波形 ↓</a><small>包含三MUX门级小数点选择、消隐与位选。另有 <a href="labs/dotselect.zip" download>独立小数点电路</a> 和 <a href="labs/sevenseg-scan.zip" download>原版dp固定关闭的扫描器</a>。均为功能仿真参考，尚未验证实际上板。</small></p><svg viewBox="0 0 300 136" role="img" aria-label="当前只显示真实选通位，消隐时四位全灭">${[3,2,1,0].map((digit,index)=>{const lit=s.scanPhase===2&&s.digit===digit,mask=lit?AN_SEG[(s.word>>>(digit*4))&15]:0,x=6+index*74;return `<g transform="translate(${x} 8)" data-scan-digit="${digit}" data-lit="${lit}"><rect x="0" y="0" width="66" height="86" rx="7" fill="#111f28" stroke="${s.digit===digit?'#f4d27c':'#486575'}"/>${polygons.map((points,bit)=>`<polygon transform="translate(5 4)" points="${points}" fill="${mask&(1<<bit)?'#ff665c':'#332e35'}"/>`).join('')}<circle data-scan-dot="${digit}" cx="59" cy="77" r="3" fill="${lit&&((s.scanDots||0)&(1<<digit))?'#ff665c':'#332e35'}"/><text x="33" y="103" text-anchor="middle">AN${digit}=${(an>>>digit)&1}</text><text x="33" y="120" text-anchor="middle">字中数字 ${((s.word>>>(digit*4))&15).toString(16).toUpperCase()}</text></g>`}).join('')}</svg><p data-scan-phase>当前：${['消隐 · 四位全关','准备共享段码 · 四位仍关','点亮 · 仅目标位选通'][s.scanPhase]}。</p><div class="an-scan-pins"><span>AN[3:0] <b data-scan-an>${an.toString(2).padStart(4,'0')}</b></span><span>seg[g:f:e:d:c:b:a] <b data-scan-seg>${seg.toString(2).padStart(7,'0')}</b></span></div><p>目标AN${s.digit}取 word[${s.digit*4+3}:${s.digit*4}]=${nibble.toString(16).toUpperCase()}。位选0接通，段线0点亮；当前dp=<b data-scan-dp>${1-((s.scanDots||0)>>>s.digit&1)}</b>，消隐时即使dp=0也不发光。</p><div class="an-timing-presets">${[3,2,1,0].map(bit=>`<button data-scan-dot-toggle="${bit}" aria-pressed="${!!((s.scanDots||0)&(1<<bit))}">AN${bit} 小数点${((s.scanDots||0)&(1<<bit))?'开':'关'}</button>`).join('')}</div><p>上图不叠加视觉暂留。每次推进只走一个教学阶段，不是100MHz时钟的一拍；没有计算亮度、电流或真实刷新率。</p><button data-scan-play aria-pressed="false">播放一轮扫描</button><p data-scan-play-status role="status">每轮12个教学阶段。</p></section>`;
}

function anatomySegmentLens(b,s){
 if(b.id!=='segmentdecode')return '';const value=s.av&15,mask=AN_SEG[value],seg=(~mask)&127,points=['25,10 75,10 66,20 34,20','78,13 87,23 80,62 69,68 73,27','69,77 81,69 76,112 65,123 60,112','25,126 64,126 74,115 32,115','15,76 25,83 30,110 20,121 11,111','20,14 31,24 25,60 14,67 10,56','26,63 66,63 76,72 64,81 25,81 15,72'],labels=[[50,8],[94,43],[88,99],[49,141],[5,100],[4,43],[48,75]];
 return `<section class="an-segment-lens"><h4>点击每一段，追到输出位</h4><svg viewBox="0 0 120 153" role="group" aria-label="七段输出逐段观察">${points.map((p,i)=>`<g role="button" tabindex="0" data-segment-inspect="${i}" aria-label="${'abcdefg'[i]}段，seg[${i}]=${(seg>>>i)&1}，${mask&(1<<i)?'亮':'灭'}"><polygon points="${p}" fill="${mask&(1<<i)?'#ff6c60':'#34404b'}"/><text x="${labels[i][0]}" y="${labels[i][1]}" text-anchor="middle">${'abcdefg'[i]}</text></g>`).join('')}</svg><p>数字 ${value.toString(16).toUpperCase()} → seg[g:f:e:d:c:b:a]=<b data-segment-code>${seg.toString(2).padStart(7,'0')}</b></p><div class="an-segment-list">${Array.from('abcdefg',(name,i)=>`<button data-segment-inspect="${i}" aria-label="查看${name}段">${name} / bit${i} = ${(seg>>>i)&1} · ${mask&(1<<i)?'亮':'灭'}</button>`).join('')}</div><p data-segment-detail role="status">选择一段查看：本接口0为点亮请求，1为关闭请求。实体发光还要求该位的位选接通。</p><small>只读查看输出位；不修改数字、段码表或位选。dp小数点不在这七位中。</small><button data-segment-expand>展开 a 段的一输出 LUT →</button></section>`;
}
function mountAnatomySegmentLens(host,s,expand=()=>{}){
 const lens=host.querySelector('.an-segment-lens');if(!lens)return;let probe=0;lens.querySelector('[data-segment-expand]').onclick=()=>expand(probe);
 const inspect=node=>{const bit=Number(node.dataset.segmentInspect),seg=(~AN_SEG[s.av&15])&127,value=(seg>>>bit)&1;probe=bit;lens.querySelector('[data-segment-expand]').textContent='展开 '+ 'abcdefg'[bit]+' 段的一输出 LUT →';lens.querySelector('[data-segment-detail]').textContent='段 '+ 'abcdefg'[bit]+' 对应 seg['+bit+']，当前='+value+'：'+(value?'关闭请求。':'点亮请求；位选也接通时才发光。');lens.querySelectorAll('[data-segment-inspect]').forEach(n=>{const selected=Number(n.dataset.segmentInspect)===bit;n.classList.toggle('selected',selected);n.setAttribute('aria-pressed',String(selected))});};
 lens.querySelectorAll('[data-segment-inspect]').forEach(node=>{node.onclick=()=>inspect(node);if(node.tagName.toLowerCase()!=='button')node.onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();inspect(node)}}});
}

function anatomyVGALens(b,s){
 if(b.lab!=='vga')return '';const v=anatomyVGAPlan(s),o=anatomyVGAOutput(s),color=s.vgaSource==='framebuffer'?'#000':'#'+s.rgb.toString(16).padStart(3,'0'),presets=[[639,0,'可见末像素'],[640,0,'横前肩'],[656,0,'HS开始'],[752,0,'HS结束'],[799,479,'可见末行末尾'],[0,480,'纵前肩'],[0,490,'VS开始'],[0,492,'VS结束'],[799,520,'帧末']];
 return `<section class="an-vga-lens" data-vga-pixel="${s.pixel}" data-vga-ticks="${s.ticks}"><h4>640×480：把整帧和同步区一起看</h4>${b.id!=='framebuffer'?'<details class="an-vga-hardware"><summary>硬件参考与验证 ↓</summary><p><a href="labs/vga-prefix-timing.zip" download>逐层比较器 + 行列扫描 + 真实波形</a></p><p><a href="labs/vga-raster-timing.zip" download>基础行列扫描版本</a></p><small>对应纯色组合模式；不包含帧缓冲、像素时钟生成或实体板时序验证。</small></details>':''}<svg viewBox="0 0 320 230" role="img" aria-label="800乘521总扫描区与当前坐标"><rect x="10" y="10" width="300" height="195.375" fill="#172737" stroke="#84a8b7"/><rect x="10" y="10" width="240" height="180" fill="${color}" opacity=".8"/><rect x="256" y="10" width="36" height="195.375" fill="#d2ad6a" opacity=".35"/><rect x="10" y="193.75" width="300" height=".75" fill="#f0bf6d"/><path d="M${10+v.x*.375} 10V205.375M10 ${10+v.y*.375}H310" stroke="#fff0b0" stroke-width="1"/><circle cx="${10+v.x*.375}" cy="${10+v.y*.375}" r="3" fill="#fff4aa"/><text x="20" y="29">可见区 640×480</text><text x="160" y="222" text-anchor="middle">当前 (${v.x}, ${v.y}) · 总扫描 800×521</text></svg><p>横向：${v.hzone}；纵向：${v.vzone}。</p><div class="an-vga-signals"><span>HS <b data-vga-hs>${o.hs}</b></span><span>VS <b data-vga-vs>${o.vs}</b></span><span>ACTIVE <b data-vga-active>${o.active}</b></span><span>实际RGB <b data-vga-rgb>0x${o.rgb.toString(16).padStart(3,'0')}</b></span></div><p>计数 x=${v.x.toString(2).padStart(10,'0')}，y=${v.y.toString(2).padStart(10,'0')}；均需10位。可见区地址：${v.address===null?'无效，不访问帧缓冲':v.address}。</p><div class="an-vga-steps"><button data-vga-advance="line" ${s.vgaCountEnable===0?'disabled':''}>推进至下一行</button><button data-vga-advance="frame" ${s.vgaCountEnable===0?'disabled':''}>推进至下一帧</button></div><p>批量推进只保存终点观察，不虚构中间波形；操作计数仍累计实际像素数。</p><details><summary>从边界重新开始实验</summary><p>下面的定位是实验初始条件注入，清空本层观察历史及操作计数，不是电路跳转指令。</p><div class="an-vga-presets">${presets.map(([x,y,label])=>`<button data-vga-start="${y*800+x}">${label} (${x},${y})</button>`).join('')}</div></details><details><summary>模式参数与来源</summary><table><thead><tr><th>区间</th><th>横像素</th><th>纵行</th></tr></thead><tbody><tr><td>可见</td><td>0…639</td><td>0…479</td></tr><tr><td>前肩</td><td>640…655</td><td>480…489</td></tr><tr><td>低有效同步</td><td>656…751</td><td>490…491</td></tr><tr><td>后肩</td><td>752…799</td><td>492…520</td></tr></tbody></table><p>采用<a href="https://digilent.com/reference/_media/basys3%3A%20basys3_rm.pdf" target="_blank" rel="noopener">Digilent手册图14示例</a>：25MHz，800×521总扫描，约59.98Hz。纵后肩29行；未混用常见525行模式。</p></details><small>${s.vgaSource==='framebuffer'?'总览黑底不代表完整存储图像，具体像素请看下方RAM窗口。':'图中颜色是整块纯色候选，不是已写入的帧缓冲。'}金色带为同步区；场同步仅2行，按真实比例很薄。纯色模式无保存延迟；帧缓冲模式同步保存颜色和控制。未模拟像素时钟电路或模拟电平。</small>${anatomyVGAFrameLens(s)}</section>`;
}

function anatomyVGAFrameLens(s){
 const o=anatomyVGAOutput(s),v=anatomyVGAPlan(s),baseX=Math.min(632,Math.floor(v.x/8)*8),baseY=Math.min(472,Math.floor(v.y/8)*8),hex=n=>'0x'+n.toString(16).padStart(3,'0');
 return `<section class="an-vga-frame"><h4>像素存储与同步读出</h4><label>输出来源<select data-vga-source><option value="uniform" ${s.vgaSource!=='framebuffer'?'selected':''}>纯色组合（无保存延迟）</option><option value="framebuffer" ${s.vgaSource==='framebuffer'?'selected':''}>帧缓冲同步读（控制一起保存）</option></select></label><p>切换来源清空观察历史和输出流水有效位，保留RAM及当前坐标。RAM为640×480×12位逻辑存储；未载入图像时未写地址为0。浏览器用图像基底加稀疏改写保存，不声称能完整放入此FPGA片内RAM。</p>${s.vgaSource==='framebuffer'?`<button data-vga-counter-toggle>扫描计数使能 = ${s.vgaCountEnable}</button><p>关闭计数使能只冻结x/y，RAM读写与输出保存仍在每个像素边沿进行。</p><label>写地址 0…307199<input data-vga-write-field="vgaWriteAddress" value="${s.vgaWriteAddress}" inputmode="numeric"></label><label>待写12位RGB（支持0x）<input data-vga-write-field="vgaWriteData" value="${hex(s.vgaWriteData)}"></label><button data-vga-write-toggle>写使能 WE = ${s.vgaWriteEnable}</button><button data-vga-scan-selected>从所选地址重建扫描起点</button><small>重建起点清空观察历史和输出有效位，不是硬件计数跳转。</small><p>只准备输入不写入。用上方“下一像素”提交共同读写边沿；WE保持1会在每个边沿重复写入。</p><p data-vga-pipeline>读请求 (${v.x},${v.y}) 地址=${v.address??'无效'}，RAM候选=${hex(v.rgb)}；保存输出 (${o.x},${o.y}) RGB=${hex(o.rgb)}，VALID=${o.valid}，HS/VS/ACTIVE=${o.hs}/${o.vs}/${o.active}。</p>${s.vgaLast?`<div data-vga-last>最近边沿#${s.vgaLast.edge}：先读地址${s.vgaLast.readAddress??'无效'}，保存${hex(s.vgaLast.readValue)}；${s.vgaLast.write?'随后写 RAM['+s.vgaLast.write.address+']：'+hex(s.vgaLast.write.before)+' → '+hex(s.vgaLast.write.after):'没有写入'}。</div>`:'<p data-vga-last>尚未给RAM读写边沿，输出VALID=0。</p>'}${anatomyVGAEdgeMarkup(s,true)}<section class="an-vga-image-loader"><h4>用本地图像重建RAM初始内容</h4><button data-vga-demo-image>载入内置色条图（重建RAM）</button><a href="assets/vga-rgb-demo.png" download>下载测试图PNG</a><label>选择PNG / JPEG / WebP图像<input data-vga-image-input type="file" accept="image/png,image/jpeg,image/webp"></label><p>只在本地读取。将按最近邻等比例缩放并居中放入640×480（不插值生成新颜色），空白与透明区域合成黑色；每通道8位取高4位，得到RGB444。载入会替换RAM、清空观察历史、重置输出及边沿计数，不冒充硬件写入过程。</p><p data-vga-image-status role="status">${s.vgaImageImport?'已载入 '+anLearningEscape(s.vgaImageImport.name)+'；原图 '+s.vgaImageImport.width+'×'+s.vgaImageImport.height+'；映射区域 ('+s.vgaImageImport.fit.x+','+s.vgaImageImport.fit.y+') '+s.vgaImageImport.fit.width+'×'+s.vgaImageImport.fit.height+'。':'尚未载入图像；也可继续逐像素准备并写入。'}</p><small>图像上限20MiB、1600万像素。输出PNG体现RGB444量化后的颜色，不保证与原图逐通道完全相同。实验报告会包含量化像素、文件名和来源校验值。</small></section><h4>完整RAM像素内容</h4><canvas data-vga-frame-canvas data-observe-section width="640" height="480" class="an-vga-frame-canvas" role="img" aria-label="640乘480帧缓冲内容，点击放大查看像素"></canvas><button data-vga-preview-open data-observe-section>放大画布 / 查看像素 / 导出PNG</button><p>此图为RAM内容，未模拟显示器暂留；颜色可能与当前延迟输出不同。</p><h4>RAM局部窗口 (${baseX},${baseY}) 起8×8</h4><div class="an-vga-memory-grid">${Array.from({length:64},(_,i)=>{const x=baseX+i%8,y=baseY+Math.floor(i/8),addr=y*640+x,value=anatomyVGAMemory(s,addr);return `<button data-vga-memory-address="${addr}" style="background:#${value.toString(16).padStart(3,'0')}" aria-label="RAM[${addr}] RGB=${hex(value)}；点击仅准备写地址" title="(${x},${y}) RAM[${addr}] ${hex(value)}" ${addr===s.vgaWriteAddress?'aria-pressed="true"':'aria-pressed="false"'}><span>${value.toString(16).padStart(3,'0')}</span></button>`}).join('')}</div><p>点击色格仅选写地址；不写入或推进。总写入边沿数=${s.vgaWrites}。同址读写采用read-first：读出边沿前旧数据，下一次读才看见新数据。</p><button data-vga-clear-memory>清空RAM并重新开始实验</button>`:'<p>选择帧缓冲后可逐像素写入，观察RAM与扫描输出之间的一拍对齐。</p>'}<p data-vga-memory-error role="status"></p></section>`;
}

const AN_VGA_BASE_CANVASES=new Map();
function anatomyVGAPaintMemory(canvas,memory,baseline=''){
 const context=canvas.getContext('2d',{alpha:false});context.imageSmoothingEnabled=false;
 if(baseline){let image=AN_VGA_BASE_CANVASES.get(baseline);if(!image){image=context.createImageData(640,480);for(let address=0;address<307200;address++){const value=parseInt(baseline.slice(address*3,address*3+3),16),offset=address*4;image.data[offset]=((value>>>8)&15)*17;image.data[offset+1]=((value>>>4)&15)*17;image.data[offset+2]=(value&15)*17;image.data[offset+3]=255;}AN_VGA_BASE_CANVASES.set(baseline,image);if(AN_VGA_BASE_CANVASES.size>2)AN_VGA_BASE_CANVASES.delete(AN_VGA_BASE_CANVASES.keys().next().value);}context.putImageData(image,0,0);}else{context.fillStyle='#000';context.fillRect(0,0,640,480);}
 for(const [key,value]of Object.entries(memory||{})){const address=Number(key);if(!Number.isInteger(address)||address<0||address>=307200)continue;context.fillStyle='#'+value.toString(16).padStart(3,'0');context.fillRect(address%640,Math.floor(address/640),1,1);}
}
function mountAnatomyVGAPreview(host,s,{blocked,beforeOpen,select}){
 const canvas=host.querySelector('[data-vga-frame-canvas]'),open=host.querySelector('[data-vga-preview-open]');if(!canvas||!open)return;anatomyVGAPaintMemory(canvas,s.vgaFB,s.vgaImageData);
 function show(initial=s.vgaWriteAddress||0){
  beforeOpen();const memory={...(s.vgaFB||{})},baseline=s.vgaImageData||'',snapshot={vgaFB:memory,vgaImageData:baseline},modal=document.createElement('dialog');modal.className='an-vga-preview-dialog';let probe=Math.max(0,Math.min(307199,initial));
  modal.innerHTML='<header><h2>帧缓冲像素快照 · 640×480</h2><button data-vga-preview-close>关闭 ×</button></header><p>显示打开时的RAM内容，不是显示器已扫描出的帧。查看不会写入RAM或推进电路。</p><div class="an-vga-preview-tools"><label>缩放<select data-vga-preview-zoom><option value="fit">适应宽度</option><option value="1">1倍</option><option value="2">2倍</option><option value="4">4倍</option><option value="8">8倍</option></select></label><button data-vga-preview-apply>将所看像素地址用于待写输入</button><button data-vga-preview-png>导出RAM像素PNG</button></div><div class="an-vga-preview-scroll"><div class="an-vga-preview-stage"><canvas class="an-vga-preview-canvas" width="640" height="480" tabindex="0" role="group" aria-label="帧缓冲像素画布，方向键查看相邻像素，Home左上，End右下"></canvas><span data-vga-probe-marker aria-hidden="true"></span></div></div><div class="an-vga-preview-pixel"><span data-vga-probe-swatch aria-hidden="true"></span><p data-vga-preview-readout role="status" aria-live="polite"></p></div><p>点击或方向键只查看像素；选择“用于待写输入”也只准备地址，仍须WE和真正的像素边沿才写入。</p>';
  host.closest('.anatomy-dialog').append(modal);const image=modal.querySelector('canvas'),viewport=modal.querySelector('.an-vga-preview-scroll'),apply=modal.querySelector('[data-vga-preview-apply]');anatomyVGAPaintMemory(image,memory,baseline);apply.disabled=blocked();
  function inspect(){const x=probe%640,y=Math.floor(probe/640),value=anatomyVGAMemory(snapshot,probe);modal.querySelector('[data-vga-preview-readout]').textContent=(blocked()?'历史只读 · ':'')+'像素('+x+','+y+') → RAM['+probe+'] = 0x'+value.toString(16).padStart(3,'0')+'；R='+((value>>>8)&15)+'，G='+((value>>>4)&15)+'，B='+(value&15)+'。';image.dataset.probeAddress=probe;const marker=modal.querySelector('[data-vga-probe-marker]'),scale=(parseFloat(image.style.width)||640)/640;marker.style.left=(x+.5)*scale+'px';marker.style.top=(y+.5)*scale+'px';modal.querySelector('[data-vga-probe-swatch]').style.background='#'+value.toString(16).padStart(3,'0');const px=(x+.5)*scale,py=(y+.5)*scale;if(px<viewport.scrollLeft||px>viewport.scrollLeft+viewport.clientWidth)viewport.scrollLeft=Math.max(0,px-viewport.clientWidth/2);if(py<viewport.scrollTop||py>viewport.scrollTop+viewport.clientHeight)viewport.scrollTop=Math.max(0,py-viewport.clientHeight/2);}
  function zoom(){const value=modal.querySelector('select').value,width=value==='fit'?Math.min(640,viewport.clientWidth):640*Number(value);image.style.width=width+'px';image.style.height=width*.75+'px';if(value!=='fit'){viewport.scrollLeft=Math.max(0,(probe%640)*width/640-viewport.clientWidth/2);viewport.scrollTop=Math.max(0,Math.floor(probe/640)*width/640-viewport.clientHeight/2);}inspect();}
  image.onclick=event=>{const rect=image.getBoundingClientRect(),x=Math.max(0,Math.min(639,Math.floor((event.clientX-rect.left)*640/rect.width))),y=Math.max(0,Math.min(479,Math.floor((event.clientY-rect.top)*480/rect.height)));probe=y*640+x;inspect()};
  image.onkeydown=event=>{const x=probe%640,y=Math.floor(probe/640),keys=['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'];if(!keys.includes(event.key))return;event.preventDefault();event.stopPropagation();probe=event.key==='Home'?0:event.key==='End'?307199:event.key==='ArrowLeft'?y*640+Math.max(0,x-1):event.key==='ArrowRight'?y*640+Math.min(639,x+1):event.key==='ArrowUp'?Math.max(0,y-1)*640+x:Math.min(479,y+1)*640+x;inspect()};
  modal.querySelector('[data-vga-preview-close]').onclick=()=>modal.close();modal.querySelector('select').onchange=zoom;apply.onclick=()=>{if(blocked())return;modal.close();select(probe)};
  modal.querySelector('[data-vga-preview-png]').onclick=()=>image.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='GBU-CS301-framebuffer-640x480.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},'image/png');
  modal.addEventListener('close',()=>{modal.remove();if(open.isConnected)open.focus({preventScroll:true})});modal.showModal();zoom();inspect();image.focus({preventScroll:true});
 }
 open.onclick=()=>show();canvas.onclick=event=>{const rect=canvas.getBoundingClientRect(),x=Math.max(0,Math.min(639,Math.floor((event.clientX-rect.left)*640/rect.width))),y=Math.max(0,Math.min(479,Math.floor((event.clientY-rect.top)*480/rect.height)));show(y*640+x)};
}

function anatomyRasterLens(b,s){
 if(b.id!=='rastercounter')return '';const p=anatomyRasterPlan(s),binary=(v,bits)=>v.toString(2).padStart(bits,'0'),r=s.rasterLast;
 return `<section class="an-raster-lens"><h4>十位共同保存，进位不丢失</h4><p><a href="labs/raster-counter.zip" download>下载十位计数RTL、独立复验与真实波形 ↓</a></p><small>功能参考；起点装载是网页初始化，硬件仅同步复位。尚未验证实体映射和时序。</small><div class="an-raster-bits">${Array.from({length:10},(_,i)=>{const bit=9-i;return `<span><small>Q${bit}</small><b>${(s.rasterQ>>>bit)&1}</b></span>`}).join('')}</div><p>Q=${s.rasterQ}：高2位 ${binary(s.rasterQ>>>8,2)} · 低8位 ${binary(s.rasterQ&255,8)}。</p><p>Q+1=${binary(p.increment,11)}；终值相等=${p.terminal}；D候选=${binary(p.d,10)}；考虑CE/RESET后的下一Q=${p.next}。</p>${r?`<p data-raster-edge>边沿#${r.edge}：旧Q=${r.before}，D候选=${r.d}，CE=${r.enable}，RESET=${r.reset} → 新Q=${r.after}。</p>`:'<p data-raster-edge>尚无共同边沿；修改终值、CE、RESET不会立即改写Q。</p>'}<p>点击主图低八位/高两位，可查看各部分的旧Q和下一D。高两位使用四位寄存器原理的低两位，高两位补0；不是另一套十位计数器。</p><details><summary>逐位展开终值选择</summary><p>每个位都在“加一结果”与常量0之间选择；只复制所选位，CE与RESET仍在保存级控制。</p><div class="an-raster-probes">${Array.from({length:10},(_,i)=>`<button data-raster-probe="${i}">D${i} = ${(p.d>>>i)&1} → 一位MUX</button>`).join('')}</div></details><p>终值比较是Q==LIMIT。若把LIMIT改成比当前Q小，计数不会立即回0，而会经过十位自然回绕后再遇到终值。</p></section>`;
}

function anatomyVGAEdgeMarkup(s,interactive=false){
 const r=s.vgaLast,o=s.vgaOutput;if(!r||!o)return '';const hex=n=>'0x'+n.toString(16).padStart(3,'0'),motion=(path,color)=>interactive?`<circle r="4" fill="${color}" opacity="0"><animateMotion begin="indefinite" dur="1.2s" path="${path}"/><animate attributeName="opacity" begin="indefinite" dur="1.2s" values="1;1;0" keyTimes="0;.95;1"/></circle>`:'',same=r.write&&r.readAddress!==null&&r.write.address===r.readAddress;
 return `<section class="an-vga-edge" data-vga-edge="${r.edge}" data-vga-edge-read="${r.readValue}" data-vga-edge-write="${r.write?.after??''}"><h4>同一边沿的两条数据流 · #${r.edge}</h4><svg viewBox="0 0 300 ${r.write?276:148}" role="img" aria-label="已执行边沿的旧RAM读值和新RAM写入对照"><text x="150" y="17" text-anchor="middle" fill="#294b60" font-size="11">请求 (${r.requestPixel%800},${Math.floor(r.requestPixel/800)}) → 输出同时保存</text><circle cx="54" cy="62" r="27" fill="#${r.readValue.toString(16).padStart(3,'0')}" stroke="#789aaa"/><text x="54" y="104" text-anchor="middle" fill="#294b60" font-size="10">${r.readAddress===null?'无效读：消隐黑':'旧 RAM['+r.readAddress+']'}</text><text x="54" y="119" text-anchor="middle" fill="#294b60" font-size="11">${hex(r.readValue)}</text><path d="M88 62H205m-6 -5 6 5-6 5" fill="none" stroke="#367d91" stroke-width="2"/>${motion('M88 62H205','#2cacc7')}<rect x="218" y="36" width="62" height="52" rx="7" fill="#${o.rgb.toString(16).padStart(3,'0')}" stroke="#52768a"/><text x="249" y="104" text-anchor="middle" fill="#294b60" font-size="10">输出Q</text><text x="249" y="119" text-anchor="middle" fill="#294b60" font-size="11">${hex(o.rgb)}</text><text x="150" y="140" text-anchor="middle" fill="#294b60" font-size="10">HS=${o.hs} · VS=${o.vs} · ACTIVE=${o.active} · VALID=${o.valid}</text>${r.write?`<path d="M14 153H286" stroke="#c1d3da"/><circle cx="54" cy="201" r="27" fill="#${r.write.before.toString(16).padStart(3,'0')}" stroke="#789aaa"/><text x="54" y="244" text-anchor="middle" fill="#294b60" font-size="10">写前 RAM[${r.write.address}]</text><text x="54" y="260" text-anchor="middle" fill="#294b60" font-size="11">${hex(r.write.before)}</text><path d="M88 201H205m-6 -5 6 5-6 5" fill="none" stroke="#7a963f" stroke-width="2"/><text x="150" y="184" text-anchor="middle" fill="#526a36" font-size="10">WE提交${hex(r.write.after)}</text>${motion('M88 201H205','#b0c856')}<rect x="218" y="175" width="62" height="52" rx="7" fill="#${r.write.after.toString(16).padStart(3,'0')}" stroke="#52768a"/><text x="249" y="244" text-anchor="middle" fill="#294b60" font-size="10">写后RAM</text><text x="249" y="260" text-anchor="middle" fill="#294b60" font-size="11">${hex(r.write.after)}</text>`:''}</svg><p>${r.write?(same?'同址读写：输出捕获边沿前旧值，RAM提交新值。下一次有效读才看见新值。':r.readAddress===null?'消隐使输出为黑；独立写端口仍按WE提交。':'读写地址不同：各自处理，不能把写端口数据当成本次读值。'):'本边沿没有写入，输出仍按同步读更新。'}</p>${interactive?'<button data-vga-edge-replay data-observe-section>回放已执行边沿（不推进）</button><p data-vga-edge-status role="status">两条流同一个边沿发生；小球只说明数据关系，不表示电气传播时延。</p>':'<p>静态保存的边沿记录，不含可运行仿真。</p>'}</section>`;
}
function mountAnatomyVGAEdgeReplay(host,pause){
 const button=host.querySelector('[data-vga-edge-replay]');if(!button)return;button.onclick=()=>{pause();const panel=button.closest('.an-vga-edge'),status=panel.querySelector('[data-vga-edge-status]');if(matchMedia('(prefers-reduced-motion: reduce)').matches){status.textContent='减少动态效果已开启，保留静态数据流；没有推进边沿。';return}status.textContent='正在回放同一个已执行边沿；实验状态保持。';panel.querySelector('animateMotion')?.addEventListener('endEvent',()=>{if(panel.isConnected)status.textContent='回放结束；没有新增像素边沿或写入。'},{once:true});panel.querySelectorAll('animateMotion,animate').forEach(node=>node.beginElement())};
}

async function anatomyVGAReadImage(file){
 const supported=['image/png','image/jpeg','image/webp'];if(!file||file.size>20*1024*1024)throw Error('请选择20MiB以内的图像。');if(!supported.includes(file.type))throw Error('请选择PNG、JPEG或WebP图像。');
 let bitmap;try{bitmap=await createImageBitmap(file)}catch{throw Error('图像无法解码，原RAM保留。')}
 try{
  const {width,height}=bitmap;if(width*height>16000000)throw Error('图像超过1600万像素，请先缩小；原RAM保留。');
  const scale=Math.min(640/width,480/height),dw=Math.max(1,Math.round(width*scale)),dh=Math.max(1,Math.round(height*scale)),x=Math.floor((640-dw)/2),y=Math.floor((480-dh)/2),canvas=document.createElement('canvas');canvas.width=640;canvas.height=480;const context=canvas.getContext('2d',{alpha:false});context.fillStyle='#000';context.fillRect(0,0,640,480);context.imageSmoothingEnabled=false;context.drawImage(bitmap,x,y,dw,dh);
  const data=anatomyVGAQuantizeRGBA(context.getImageData(0,0,640,480).data),digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer()),sourceSHA256=Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,'0')).join('');
  return {data,metadata:{name:file.name,width,height,fit:{x,y,width:dw,height:dh},sourceSHA256,quantization:'nearest contain; RGB8 channel >>> 4; black letterbox and alpha composite',format:'RGB444-hex-row-major'}};
 }finally{bitmap.close()}
}
function mountAnatomyVGAImageImport(host,{blocked,commit}){
 const input=host.querySelector('[data-vga-image-input]'),demo=host.querySelector('[data-vga-demo-image]');if(!input)return;let generation=0;
 async function load(source){if(blocked())return;const version=++generation,status=host.querySelector('[data-vga-image-status]');input.disabled=true;demo.disabled=true;status.textContent='正在本地解码并转换为RGB444…';try{const file=typeof source==='function'?await source():source,result=await anatomyVGAReadImage(file);if(version!==generation||!input.isConnected||blocked())return;commit(result)}catch(error){if(version===generation&&input.isConnected)status.textContent=error.message}finally{if(version===generation&&input.isConnected){input.disabled=blocked();demo.disabled=blocked()}}}
 input.onchange=()=>{if(input.files?.length)load(input.files[0])};demo.onclick=()=>load(async()=>{const response=await fetch('assets/vga-rgb-demo.png');if(!response.ok)throw Error('内置测试图暂时无法读取，原RAM保留。');return new File([await response.blob()],'内置色条图.png',{type:'image/png'})});
}

function anatomyPixelWordLens(b,s){
 if(b.id!=='pixelword')return '';const hex=v=>'0x'+v.toString(16).padStart(3,'0'),r=s.pixelLast;
 return `<section class="an-pixelword-lens"><h4>${s.pixelAddress===null?'独立像素字':'RAM['+s.pixelAddress+']'}的十二个保存位</h4><div class="an-pixelword-colors"><span><i style="background:#${s.pixelQ.toString(16).padStart(3,'0')}"></i>保存Q ${hex(s.pixelQ)}</span><span><i style="background:#${s.pixelD.toString(16).padStart(3,'0')}"></i>候选D ${hex(s.pixelD)}</span></div>${[['R',8,'红'],['G',4,'绿'],['B',0,'蓝']].map(([channel,shift,label])=>`<div class="an-pixelword-channel" data-pixelword-channel="${channel}"><h4>${label} ${channel}[3:0] = ${(s.pixelQ>>>shift)&15}</h4><div class="an-pixelword-cells">${[3,2,1,0].map(local=>{const bit=shift+local;return `<div data-pixelword-saved="${bit}"><small>${channel}${local} / bit${bit}</small><b>${(s.pixelQ>>>bit)&1}</b><button data-pixelword-candidate="${bit}" aria-label="翻转候选D${bit}">D=${(s.pixelD>>>bit)&1}</button><button data-pixelword-open="${bit}" data-observe-section aria-label="进入保存位${bit}的SRAM原理">SRAM ↗</button></div>`}).join('')}</div></div>`).join('')}<p>候选D可逐位翻转；保存Q只在本字WE有效的提交边沿更新。进入SRAM会复制所选位Q、D和本字WE；这是独立原理副本。</p>${anatomyPixelWordEdge(s)}${r?`<p data-pixelword-last>边沿#${r.edge}：旧Q=${hex(r.before)}，D=${hex(r.input)}，WE=${r.enable} → 新Q=${hex(r.after)}。</p>`:'<p data-pixelword-last>尚未提交本字写边沿。</p>'}</section>`;
}

function anatomyPixelWordEdge(s){
 const r=s.pixelLast;if(!r)return '';
 const changed=((r.before^r.after)&4095).toString(2).replace(/0/g,'').length;
 return `<section class="an-pixelword-edge" data-pixelword-edge><h4>上次真实边沿 #${r.edge} · ${changed} 位翻转</h4><p>WE=${r.enable}：${r.enable?'十二位同时采样D；输入等于旧值的位保持同值。':'十二位全部保持旧Q；候选D未被写入。'}</p><div class="an-pixelword-edge-grid">${Array.from({length:12},(_,i)=>{const bit=11-i,before=(r.before>>>bit)&1,after=(r.after>>>bit)&1,d=(r.input>>>bit)&1,status=!r.enable?'hold':before!==after?'changed':'same';return `<div data-pixelword-edge-bit="${bit}" data-edge-kind="${status}"><small>${bit>=8?'R':bit>=4?'G':'B'}${bit%4}</small><span>${before} → <b>${after}</b></span><small>D=${d}</small><em>${status==='hold'?'未写入':status==='changed'?'翻转':'写入同值'}</em></div>`}).join('')}</div><button type="button" data-pixelword-replay data-observe-section>↻ 回放这次边沿</button><small data-pixelword-replay-status role="status">回放仅强调这次记录，不推进时钟；十二位同时更新。</small></section>`;
}
function mountAnatomyPixelWordReplay(root){
 const button=root.querySelector('[data-pixelword-replay]');if(!button)return;
 button.onclick=()=>{
  const host=button.closest('[data-pixelword-edge]');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  host.querySelector('[data-pixelword-replay-status]').textContent=reduced?'已展示这次边沿的静态对照；遵循减少动态效果设置。':'正在强调这次记录：十二位同时更新，未产生新时钟。';
  for(const cell of host.querySelectorAll('[data-pixelword-edge-bit]')){
   cell.getAnimations().forEach(a=>a.cancel());if(reduced)continue;
   const color=cell.dataset.edgeKind==='changed'?'#52603a':cell.dataset.edgeKind==='hold'?'#374354':'#245a58';
   cell.animate([{backgroundColor:color,outline:'2px solid #ffe29b'},{backgroundColor:color,outline:'2px solid #ffe29b',offset:.65},{backgroundColor:'#142d39',outline:'0px solid transparent'}],{duration:1100});
  }
 };
}

function anatomySavedEdgeReport(b,s,table){
 const pixel=b.id==='pixelword',r=pixel?s.pixelLast:b.id==='rastercounter'?s.rasterLast:null;
 if(!r||!['pixelword','rastercounter'].includes(b.id))return '';
 const width=pixel?12:10,mask=(1<<width)-1,hex=v=>'0x'+(v&mask).toString(16).padStart(3,'0');
 const mode=pixel?(r.enable?'采样D':'保持旧Q'):r.reset?'同步清零':r.enable?'采样D':'保持旧Q';
 const candidate=pixel?r.input:r.d,changed=((r.before^r.after)&mask).toString(2).replace(/0/g,'').length;
 return '<section data-report-saved-edge="'+b.id+'"><h2>最近一次实际保存边沿</h2><p>边沿 #'+r.edge+' · '+mode+' · '+changed+' 位翻转。以下来自当次边沿记录；上方输入条件是导出所选时刻的输入，之后修改候选不会改写这次记录。</p>'+table(['当次旧Q','当次候选D','当次使能','当次复位','实际新Q'],[[hex(r.before),hex(candidate),r.enable,pixel?'不适用':r.reset,hex(r.after)]])+table(['保存位','旧Q','当次D','新Q','实际行为'],Array.from({length:width},(_,i)=>{const bit=width-1-i,before=(r.before>>>bit)&1,after=(r.after>>>bit)&1,label=pixel?(bit>=8?'R':bit>=4?'G':'B')+(bit%4)+' / bit'+bit:'Q'+bit;return [label,before,(candidate>>>bit)&1,after,!pixel&&r.reset?'同步清零':!r.enable?'未写入':before!==after?'翻转':'写入同值']}))+'<p>这是静态记录；不播放动画，不产生新时钟，不反写上级电路。</p></section>';
}

function anatomyTimingCompareLens(b,s){
 if(b.lab!=='timingcompare')return '';const p=anatomyTimingPlan(b.id,s),visible=b.id==='visiblearea',vertical=b.id==='vsync';
 const presets=visible?[[639,479,'最后可见角'],[640,479,'刚越横界'],[639,480,'刚越纵界'],[640,480,'两个都越界']]:[p.low-1,p.low,p.high-1,p.high].map(v=>[vertical?s.timingX:v,vertical?v:s.timingY,String(v)]);
 const svg=visible?`<svg viewBox="0 0 300 230" role="img" aria-label="局部十位坐标中的可见矩形"><rect x="15" y="15" width="270" height="190" fill="#1b2c3a" stroke="#9cb4c0"/><rect x="15" y="15" width="${270*640/1024}" height="${190*480/1024}" fill="#346f72"/><circle cx="${15+s.timingX*270/1024}" cy="${15+s.timingY*190/1024}" r="4" fill="#ffe39c"/><text x="25" y="32">X&lt;640 且 Y&lt;480</text><text x="150" y="224" text-anchor="middle">独立输入 (${s.timingX},${s.timingY}) · 每轴0…1023</text></svg>`:`<svg viewBox="0 0 300 120" role="img" aria-label="左闭右开低有效同步区间"><rect x="15" y="35" width="270" height="26" fill="#29555f" stroke="#9cb4c0"/><rect x="${15+p.low*270/1024}" y="35" width="${(p.high-p.low)*270/1024}" height="26" fill="#c3a761"/><path d="M${15+p.value*270/1024} 20V75" stroke="#ffe39c" stroke-width="2"/><text x="150" y="95" text-anchor="middle">低有效区间 [${p.low},${p.high}) · 坐标 ${p.value}</text><text x="15" y="17">0</text><text x="285" y="17" text-anchor="end">1023</text></svg>`;
 return `<section class="an-timing-lens"><h4>先预测边界，再改变局部坐标</h4>${anatomyTimingBitInputs(b,s)}${svg}<p data-timing-result>${visible?'ACTIVE':vertical?'VS':'HS'} = <b>${p.result}</b> · ${visible?(p.result?'横纵条件都满足':'至少一个方向不可见'):(p.result?'区间外：同步未有效':'区间内：低有效同步')}</p><div class="an-timing-presets">${presets.map(([x,y,label])=>`<button data-timing-preset="${x},${y}">${label}</button>`).join('')}</div><p>${visible?'640和480这两个边界本身已在可见区外。ACTIVE只判断位置，不表示颜色非黑或RAM输出有效。':'上界'+p.high+'不属于低有效区间；下界'+p.low+'属于。'+(vertical?'纵同步带只有两个坐标单位，按真实比例很薄。':'横同步带宽为96个坐标单位。')}</p><small>输入变化直接重新计算组合输出，不需要时钟；局部范围0…1023是比较原理实验，不改变实际扫描总范围。</small></section>`;
}

function anatomyTimingBitInputs(b,s){
 const axes=b.id==='visiblearea'?['X','Y']:b.id==='vsync'?['Y']:['X'];
 return axes.map(axis=>{const key='timing'+axis,value=s[key],terms=Array.from({length:10},(_,i)=>9-i).filter(bit=>(value>>>bit)&1).map(bit=>2**bit);
 return `<section class="an-timing-bit-input" data-timing-bit-axis="${axis}"><h4>${axis} = ${value} <small>十位无符号输入</small></h4><small class="an-timing-bit-hint">上：位号 · 中：当前值 · 下：位权；左右键移动，空格切换。</small><div class="an-timing-bit-row" role="group" aria-label="${axis}的十个输入位">${Array.from({length:10},(_,i)=>{const bit=9-i,one=(value>>>bit)&1;return `<button type="button" data-timing-bit="${key}:${bit}" aria-pressed="${!!one}" aria-label="${axis}第${bit}位，位权${2**bit}，当前${one}，点击置${1-one}"><small>bit${bit}</small><b>${one}</b><small>${2**bit}</small></button>`}).join('')}</div><p data-timing-weight-sum>${terms.length?terms.join(' + '):'0'} = ${value}</p></section>`;
 }).join('');
}

function anatomyCompare10Lens(b,s){
 if(b.id==='comparebit'){const p=anatomyCompareBitPlan(s);return `<section class="an-compare10-lens"><h4>高位决定后，低位不能推翻</h4><p><a href="labs/compare10-prefix.zip" download>下载前缀比较门级RTL与真实波形 ↓</a></p><p>当前A/B=${s.cmpBitA}/${s.cmpBitB}；高位EQ/LT=${s.cmpPrefixEq}/${s.cmpPrefixLt}。</p><p>EQout = ${s.cmpPrefixEq} AND ${+(s.cmpBitA===s.cmpBitB)} = <b>${p.eq}</b></p><p>LTout = ${s.cmpPrefixLt} OR (${s.cmpPrefixEq} AND ${1-s.cmpBitA} AND ${s.cmpBitB}) = <b>${p.lt}</b></p><p>${s.cmpPrefixEq&&s.cmpPrefixLt?'当前EQ/LT=1/1不是合法的高位比较历史；仍按所画逻辑门计算。':s.cmpPrefixEq?'高位仍相等，当前位可以决定大小。':s.cmpPrefixLt?'高位已经小于，无论当前位如何，LTout保持1。':'高位已经大于，当前位不能改判小于。'}</p><small>这里的保持表示组合条件决定结果，不是触发器保存；没有时钟。可继续展开任意逻辑门。</small></section>`;}
 if(b.id!=='compare10')return '';const p=anatomyCompare10Plan(s);
 const input=(key,label)=>`<section class="an-timing-bit-input"><h4>${label} = ${s[key]}</h4><div class="an-timing-bit-row">${Array.from({length:10},(_,i)=>{const bit=9-i,one=(s[key]>>>bit)&1;return `<button data-cmp10-bit="${key}:${bit}" aria-pressed="${!!one}" aria-label="翻转${label}第${bit}位"><small>${bit}</small><b>${one}</b><small>${2**bit}</small></button>`}).join('')}</div></section>`;
 return `<section class="an-compare10-lens"><h4>从最高位找第一个不同位</h4><p><a href="labs/compare10-prefix.zip" download>下载十位比较RTL、独立复验与真实波形 ↓</a></p><div class="an-cmp10-walk-controls" data-cmp10-walk-controls><button data-cmp10-walk-prev data-observe-section>← 上一级</button><button data-cmp10-walk-next data-observe-section>讲解下一级 →</button><button data-cmp10-walk-play data-observe-section aria-pressed="false">自动讲解</button><button data-cmp10-walk-reset data-observe-section>从最高位重看</button><p data-cmp10-walk-status role="status">尚未开始。讲解不改变输入，不产生时钟。</p></div>${input('cmp10A','A')}${input('cmp10B','B')}<div class="an-timing-presets">${[[511,512],[655,656],[656,656],[1023,0]].map(([a,z])=>`<button data-cmp10-example="${a},${z}">${a} 与 ${z}</button>`).join('')}</div><p data-cmp10-decision>${p.first===null?'所有位相等，EQ=1、LT=0。':'最高不同位是bit'+p.first+'：A位'+((s.cmp10A>>>p.first)&1)+'、B位'+((s.cmp10B>>>p.first)&1)+'，所以A'+(p.lt?'小于':'大于')+'B。更低位不能推翻。'}</p><div class="an-compare10-stages">${p.rows.map(row=>`<button data-cmp10-stage="${row.bit}" data-observe-section class="${row.bit===p.first?'decisive':''}"><b>bit${row.bit} · A/B=${row.a}/${row.b}</b><span>进入 EQ/LT=${row.eqIn}/${row.ltIn} → 输出 ${row.eq}/${row.lt}</span><small>${row.bit===p.first?'最高不同位 · 决定大小':row.eqIn?'高位仍相等':'高位已决定，低位不改判'} · 展开门级 ↗</small></button>`).join('')}</div><small>从上往下是逻辑解释顺序，不是十个保存边沿，也不是软件逐位执行。全部级为组合电路。</small></section>`;
}

function mountAnatomyCompare10Walk(root,s,{focus=()=>{},beforeStart=()=>{}}={}){
 const panel=root.querySelector('[data-cmp10-walk-controls]');if(!panel)return null;
 const rows=anatomyCompare10Plan(s).rows;let index=-1,timer=null,disposed=false;
 const play=panel.querySelector('[data-cmp10-walk-play]'),status=panel.querySelector('[data-cmp10-walk-status]');
 const pause=note=>{if(timer!==null)clearTimeout(timer);timer=null;play.textContent='自动讲解';play.setAttribute('aria-pressed','false');if(note)status.textContent=note};
 const paint=()=>{
  const row=rows[index];root.querySelectorAll('[data-cmp10-stage]').forEach(node=>{node.getAnimations().forEach(a=>a.cancel());const current=!!row&&+node.dataset.cmp10Stage===row.bit;node.classList.toggle('walk-current',current);if(current)node.setAttribute('aria-current','step');else node.removeAttribute('aria-current');});
  panel.querySelector('[data-cmp10-walk-prev]').disabled=index<0;panel.querySelector('[data-cmp10-walk-next]').disabled=index===9;
  if(!row){status.textContent='尚未开始。讲解不改变输入，不产生时钟。';focus(null);return;}
  const first=rows.find(r=>r.a!==r.b),decisive=first?.bit===row.bit;
  status.textContent='第'+(index+1)+'/10级 · bit'+row.bit+'：A/B='+row.a+'/'+row.b+'，进入EQ/LT='+row.eqIn+'/'+row.ltIn+' → 输出'+row.eq+'/'+row.lt+'。'+(decisive?(index===9?'最低位首次不同，大小已决定；没有后续级。':'最高不同位在此，大小已决定；自动讲解会暂停，继续可看低位不能改判。'):row.eqIn?(index===9?'所有十位相等，最终EQ=1、LT=0。':'高位仍相等，继续看更低位。'):'高位已经决定，当前位不能推翻。')+(index===9?' 十级解释完成；没有执行保存边沿。':'');
  focus(row.bit);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const node=root.querySelector('[data-cmp10-stage="'+row.bit+'"]');node.getAnimations().forEach(a=>a.cancel());node.animate([{outline:'2px solid #ffe39c'},{outline:'0px solid transparent'}],{duration:600});}
 };
 const advance=()=>{if(disposed||!root.isConnected||document.hidden){pause('页面不可见或已离开，讲解已暂停。');return false;}if(index<9)index++;paint();const row=rows[index];if(index===9||row.eqIn&&row.a!==row.b){pause();return false;}return true;};
 const schedule=()=>{timer=setTimeout(()=>{timer=null;if(advance())schedule();},1000);play.textContent='暂停讲解';play.setAttribute('aria-pressed','true')};
 panel.querySelector('[data-cmp10-walk-next]').onclick=()=>{beforeStart();pause();advance()};
 panel.querySelector('[data-cmp10-walk-prev]').onclick=()=>{beforeStart();pause();index=Math.max(-1,index-1);paint()};
 panel.querySelector('[data-cmp10-walk-reset]').onclick=()=>{beforeStart();pause();index=-1;paint()};
 play.onclick=()=>{if(timer!==null){pause('讲解已暂停。点击自动讲解继续；输入与时钟不变。');return;}beforeStart();if(index===9)index=-1;if(advance())schedule()};
 const visibility=()=>{if(document.hidden)pause('页面不可见，讲解已暂停。')};document.addEventListener('visibilitychange',visibility);paint();
 return {pause,dispose:()=>{disposed=true;pause();document.removeEventListener('visibilitychange',visibility);root.querySelectorAll('[data-cmp10-stage]').forEach(n=>n.getAnimations().forEach(a=>a.cancel()))}};
}

function anatomyCompareReport(b,s,table){
 if(b.id==='compare10'){
  const p=anatomyCompare10Plan(s),verdict=p.eq?'A等于B':p.lt?'A小于B':'A大于B';
  return '<section data-report-compare="compare10"><h2>十位比较的完整组合前缀</h2><p>A='+s.cmp10A+'（'+s.cmp10A.toString(2).padStart(10,'0')+'），B='+s.cmp10B+'（'+s.cmp10B.toString(2).padStart(10,'0')+'）。'+verdict+'；最终EQ/LT='+p.eq+'/'+p.lt+'。'+(p.first===null?'所有位相等，没有最高不同位。':'最高不同位为bit'+p.first+'，更低位不能推翻这一结论。')+'</p>'+table(['位','A','B','进入EQ','进入LT','输出EQ','输出LT','判断依据'],p.rows.map(r=>['bit'+r.bit,r.a,r.b,r.eqIn,r.ltIn,r.eq,r.lt,r.bit===p.first?'最高不同位：决定'+(p.lt?'小于':'大于'):r.eqIn?(r.bit===0?'所有十位相等':'本位也相等；交给更低位'):'高位已决定；本位不改判']))+'<p>初始EQ=1、LT=0。EQout=EQin AND NOT(A XOR B)；LTout=LTin OR (EQin AND NOT A AND B)。</p><p>表格保存所选快照的完整组合结果，独立于讲解动画播放到哪一级；不是十个时钟、十次采样或执行记录。</p></section>';
 }
 if(b.id==='comparebit'){
  const p=anatomyCompareBitPlan(s),invalid=!!(s.cmpPrefixEq&&s.cmpPrefixLt);
  return '<section data-report-compare="comparebit"><h2>单级前缀的组合判断</h2>'+table(['当前A位','当前B位','进入EQ','进入LT','输出EQ','输出LT'],[[s.cmpBitA,s.cmpBitB,s.cmpPrefixEq,s.cmpPrefixLt,p.eq,p.lt]])+'<p>'+(invalid?'当前进入EQ/LT=1/1不是合法比较前缀；以下只表示手动输入的门真值。':s.cmpPrefixEq?'高位仍相等，当前位有权决定大小。':s.cmpPrefixLt?'高位已小于，当前位不能推翻。':'高位已大于，当前位不能改判小于。')+'</p><p>当前位相等='+ +(s.cmpBitA===s.cmpBitB)+'；当前位小于='+ +(!s.cmpBitA&&s.cmpBitB)+'。EQout='+s.cmpPrefixEq+' AND '+ +(s.cmpBitA===s.cmpBitB)+' = '+p.eq+'；LTout='+s.cmpPrefixLt+' OR ('+s.cmpPrefixEq+' AND '+(1-s.cmpBitA)+' AND '+s.cmpBitB+') = '+p.lt+'。</p><p>这是组合真值，不含触发器保存、时钟或物理延迟。</p></section>';
 }
 return '';
}

function anatomyPWMLens(b,s){
 if(b.id!=='leddriver')return '';const high=s.phase<s.duty;
 const y=phase=>phase<s.duty?24:70,points=Array.from({length:16},(_,phase)=>`${phase?'L':'M'}${32+phase*24} ${y(phase)}H${32+(phase+1)*24}`).join(' ');
 const next=(s.phase+1)&15;
 const wave=`<figure class="an-pwm-wave"><figcaption>一个周期的输出形状 · 横轴为相位</figcaption><svg viewBox="0 0 448 108" role="img" aria-label="PWM组合波形预览，占空比${s.duty}/16，当前相位${s.phase}" data-pwm-wave-duty="${s.duty}"><rect x="${32+s.phase*24}" y="14" width="24" height="66" fill="#f5d67f" opacity=".2"/>${Array.from({length:17},(_,i)=>`<path d="M${32+i*24} 18V80" stroke="#3b5969"/>${i%4===0?`<text x="${32+i*24}" y="99" text-anchor="middle" fill="#bdd2dd" font-size="12">${i===16?'0↻':i}</text>`:''}`).join('')}<text x="10" y="28" fill="#bdd2dd" font-size="12">1</text><text x="10" y="74" fill="#bdd2dd" font-size="12">0</text><path data-pwm-wave-path d="${points}" fill="none" stroke="#78dfbb" stroke-width="3" stroke-linejoin="round"/><circle data-pwm-wave-cursor cx="${44+s.phase*24}" cy="${y(s.phase)}" r="5" fill="#ffe39c"/></svg></figure><p data-pwm-comparison><code>${s.phase.toString(2).padStart(4,'0')}</code>（相位${s.phase}） &lt; <code>${s.duty.toString(2).padStart(5,'0')}</code>（阈值${s.duty}） → 输出${+high}。下一次有效边沿：相位${s.phase} → ${next}${next===0?'，四位计数回绕':''}，输出将为${+(next<s.duty)}。</p>`;

 return `<section class="an-pwm-lens"><h4>一周期16个相位 · 当前phase=${s.phase}</h4>${wave}<div class="an-pwm-cycle" role="img" aria-label="16相位组合预览，当前相位${s.phase}，duty为${s.duty}">${Array.from({length:16},(_,phase)=>`<span data-pwm-phase="${phase}" data-pwm-level="${+(phase<s.duty)}" ${phase===s.phase?'aria-current="step"':''}><small>${phase}</small><b>${+(phase<s.duty)}</b></span>`).join('')}</div><p data-pwm-summary>当前输出=${+high}；完整周期高电平 ${s.duty}/16 = ${s.duty/16*100}%。</p><div class="an-timing-presets">${[0,1,8,15,16].map(duty=>`<button data-pwm-duty="${duty}">${duty}/16${duty===0?' · 全灭':duty===16?' · 全亮':''}</button>`).join('')}</div><p>相位只需四位；阈值16需要五位。若把16截成四位，会变成0，无法表达严格全亮端点。</p><small>方格是当前阈值下的一周期组合预览，不是已经执行的波形。上方推进按钮才增加一个虚拟边沿；占空比不直接等于实际光强或真实频率。</small></section>`;
}

function anatomyDotSelectLens(b,s){
 if(b.id!=='dotselect')return '';const request=(s.av>>>s.bv)&1,group=s.bv>>>1;
 return `<section class="an-dotselect-lens"><h4>先选哪一位，再转换亮灭极性</h4><p><a href="labs/dotselect.zip" download>下载门级RTL、64组验证与VCD波形 ↓</a></p><p>① 点击希望亮的小数点（请求1）</p><div class="an-dotselect-row">${[3,2,1,0].map(bit=>`<button data-dotselect-bit="${bit}" aria-pressed="${!!(s.av&(1<<bit))}"><span class="an-dotselect-dot ${s.av&(1<<bit)?'on':''}">●</span>AN${bit}<b>${(s.av>>>bit)&1}</b></button>`).join('')}</div><p>② 选择当前扫描位置</p><div class="an-dotselect-row">${[3,2,1,0].map(bit=>`<button data-dotselect-digit="${bit}" aria-pressed="${s.bv===bit}">AN${bit}<small>编号 ${bit.toString(2).padStart(2,'0')}</small></button>`).join('')}</div><div class="an-dotselect-route" data-dotselect-route><span>M${group}：编号bit0=${s.bv&1}<br>选组内第${s.bv&1}路</span><i>→</i><span>M2：编号bit1=${group}<br>选${group?'高':'低'}组</span><i>→</i><span>请求${request}<br>NOT → dp=${1-request}</span></div><p data-dotselect-explanation>AN${s.bv} 请求=${request} → dp=${1-request}：${request?'发出点亮请求':'不请求点亮'}。本层没有AN使能输入，因此不能据此判断实体小数点已经亮起。</p><button data-dotselect-expand="M${group}">展开当前组 M${group} →</button><button data-dotselect-expand="INV">展开极性转换 →</button><small>这是组合选择路径；改变输入立即重新计算，不增加时钟。金色按钮标出选位，圆点只表示请求。</small></section>`;
}

function anatomyIdealRXLens(s){
 const count=s.rxPhase>=0?Math.min(s.rxPhase,8):(s.rxValid||s.rxError?8:0),next=s.rxPhase<0?'等待起始位0':s.rxPhase<8?'采样数据位d'+s.rxPhase:'检查停止位1';
 return `<section class="an-ideal-rx-lens"><h4>接收器：只展示实际采到的位</h4><p data-rx-next>下一次采样：${next}。当前RX=${s.a}。</p><div class="an-uart-loop-bits">${Array.from({length:8},(_,i)=>{const bit=7-i;return `<span data-rx-received-bit="${bit}" data-known="${bit<count}"><small>d${bit}</small>${bit<count?(s.rxData>>>bit)&1:'·'}</span>`}).join('')}</div><p data-rx-accepted>本帧已采数据 ${count}/8；组装寄存器=${s.rxData}。VALID=${s.rxValid}，ERROR=${s.rxError}。</p><div class="an-rx-verdict" role="status">${s.rxValid?'停止位为1：本次接收有效。':s.rxError?'停止位为0：本帧无效；组装值不能作为有效字节使用。':s.rxPhase===8?'八个数据位已收齐，但还不是有效帧；下一次必须检查停止位。':s.rxPhase<0?'等待新起始；寄存器可能保留旧值，不能当作新收到的字节。':'正在接收；未采到的位显示·，不是已收到0。'}</div><div class="an-timing-presets"><button data-rx-drive-sample="0">送0并采样一次</button><button data-rx-drive-sample="1">送1并采样一次</button></div><ol><li>先送0并采样，确认起始位。</li><li>按d0到d7依次送八个数据位，每位采样一次。</li><li>送1并采样，检查停止位；只有此时VALID才可变1。</li></ol><small>本层假设每次按钮已经对准一个理想位的采样点；不完成异步同步或位中心定位。VALID/ERROR仅持续到下一次采样，组装寄存器可以保留旧值。需要时进入下方两级同步与8倍采样模型。</small></section>`;
}

function anatomyMemoryReadReplay(s){
 const r=s.memoryAccess;if(!r||r.kind!=='read')return '';const offset=r.address&1,base=r.address&~1,hex=v=>'0x'+v.toString(16).padStart(2,'0');
 return `<section class="an-memory-read-replay"><h5>回看已执行的地址${r.address}读取</h5><svg viewBox="0 0 300 286" role="img" aria-label="已记录访问地址${r.address}，${r.hit?'命中':'缺失回填'}，偏移${offset}返回${r.value}"><g data-memory-read-stage="0"><rect x="15" y="8" width="270" height="42" rx="8" fill="#203e50" stroke="#8eb8bf"/><text x="150" y="25" text-anchor="middle">① 查行${r.index} · TAG=${r.address>>>3}</text><text x="150" y="42" text-anchor="middle">${r.hit?'命中：有效且标签匹配':r.oldTag===null?'冷缺失：该行原来无效':'冲突缺失：替换旧TAG='+r.oldTag}</text></g><path d="M150 50V66m-5 -6 5 6 5 -6" fill="none" stroke="#c4b57f"/><g data-memory-read-stage="1"><rect x="15" y="70" width="270" height="45" rx="8" fill="${r.hit?'#293842':'#274c48'}" stroke="#8eb8bf"/><text x="150" y="88" text-anchor="middle">② ${r.hit?'跳过后备读取，使用缓存块':'从后备地址'+base+'、'+(base+1)+'回填'}</text><text x="150" y="106" text-anchor="middle">两个已保存字节：${hex(r.bytes[0])} · ${hex(r.bytes[1])}</text></g><path d="M150 115V131m-5 -6 5 6 5 -6" fill="none" stroke="#c4b57f"/><g data-memory-read-stage="2"><text x="150" y="149" text-anchor="middle">③ OFFSET=${offset}，选择一个字节</text>${r.bytes.map((v,i)=>`<rect x="${35+i*125}" y="157" width="105" height="38" rx="7" fill="${i===offset?'#65562e':'#203e50'}" stroke="${i===offset?'#ffe29a':'#6a8b9d'}"/><text x="${87+i*125}" y="181" text-anchor="middle" data-memory-read-byte="${i}" data-chosen="${i===offset}">${hex(v)}</text>`).join('')}</g><path d="M150 197V214m-5 -6 5 6 5 -6" fill="none" stroke="#c4b57f"/><g data-memory-read-stage="3"><rect x="50" y="219" width="200" height="43" rx="15" fill="#244b40" stroke="#7ecdb0"/><text x="150" y="245" text-anchor="middle">④ 返回 ${r.value}（${hex(r.value)}）</text></g></svg><button data-memory-read-replay data-observe-section>↻ 回放这次访问</button><small data-memory-read-replay-status role="status">只强调已执行记录；讲解顺序不代表硬件周期或传播时间，不再次读取/回填。</small></section>`;
}
function mountAnatomyMemoryReadReplay(host){
 const panel=host.querySelector('.an-memory-read-replay');if(!panel)return;let epoch=0;
 panel.querySelector('[data-memory-read-replay]').onclick=()=>{const current=++epoch;panel.getAnimations({subtree:true}).forEach(a=>a.cancel());const status=panel.querySelector('[data-memory-read-replay-status]');if(matchMedia('(prefers-reduced-motion: reduce)').matches){status.textContent='减少动态效果：保留静态记录，没有执行访问。';return}status.textContent='回放已记录的访问；没有推进操作或改写缓存。';const animations=[...panel.querySelectorAll('[data-memory-read-stage]')].map((node,i)=>node.animate([{opacity:.35},{opacity:1,offset:.35},{opacity:1}],{duration:550,delay:i*450,fill:'none'}));Promise.all(animations.map(a=>a.finished)).then(()=>{if(panel.isConnected&&epoch===current)status.textContent='回放结束；请求、缓存、返回值和操作次数均未改变。'}).catch(()=>{});};
}

function anatomyMemoryAccessReport(b,s,table){
 if(b.id!=='memorySystem')return '';const r=s.memoryAccess,read=s.memoryLastRead;
 return '<section data-report-memory-access><h2>请求与已执行访问</h2>'+table(['项目','记录值'],[['当前请求地址（不表示已访问）',s.addr],['待写数据（不表示已写入）',s.data],['上次实际读取来源',read?'地址'+read.address+' → '+read.value+'，'+(read.hit?'命中':'缺失回填'):'尚无实际读取，输出0为初值']])+(!r?'<p>尚未执行读写。</p>':r.kind==='write'?table(['最近操作','地址','提交值','失效行'],[['写后备存储',r.address,r.value,r.index]]):table(['读取地址','索引行','TAG','OFFSET','命中','原TAG','记录块字节','返回值'],[[r.address,r.index,r.address>>>3,r.address&1,r.hit?1:0,r.oldTag===null?'无效':r.oldTag,r.bytes.join(', '),r.value]]))+'<p>以上来自实际保存记录。讲解顺序不表示真实硬件周期；本报告不再次读取或回填。</p></section>';
}

function anatomyCacheTagHardwareLink(b){return ['cachecheck','tageq5'].includes(b.id)?'<section class="an-cache-tag-hardware"><a href="labs/cache-tag-hit.zip" download>下载五位TAG门级RTL、2048组验证与VCD ↓</a><p>包含逐位XOR/NOT、AND合并与VALID；不包含完整缓存回填/数据阵列。功能仿真已对照，不代表实际FPGA时序或上板完成。</p></section>':'';}

function anatomyTagBitsLens(b,s){
 if(!['cachecheck','tageq5'].includes(b.id))return '';const diff=s.av^s.bv,equal=diff===0;
 return `<section class="an-tag-bits"><h4>逐位比较完整五位TAG</h4><div class="an-tag-bit-grid"><span>位 / 权重</span>${[4,3,2,1,0].map(bit=>`<small>bit${bit}<br>${1<<bit}</small>`).join('')}${[['av','请求'],['bv','保存']].map(([key,label])=>`<span>${label}</span>${[4,3,2,1,0].map(bit=>`<button data-tag-input-bit="${key}:${bit}" aria-pressed="${!!(s[key]&(1<<bit))}" aria-label="翻转${label}TAG的bit${bit}，权重${1<<bit}，当前${(s[key]>>>bit)&1}">${(s[key]>>>bit)&1}</button>`).join('')}`).join('')}<span>逐位结果</span>${[4,3,2,1,0].map(bit=>`<b data-tag-equal-bit="${bit}" data-equal="${!(diff&(1<<bit))}">${diff&(1<<bit)?'不同':'相同'}</b>`).join('')}</div><p data-tag-bit-summary>请求 ${s.av.toString(2).padStart(5,'0')} = ${s.av}；保存 ${s.bv.toString(2).padStart(5,'0')} = ${s.bv}。${equal?'五位全部相同，EQ=1。':'至少一位不同，EQ=0。'}${b.id==='cachecheck'?'VALID='+s.enable+'，因此HIT='+(+equal&s.enable)+'。相等但无效仍不命中。':'EQ只比较TAG，不包含VALID。'}</p><button data-tag-copy-request>将本层保存TAG设为请求TAG</button><small>这里只改变独立比较输入，不写入上级缓存、存储器或有效位。五个XOR并行比较，不是五次采样。</small></section>`;
}

function anatomyDemorganLens(b,s){
 if(b.lab!=='demorgan')return '';const nand=b.id==='demorganNand',formula=nand?'¬(A ∧ B) = ¬A ∨ ¬B':'¬(A ∨ B) = ¬A ∧ ¬B';
 return `<section class="an-demorgan-lens"><h4>${formula}</h4><p>取反进入括号时，既要分别反相输入，也要交换AND与OR。</p><table><thead><tr><th>输入</th><th>原式</th><th>变换式</th><th>对照</th></tr></thead><tbody>${[0,1,2,3].map(word=>{const a=word>>>1,b=word&1,left=nand?+(a*b===0):+(a+b===0),right=nand?+(!a||!b):+(!a&&!b);return `<tr data-demorgan-truth="${word}" ${a===s.a&&b===s.b?'aria-current="true"':''}><td><button data-demorgan-case="${word}">A=${a}, B=${b}</button></td><td>${left}</td><td>${right}</td><td>${left===right?'相同':'不同'}</td></tr>`}).join('')}</tbody></table><p>点击一行，把同一组A/B同时送到两条电路；再点击门，继续查看它的实际输入。四行覆盖二输入的全部组合。</p><small>两条分支并行计算，阅读顺序不增加时钟。等价只描述逻辑输出，不直接保证门数量、综合资源或物理延迟相同。</small></section>`;
}

function anatomyTruth2Lens(b,s){
 if(b.id!=='truth2')return '';const p=anatomyTruth2Plan(s);
 return `<section class="an-demorgan-lens"><h4>① 定义函数 → ② 施加输入 → ③ 观察支路</h4><p>修改Y定义电路；选择A/B只是测试当前函数。两种操作独立，不需要时钟。</p><table><thead><tr><th>测试输入 A/B</th><th>函数表 Y（点击翻转）</th><th>最小项</th><th>当前支路</th></tr></thead><tbody>${[0,1,2,3].map(i=>`<tr data-truth-row="${i}" ${p.row===i?'aria-current="true"':''}><td><button data-truth-case="${i}">${i>>>1} / ${i&1}</button></td><td><button data-truth-bit="${i}" aria-label="翻转输入${i>>>1}${i&1}的函数输出" aria-pressed="${!!(s.truthMask&(1<<i))}">${(s.truthMask>>>i)&1}</button></td><td>${['¬A·¬B','¬A·B','A·¬B','A·B'][i]}</td><td>${p.row===i?((s.truthMask>>>i)&1?'选中并通过':'选中但配置关闭'):'未选中'}</td></tr>`).join('')}</tbody></table><p>${[[0,'常量0'],[15,'常量1'],[6,'XOR'],[8,'AND'],[14,'OR'],[7,'NAND'],[1,'NOR']].map(([mask,label])=>`<button data-truth-preset="${mask}">${label}</button>`).join(' ')}</p><p>标准与或式：<strong>${p.expression}</strong><br>等价简式：<strong>${p.simplified}</strong><br><span data-truth-result>当前 m${p.row}=1，Y=${p.output}</span></p><small>上图始终显示四条可配置最小项支路；简式用于对照，不会悄悄改接上图。颜色与线上数值反映实际逻辑值。可双击门查看其输入及内部结构。</small></section>`;
}
